INSERT INTO recipe_catalog (id, name, category, cuisine, emoji, description, steps, ingredients, methods, flavors, meal_types, estimated_minutes, servings, serving_size, kcal, protein, carbs, fat, protein_per100g, carbs_per100g, fat_per100g, image_key, source, source_url, search_text) VALUES
('2470997b-5b54-5ebf-b0c0-7a8011d9bbfe', 'biangbiang面', '家常菜', 'shan', '🍜', '一根面条宽似裤带，筋道耐嚼，油泼辣子一浇，蒜香醋香直冲鼻腔，咸阳人的心头好。', '["面粉加盐和凉水揉成光滑面团，醒面 30 分钟后搓条，抹油分成小剂子再醒 20 分钟。", "取面剂子压扁抻长，边摔打边拉成宽约 5 厘米的长面条。", "水开下面，煮 2 分钟捞出沥干，码入碗中放辣椒面、蒜末、葱花。", "烧热油浇在辣椒面上激出香味，加香醋、生抽、盐拌匀即可。"]'::jsonb, '[{"name": "高筋面粉", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "辣椒面", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "葱花", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '350 g', '690', '28', '98', '21', '8', '28', '6', NULL, 'A', NULL, 'biangbiang面 家常菜 shan 一根面条宽似裤带，筋道耐嚼，油泼辣子一浇，蒜香醋香直冲鼻腔，咸阳人的心头好。 面粉加盐和凉水揉成光滑面团，醒面 30 分钟后搓条，抹油分成小剂子再醒 20 分钟。 取面剂子压扁抻长，边摔打边拉成宽约 5 厘米的长面条。 水开下面，煮 2 分钟捞出沥干，码入碗中放辣椒面、蒜末、葱花。 烧热油浇在辣椒面上激出香味，加香醋、生抽、盐拌匀即可。 煮 酸辣 午餐 晚餐 高筋面粉 辣椒面 蒜末 葱花 香醋 生抽 盐 食用油'),
('2738bb41-0855-54bc-ac47-05331eabe119', '一品锅', '家常菜', '徽菜', '🍲', '绩溪胡适家宴名菜，层层码放蛋饺、肉圆、鸡块、笋干，炭火慢炖，一锅汇聚荤素百味，热腾腾端上桌。', '["笋干提前泡发切段，与鸡块分别焯水去浮沫。", "砂锅底部铺笋干和豆腐泡，再逐层码入鸡块、蛋饺、肉圆、火腿片。", "倒入没过食材的高汤，加姜片，小火加盖慢炖 40 分钟。", "揭盖加盐调味，再炖 5 分钟，连锅上桌。"]'::jsonb, '[{"name": "鸡块", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蛋饺", "quantity": "8", "quantityPrefix": null, "unit": "只", "note": null, "sourceText": null}, {"name": "肉圆", "quantity": "6", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "笋干", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "豆腐泡", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "火腿片", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜片", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['炖']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '400 g', '580', '40', '24', '36', '10', '6', '9', NULL, 'A', NULL, '一品锅 家常菜 徽菜 绩溪胡适家宴名菜，层层码放蛋饺、肉圆、鸡块、笋干，炭火慢炖，一锅汇聚荤素百味，热腾腾端上桌。 笋干提前泡发切段，与鸡块分别焯水去浮沫。 砂锅底部铺笋干和豆腐泡，再逐层码入鸡块、蛋饺、肉圆、火腿片。 倒入没过食材的高汤，加姜片，小火加盖慢炖 40 分钟。 揭盖加盐调味，再炖 5 分钟，连锅上桌。 炖 咸鲜 晚餐 鸡块 蛋饺 肉圆 笋干 豆腐泡 火腿片 姜片 盐'),
('216f1c91-2356-5178-b3c4-f76147b88533', '丁丁炒面', '家常菜', '新疆菜', '🥢', '拉条子切成小丁和羊肉丁、菜丁同炒，面丁入味、一勺一勺停不下来。', '["拉面煮熟捞出，切成 1 厘米小丁；羊肉、洋葱、青红椒、番茄全部切丁。", "热油下羊肉丁煸炒至变色，加洋葱丁炒香。", "下番茄丁炒出汁，再下青红椒丁翻炒 1 分钟。", "倒入面丁，加盐、孜然粉、生抽大火炒 1 分钟即可。"]'::jsonb, '[{"name": "拉面", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "羊肉", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "青红椒", "quantity": "1", "quantityPrefix": "各", "unit": "个", "note": null, "sourceText": null}, {"name": "洋葱", "quantity": "0.5", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "番茄", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "孜然粉", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['炒']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '740', '32', '108', '20', '8', '27', '5', NULL, 'A', NULL, '丁丁炒面 家常菜 新疆菜 拉条子切成小丁和羊肉丁、菜丁同炒，面丁入味、一勺一勺停不下来。 拉面煮熟捞出，切成 1 厘米小丁；羊肉、洋葱、青红椒、番茄全部切丁。 热油下羊肉丁煸炒至变色，加洋葱丁炒香。 下番茄丁炒出汁，再下青红椒丁翻炒 1 分钟。 倒入面丁，加盐、孜然粉、生抽大火炒 1 分钟即可。 炒 咸鲜 午餐 晚餐 拉面 羊肉 青红椒 洋葱 番茄 孜然粉 生抽 食用油'),
('198c137e-e26c-5a27-8fc8-65f1a13421ed', '三合汤', '家常菜', '湘菜', '🍜', '娄底新化名汤，牛肉、牛肚、牛血一锅烩，山胡椒油点睛，酸辣鲜香开胃。', '["牛肉切薄片，牛肚切条，牛血切块焯水。", "热油下姜蒜、泡椒炒香，倒入牛肉、牛肚翻炒至变色。", "加开水大火煮 3 分钟，下牛血再煮 2 分钟。", "加盐调味，淋山胡椒油，撒葱花出锅。"]'::jsonb, '[{"name": "黄牛肉", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "熟牛肚", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "牛血", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "山胡椒油", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "酸泡椒", "quantity": "6", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "姜", "quantity": "1", "quantityPrefix": null, "unit": "块", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "5", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "葱", "quantity": "2", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}]'::jsonb, ARRAY['烩']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '528', '40', '20', '32', '10', '5', '8', NULL, 'A', NULL, '三合汤 家常菜 湘菜 娄底新化名汤，牛肉、牛肚、牛血一锅烩，山胡椒油点睛，酸辣鲜香开胃。 牛肉切薄片，牛肚切条，牛血切块焯水。 热油下姜蒜、泡椒炒香，倒入牛肉、牛肚翻炒至变色。 加开水大火煮 3 分钟，下牛血再煮 2 分钟。 加盐调味，淋山胡椒油，撒葱花出锅。 烩 酸辣 午餐 晚餐 黄牛肉 熟牛肚 牛血 山胡椒油 酸泡椒 姜 蒜 葱'),
('64dcbd64-c1ba-5579-8b31-41dc6d50a695', '三文鱼杂粮饭', '增肌', '通用', '🍱', '三文鱼的 Omega-3 与杂粮慢碳强强联合，增肌又护心的营养大碗。', '["三文鱼两面抹盐和黑胡椒，平底锅少油每面煎 2–3 分钟。", "西兰花焯水 1 分钟；牛油果去皮切片。", "杂粮饭盛碗打底，摆上煎好的三文鱼。", "码入牛油果和西兰花，撒海苔碎，挤柠檬汁即可。"]'::jsonb, '[{"name": "三文鱼", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "杂粮饭", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": "（熟）", "sourceText": null}, {"name": "牛油果", "quantity": "0.5", "quantityPrefix": null, "unit": "个", "note": "（约 70 克）", "sourceText": null}, {"name": "西兰花", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "海苔碎", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "柠檬", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}]'::jsonb, ARRAY['煎']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '500 g', '692', '40', '61', '32', '8', '12.2', '6.4', NULL, 'A', NULL, '三文鱼杂粮饭 增肌 通用 三文鱼的 omega-3 与杂粮慢碳强强联合，增肌又护心的营养大碗。 三文鱼两面抹盐和黑胡椒，平底锅少油每面煎 2–3 分钟。 西兰花焯水 1 分钟；牛油果去皮切片。 杂粮饭盛碗打底，摆上煎好的三文鱼。 码入牛油果和西兰花，撒海苔碎，挤柠檬汁即可。 煎 咸鲜 午餐 晚餐 三文鱼 杂粮饭 牛油果 西兰花 海苔碎 柠檬'),
('d27984fc-b43c-50ec-9912-8ab2b9bfe7bb', '三文鱼菠菜烘蛋', '营养', '通用', '🍳', '三文鱼优质脂肪酸搭配新鲜菠菜与散养鸡蛋，无粉烘烤，兼具卵磷脂与丰富矿物质。', '["菠菜沸水焯水挤干水分切段；小番茄对半切开。", "鸡蛋打入碗中，加牛奶、海盐和黑胡椒搅打均匀。", "耐热烤碗刷橄榄油，铺入菠菜、三文鱼碎和小番茄。", "倒入蛋液，烤箱 180 度烤 18 分钟至蛋液完全凝固金黄蓬松。"]'::jsonb, '[{"name": "三文鱼碎", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡蛋", "quantity": "3", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "菠菜", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "小番茄", "quantity": "4", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "脱脂牛奶", "quantity": "20", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}, {"name": "橄榄油", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黑胡椒、海盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['烘焙', '煎']::TEXT[], ARRAY['鲜香']::TEXT[], ARRAY['早餐', '午餐']::TEXT[], NULL, NULL, '320 g', '440', '39', '8', '28', '12.2', '2.5', '8.8', NULL, 'A', NULL, '三文鱼菠菜烘蛋 营养 通用 三文鱼优质脂肪酸搭配新鲜菠菜与散养鸡蛋，无粉烘烤，兼具卵磷脂与丰富矿物质。 菠菜沸水焯水挤干水分切段；小番茄对半切开。 鸡蛋打入碗中，加牛奶、海盐和黑胡椒搅打均匀。 耐热烤碗刷橄榄油，铺入菠菜、三文鱼碎和小番茄。 倒入蛋液，烤箱 180 度烤 18 分钟至蛋液完全凝固金黄蓬松。 烘焙 煎 鲜香 早餐 午餐 三文鱼碎 鸡蛋 菠菜 小番茄 脱脂牛奶 橄榄油 黑胡椒、海盐'),
('8192e307-7ea5-566c-a1e1-252d19996d3c', '三杯鸡', '家常菜', '粤菜', '🍶', '台菜经典，米酒、酱油、麻油各一杯，九层塔点睛咸香回甘。', '["鸡腿肉剁块，冷水下锅焯 2 分钟捞出沥干。", "锅中倒麻油，小火煸姜片至微焦卷曲，约 3 分钟。", "下蒜瓣爆香，倒鸡块中火翻炒 3 分钟至表面金黄。", "淋入米酒和生抽，加冰糖，大火烧开转中小火焖 12 分钟。", "开大火收汁至浓稠，关火前撒九层塔翻匀即可。"]'::jsonb, '[{"name": "鸡腿肉", "quantity": "400", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "米酒", "quantity": "0.5", "quantityPrefix": null, "unit": "杯", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "0.5", "quantityPrefix": null, "unit": "杯", "note": null, "sourceText": null}, {"name": "麻油", "quantity": "0.5", "quantityPrefix": null, "unit": "杯", "note": null, "sourceText": null}, {"name": "姜", "quantity": "1", "quantityPrefix": null, "unit": "块", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "6", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "九层塔", "quantity": "1", "quantityPrefix": null, "unit": "把", "note": null, "sourceText": null}, {"name": "冰糖", "quantity": "2", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}]'::jsonb, ARRAY['焖']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '450 g', '616', '50', '32', '32', '11', '7', '7', NULL, 'A', NULL, '三杯鸡 家常菜 粤菜 台菜经典，米酒、酱油、麻油各一杯，九层塔点睛咸香回甘。 鸡腿肉剁块，冷水下锅焯 2 分钟捞出沥干。 锅中倒麻油，小火煸姜片至微焦卷曲，约 3 分钟。 下蒜瓣爆香，倒鸡块中火翻炒 3 分钟至表面金黄。 淋入米酒和生抽，加冰糖，大火烧开转中小火焖 12 分钟。 开大火收汁至浓稠，关火前撒九层塔翻匀即可。 焖 咸鲜 晚餐 鸡腿肉 米酒 生抽 麻油 姜 蒜 九层塔 冰糖'),
('3cfdf6b8-68d0-574d-b1b2-4ec65ce59886', '三河小炒', '家常菜', '徽菜', '🥗', '三河古镇家常炒菜，肉丝、豆干丝、韭黄、青椒多料合炒，锅气足、色泽亮，咸鲜微辣最下饭。', '["豆干切丝，韭黄切段，青椒切丝备用。", "热油下肉丝滑炒至变色盛出。", "下豆干丝煸香，放青椒丝和韭黄大火快炒。", "倒回肉丝，加生抽和盐炒匀出锅。"]'::jsonb, '[{"name": "猪里脊丝", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "豆干", "quantity": "2", "quantityPrefix": null, "unit": "块", "note": null, "sourceText": null}, {"name": "韭黄", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "青椒", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "菜籽油", "quantity": "20", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['炒']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '250 g', '318', '15', '25', '18', '6', '10', '7', NULL, 'A', NULL, '三河小炒 家常菜 徽菜 三河古镇家常炒菜，肉丝、豆干丝、韭黄、青椒多料合炒，锅气足、色泽亮，咸鲜微辣最下饭。 豆干切丝，韭黄切段，青椒切丝备用。 热油下肉丝滑炒至变色盛出。 下豆干丝煸香，放青椒丝和韭黄大火快炒。 倒回肉丝，加生抽和盐炒匀出锅。 炒 咸鲜 午餐 晚餐 猪里脊丝 豆干 韭黄 青椒 生抽 菜籽油 盐'),
('0349a878-004b-587a-9ed0-099e6f4906aa', '三河米饺', '小吃', '徽菜', '🥟', '三河古镇名点，籼米粉和面擀皮，包入豆腐干、肉末和虾米馅，油炸至金黄，外酥内糯、鲜香可口。', '["豆腐干切丁，与肉末、虾米、葱姜末炒成馅，加盐和生抽调味。", "籼米粉用开水烫熟揉成团，分剂擀成圆皮。", "包入馅料捏成月牙形饺，收口捏紧。", "油烧至六成热，下米饺炸至两面金黄浮起，捞出沥油。"]'::jsonb, '[{"name": "籼米粉", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "豆腐干", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "猪肉末", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "虾米", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "葱姜末", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "菜籽油", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['炸']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['早餐', '午餐']::TEXT[], NULL, NULL, '150 g', '324', '9', '45', '12', '6', '30', '8', NULL, 'A', NULL, '三河米饺 小吃 徽菜 三河古镇名点，籼米粉和面擀皮，包入豆腐干、肉末和虾米馅，油炸至金黄，外酥内糯、鲜香可口。 豆腐干切丁，与肉末、虾米、葱姜末炒成馅，加盐和生抽调味。 籼米粉用开水烫熟揉成团，分剂擀成圆皮。 包入馅料捏成月牙形饺，收口捏紧。 油烧至六成热，下米饺炸至两面金黄浮起，捞出沥油。 炸 咸鲜 早餐 午餐 籼米粉 豆腐干 猪肉末 虾米 葱姜末 盐 生抽 菜籽油'),
('a74bb626-037c-5188-93ec-deef645772b8', '三皮丝', '家常菜', 'shan', '🥗', '猪皮、鸡皮、海蜇皮切细丝，蒜醋汁一拌，脆韧相间，是陕西冷盘里的功夫菜。', '["猪皮、鸡皮切细丝，海蜇皮泡去咸味后同样切丝。", "三种丝分别焯水，海蜇丝过冰水保持脆感，捞出沥干。", "蒜末加香醋、生抽、盐、辣椒油调成料汁。", "三丝同碗，浇料汁拌匀即可。"]'::jsonb, '[{"name": "熟猪皮", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "熟鸡皮", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "海蜇皮", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '200 g', '340', '32', '8', '20', '16', '4', '10', NULL, 'A', NULL, '三皮丝 家常菜 shan 猪皮、鸡皮、海蜇皮切细丝，蒜醋汁一拌，脆韧相间，是陕西冷盘里的功夫菜。 猪皮、鸡皮切细丝，海蜇皮泡去咸味后同样切丝。 三种丝分别焯水，海蜇丝过冰水保持脆感，捞出沥干。 蒜末加香醋、生抽、盐、辣椒油调成料汁。 三丝同碗，浇料汁拌匀即可。 凉拌 酸辣 午餐 晚餐 熟猪皮 熟鸡皮 海蜇皮 蒜末 香醋 生抽 辣椒油 盐'),
('40f725cf-0c99-52bc-aa99-c17b06ab08d0', '三色虾仁', '家常菜', '通用', '🍤', '虾仁鲜嫩弹牙，玉米豌豆胡萝卜三色清甜，少油蒸制健康清爽。', '["虾仁用盐、白胡椒粉、淀粉抓匀腌制 10 分钟；葱切花。", "三色杂菜加少许盐、油拌匀，平铺在盘底。", "虾仁整齐铺在杂菜上，撒葱花。", "蒸锅上汽后放入，大火蒸 8 分钟至虾仁变红即可。"]'::jsonb, '[{"name": "虾仁", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "玉米粒", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "豌豆", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "胡萝卜丁", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}, {"name": "白胡椒粉", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}, {"name": "淀粉", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}]'::jsonb, ARRAY['蒸']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '250 g', '207', '25', '20', '3', '10', '8', '1', NULL, 'A', NULL, '三色虾仁 家常菜 通用 虾仁鲜嫩弹牙，玉米豌豆胡萝卜三色清甜，少油蒸制健康清爽。 虾仁用盐、白胡椒粉、淀粉抓匀腌制 10 分钟；葱切花。 三色杂菜加少许盐、油拌匀，平铺在盘底。 虾仁整齐铺在杂菜上，撒葱花。 蒸锅上汽后放入，大火蒸 8 分钟至虾仁变红即可。 蒸 清淡 午餐 晚餐 虾仁 玉米粒 豌豆 胡萝卜丁 盐 白胡椒粉 淀粉 葱'),
('211165dc-6c60-5689-bf87-c0f5a44bb779', '三鲜汤', '家常菜', '通用', '🍤', '虾仁火腿蘑菇三鲜齐聚，清汤鲜美，家宴常用。', '["虾仁开背去虾线，火腿切丝，香菇切片，豆腐切块。", "锅中水烧开，下姜片、火腿丝、香菇片煮 3 分钟。", "下豆腐块煮 2 分钟，再下虾仁煮 1 分钟至变色。", "加盐调味，撒葱花即可。"]'::jsonb, '[{"name": "鲜虾仁", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "火腿", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鲜香菇", "quantity": "4", "quantityPrefix": null, "unit": "朵", "note": null, "sourceText": null}, {"name": "嫩豆腐", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['鲜香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '600 g', '193', '19', '9', '9', '3.2', '1.5', '1.5', NULL, 'A', NULL, '三鲜汤 家常菜 通用 虾仁火腿蘑菇三鲜齐聚，清汤鲜美，家宴常用。 虾仁开背去虾线，火腿切丝，香菇切片，豆腐切块。 锅中水烧开，下姜片、火腿丝、香菇片煮 3 分钟。 下豆腐块煮 2 分钟，再下虾仁煮 1 分钟至变色。 加盐调味，撒葱花即可。 煮 鲜香 午餐 晚餐 鲜虾仁 火腿 鲜香菇 嫩豆腐 姜 小葱 盐'),
('33f12db2-cfa5-5a5a-8df8-b4ef298c93a4', '三鲜豆皮', '小吃', 'e', '🍳', '绿豆米浆摊皮，铺糯米浇三鲜臊子，煎得金黄焦香，武汉「过早」经典。', '["绿豆、大米泡 4 小时磨浆；糯米蒸熟。", "肉末炒散，加香菇丁、豆干丁、生抽炒成三鲜臊子。", "平底锅刷油摊米浆成皮，磕蛋抹匀翻面。", "铺糯米饭，浇臊子压平，煎至底面金黄翻面再煎 2 分钟，切块。"]'::jsonb, '[{"name": "绿豆", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "大米", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "糯米", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "猪肉末", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "香菇", "quantity": "4", "quantityPrefix": null, "unit": "朵", "note": null, "sourceText": null}, {"name": "豆干", "quantity": "1", "quantityPrefix": null, "unit": "块", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "鸡蛋", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}]'::jsonb, ARRAY['煎']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['早餐']::TEXT[], NULL, NULL, '180 g', '414', '13', '50', '18', '7', '28', '10', NULL, 'A', NULL, '三鲜豆皮 小吃 e 绿豆米浆摊皮，铺糯米浇三鲜臊子，煎得金黄焦香，武汉「过早」经典。 绿豆、大米泡 4 小时磨浆；糯米蒸熟。 肉末炒散，加香菇丁、豆干丁、生抽炒成三鲜臊子。 平底锅刷油摊米浆成皮，磕蛋抹匀翻面。 铺糯米饭，浇臊子压平，煎至底面金黄翻面再煎 2 分钟，切块。 煎 咸鲜 早餐 绿豆 大米 糯米 猪肉末 香菇 豆干 生抽 鸡蛋'),
('f4a751a8-f822-5cae-84a0-7982f1f63637', '上汤娃娃菜', '家常菜', '粤菜', '🥬', '皮蛋咸蛋黄熬出的金黄鲜汤，娃娃菜吸饱汤汁，鲜到掉眉。', '["娃娃菜对半切开洗净；皮蛋和咸蛋黄切小丁。", "热锅倒油，下蒜瓣小火煎至金黄，放入皮蛋丁、咸蛋黄丁炒出沙。", "倒入高汤烧开，下娃娃菜，中火煮 4 分钟至菜帮透明变软。", "加盐调味，连汤带菜盛出即可。"]'::jsonb, '[{"name": "娃娃菜", "quantity": "400", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "皮蛋", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": "（约 60 克）", "sourceText": null}, {"name": "咸蛋黄", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": "（约 15 克）", "sourceText": null}, {"name": "蒜瓣", "quantity": "4", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "高汤", "quantity": "300", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "8", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['煲汤']::TEXT[], ARRAY['鲜香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '470 g', '288', '13', '14', '20', '2.8', '3', '4.3', 'recipes/images/a05b627440bbbb059fea.jpg', 'A', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/vegetable_dish/%E4%B8%8A%E6%B1%A4%E5%A8%83%E5%A8%83%E8%8F%9C/%E4%B8%8A%E6%B1%A4%E5%A8%83%E5%A8%83%E8%8F%9C.md', '上汤娃娃菜 家常菜 粤菜 皮蛋咸蛋黄熬出的金黄鲜汤，娃娃菜吸饱汤汁，鲜到掉眉。 娃娃菜对半切开洗净；皮蛋和咸蛋黄切小丁。 热锅倒油，下蒜瓣小火煎至金黄，放入皮蛋丁、咸蛋黄丁炒出沙。 倒入高汤烧开，下娃娃菜，中火煮 4 分钟至菜帮透明变软。 加盐调味，连汤带菜盛出即可。 煲汤 鲜香 午餐 晚餐 娃娃菜 皮蛋 咸蛋黄 蒜瓣 高汤 食用油'),
('9fb9b861-de5d-5196-8dfa-0ecfc3841ee9', '上汤菠菜', '减脂', '通用', '🥬', '菠菜配高汤蒜末同煮，去草酸更易吸收铁质，清淡暖胃。', '["菠菜洗净，沸水焯 30 秒去草酸，捞出沥干。", "蒜切末，锅中放橄榄油爆香蒜末。", "倒入高汤烧开，下菠菜煮 1 分钟。", "加盐调味，撒枸杞出锅即可。"]'::jsonb, '[{"name": "菠菜", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "枸杞", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "高汤", "quantity": "300", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}, {"name": "橄榄油", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '450 g', '125', '9', '11', '5', '2', '2.5', '1.2', NULL, 'A', NULL, '上汤菠菜 减脂 通用 菠菜配高汤蒜末同煮，去草酸更易吸收铁质，清淡暖胃。 菠菜洗净，沸水焯 30 秒去草酸，捞出沥干。 蒜切末，锅中放橄榄油爆香蒜末。 倒入高汤烧开，下菠菜煮 1 分钟。 加盐调味，撒枸杞出锅即可。 煮 清淡 晚餐 菠菜 蒜 枸杞 高汤 橄榄油 盐'),
('48861abd-e4e6-5237-a612-d570d451fe97', '东北乱炖', '家常菜', '东北菜', '🥘', '土豆、豆角、茄子、青椒配五花肉一锅乱炖，越炖越香，一锅顶一桌。', '["五花肉切片，土豆切块，豆角掰段，茄子手撕大块，青椒切块。", "热油下五花肉煸出油，加姜片、葱段、大酱炒香。", "下土豆、豆角、茄子翻炒 3 分钟，加热水没过食材。", "炖 20 分钟至土豆绵软，下青椒再炖 5 分钟即可。"]'::jsonb, '[{"name": "五花肉", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "土豆", "quantity": "2", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "豆角", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "茄子", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "青椒", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "东北大酱", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "姜", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "葱", "quantity": "1", "quantityPrefix": null, "unit": "段", "note": null, "sourceText": null}]'::jsonb, ARRAY['炖']::TEXT[], ARRAY['酱香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '350 g', '425', '18', '32', '25', '5', '9', '7', NULL, 'A', NULL, '东北乱炖 家常菜 东北菜 土豆、豆角、茄子、青椒配五花肉一锅乱炖，越炖越香，一锅顶一桌。 五花肉切片，土豆切块，豆角掰段，茄子手撕大块，青椒切块。 热油下五花肉煸出油，加姜片、葱段、大酱炒香。 下土豆、豆角、茄子翻炒 3 分钟，加热水没过食材。 炖 20 分钟至土豆绵软，下青椒再炖 5 分钟即可。 炖 酱香 午餐 晚餐 五花肉 土豆 豆角 茄子 青椒 东北大酱 姜 葱'),
('19e2ff6f-6bff-5795-b9f6-b7e961be079c', '东北大拉皮', '小吃', '东北菜', '🥒', '拉皮晶莹筋道，配黄瓜丝、胡萝卜丝浇上麻酱蒜汁，酸辣爽滑。', '["拉皮切宽条，凉开水冲洗后沥干；黄瓜、胡萝卜切丝，香菜切段。", "麻酱加生抽、香醋、蒜末和少许凉开水澥开调匀。", "拉皮和蔬菜丝放大碗，浇上调好的麻酱汁。", "拌匀即可，爽滑酸辣。"]'::jsonb, '[{"name": "拉皮", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "胡萝卜", "quantity": "0.5", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "香菜", "quantity": "1", "quantityPrefix": null, "unit": "把", "note": null, "sourceText": null}, {"name": "麻酱", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '250 g', '250', '5', '35', '10', '2', '14', '4', NULL, 'A', NULL, '东北大拉皮 小吃 东北菜 拉皮晶莹筋道，配黄瓜丝、胡萝卜丝浇上麻酱蒜汁，酸辣爽滑。 拉皮切宽条，凉开水冲洗后沥干；黄瓜、胡萝卜切丝，香菜切段。 麻酱加生抽、香醋、蒜末和少许凉开水澥开调匀。 拉皮和蔬菜丝放大碗，浇上调好的麻酱汁。 拌匀即可，爽滑酸辣。 凉拌 酸辣 午餐 晚餐 拉皮 黄瓜 胡萝卜 香菜 麻酱 蒜 生抽 香醋'),
('2810ba57-f12e-5230-8e42-94a5c60959e9', '东北饭包', '家常菜', '东北菜', '🌯', '大白菜叶包上米饭、土豆泥和鸡蛋酱，捧在手心大口啃，豪爽又管饱。', '["土豆去皮切块蒸熟，压成土豆泥；鸡蛋加酱炒成鸡蛋酱。", "大白菜叶洗净擦干，铺平。", "米饭、土豆泥、鸡蛋酱、小葱段、香菜段拌匀。", "用白菜叶包紧，大口开吃。"]'::jsonb, '[{"name": "大米饭", "quantity": "2", "quantityPrefix": null, "unit": "碗", "note": null, "sourceText": null}, {"name": "大白菜叶", "quantity": "4", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "土豆", "quantity": "2", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "鸡蛋", "quantity": "2", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "东北大酱", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "3", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "香菜", "quantity": "1", "quantityPrefix": null, "unit": "把", "note": null, "sourceText": null}, {"name": "食用油", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['蒸']::TEXT[], ARRAY['酱香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '462', '15', '60', '18', '5', '20', '6', NULL, 'A', NULL, '东北饭包 家常菜 东北菜 大白菜叶包上米饭、土豆泥和鸡蛋酱，捧在手心大口啃，豪爽又管饱。 土豆去皮切块蒸熟，压成土豆泥；鸡蛋加酱炒成鸡蛋酱。 大白菜叶洗净擦干，铺平。 米饭、土豆泥、鸡蛋酱、小葱段、香菜段拌匀。 用白菜叶包紧，大口开吃。 蒸 酱香 午餐 晚餐 大米饭 大白菜叶 土豆 鸡蛋 东北大酱 小葱 香菜 食用油'),
('8c5c3660-9f8a-5c13-919d-5916a9075bfc', '东安子鸡', '家常菜', '湘菜', '🍗', '八大湘菜之首，嫩鸡切小条，酸辣汁快炒，醋香突出、微酸微辣，鸡肉弹嫩。', '["整鸡煮 15 分钟至七成熟，捞出晾凉，斩成 2 厘米长的小条。", "干辣椒剪段，姜切细丝，小米辣切圈。", "热油下姜丝、花椒、干辣椒炒香，倒入鸡条大火翻炒。", "烹入香醋、料酒，下小米辣再炒 2 分钟，加盐调味撒葱段出锅。"]'::jsonb, '[{"name": "三黄鸡", "quantity": "1", "quantityPrefix": null, "unit": "只", "note": "（约 1000 克）", "sourceText": null}, {"name": "干辣椒", "quantity": "10", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "姜", "quantity": "1", "quantityPrefix": null, "unit": "块", "note": null, "sourceText": null}, {"name": "小米辣", "quantity": "5", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "4", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "花椒", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "葱", "quantity": "2", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}]'::jsonb, ARRAY['炒']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '576', '48', '24', '32', '12', '6', '8', NULL, 'A', NULL, '东安子鸡 家常菜 湘菜 八大湘菜之首，嫩鸡切小条，酸辣汁快炒，醋香突出、微酸微辣，鸡肉弹嫩。 整鸡煮 15 分钟至七成熟，捞出晾凉，斩成 2 厘米长的小条。 干辣椒剪段，姜切细丝，小米辣切圈。 热油下姜丝、花椒、干辣椒炒香，倒入鸡条大火翻炒。 烹入香醋、料酒，下小米辣再炒 2 分钟，加盐调味撒葱段出锅。 炒 酸辣 午餐 晚餐 三黄鸡 干辣椒 姜 小米辣 香醋 料酒 花椒 葱'),
('4360bb14-3cea-51d6-874f-290ccc53b80f', '丝瓜炒蛋', '保持', '通用', '🥒', '丝瓜清甜多汁，裹着嫩滑蛋块，清淡爽口又下饭的夏日家常菜。', '["丝瓜去皮切滚刀块，鸡蛋打散，蒜切片。", "热锅放油，倒入蛋液中火炒至刚凝固盛出。", "余油爆香蒜片，下丝瓜块中火翻炒 2 分钟至变软出水。", "倒回鸡蛋，加盐炒匀，中火再焖 1 分钟，撒葱花出锅。"]'::jsonb, '[{"name": "丝瓜", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡蛋", "quantity": "2", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "6", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "2", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}]'::jsonb, ARRAY['炒']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['早餐', '午餐']::TEXT[], NULL, NULL, '380 g', '250', '16', '12', '15', '4.2', '3.2', '3.9', NULL, 'A', NULL, '丝瓜炒蛋 保持 通用 丝瓜清甜多汁，裹着嫩滑蛋块，清淡爽口又下饭的夏日家常菜。 丝瓜去皮切滚刀块，鸡蛋打散，蒜切片。 热锅放油，倒入蛋液中火炒至刚凝固盛出。 余油爆香蒜片，下丝瓜块中火翻炒 2 分钟至变软出水。 倒回鸡蛋，加盐炒匀，中火再焖 1 分钟，撒葱花出锅。 炒 清淡 早餐 午餐 丝瓜 鸡蛋 食用油 蒜 盐 小葱'),
('1749f61b-de26-577e-b322-c6fa1d1f355f', '丝瓜虾仁汤', '保持', '通用', '🍤', '丝瓜清甜滑嫩，虾仁弹鲜，豆腐增香，一锅清爽的夏日靓汤。', '["丝瓜去皮切滚刀块，虾仁用料酒腌 5 分钟，嫩豆腐切块。", "锅中放油爆香姜片，下丝瓜翻炒 1 分钟。", "加三碗开水，下豆腐块煮 3 分钟。", "下虾仁煮 2 分钟至变色，加盐和白胡椒，撒葱花出锅。"]'::jsonb, '[{"name": "丝瓜", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "虾仁", "quantity": "120", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "嫩豆腐", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "盐、白胡椒", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '550 g', '265', '32', '14', '9', '5.8', '2.5', '1.6', NULL, 'A', NULL, '丝瓜虾仁汤 保持 通用 丝瓜清甜滑嫩，虾仁弹鲜，豆腐增香，一锅清爽的夏日靓汤。 丝瓜去皮切滚刀块，虾仁用料酒腌 5 分钟，嫩豆腐切块。 锅中放油爆香姜片，下丝瓜翻炒 1 分钟。 加三碗开水，下豆腐块煮 3 分钟。 下虾仁煮 2 分钟至变色，加盐和白胡椒，撒葱花出锅。 煮 清淡 晚餐 丝瓜 虾仁 嫩豆腐 姜 小葱 食用油 盐、白胡椒'),
('13be0d9a-75f7-56d6-bfdf-b24740b24fc0', '丝瓜虾皮汤', '减脂', '通用', '🍲', '丝瓜清甜虾皮提鲜，加蛋花增蛋白，清淡暖胃的一碗汤。', '["丝瓜去皮切滚刀块，虾皮冲洗一下沥干。", "锅中烧开两碗水，放姜片和虾皮煮 2 分钟出鲜味。", "下丝瓜块，中火煮 5 分钟至变软。", "鸡蛋打散淋入锅中，煮至蛋花浮起，加盐调味，滴香油撒葱花出锅。"]'::jsonb, '[{"name": "丝瓜", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": "（约 250 克）", "sourceText": null}, {"name": "虾皮", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡蛋", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "姜", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "香油", "quantity": "2", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '400 g', '150', '13', '11', '6', '3.25', '2.75', '1.5', NULL, 'A', NULL, '丝瓜虾皮汤 减脂 通用 丝瓜清甜虾皮提鲜，加蛋花增蛋白，清淡暖胃的一碗汤。 丝瓜去皮切滚刀块，虾皮冲洗一下沥干。 锅中烧开两碗水，放姜片和虾皮煮 2 分钟出鲜味。 下丝瓜块，中火煮 5 分钟至变软。 鸡蛋打散淋入锅中，煮至蛋花浮起，加盐调味，滴香油撒葱花出锅。 煮 清淡 晚餐 丝瓜 虾皮 鸡蛋 姜 小葱 盐 香油'),
('978d74d2-1b95-5a2c-9db1-41b7db240d59', '丝瓜蛋汤', '家常菜', '通用', '🥒', '丝瓜清甜滑嫩，蛋花鲜美，三分钟出锅的夏日快手汤。', '["丝瓜去皮切滚刀块，用淡盐水浸泡防止氧化变黑。", "鸡蛋打散备用，葱切葱花。", "锅中水烧开，下姜片和丝瓜块煮 3 分钟。", "转小火淋入蛋液，用筷子轻推成蛋花。", "加盐和香油调味，撒葱花即可。"]'::jsonb, '[{"name": "丝瓜", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": "（约 350 克）", "sourceText": null}, {"name": "鸡蛋", "quantity": "2", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "姜", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "香油", "quantity": null, "quantityPrefix": null, "unit": "几滴", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '650 g', '155', '9', '14', '7', '1.4', '2.2', '1', NULL, 'A', NULL, '丝瓜蛋汤 家常菜 通用 丝瓜清甜滑嫩，蛋花鲜美，三分钟出锅的夏日快手汤。 丝瓜去皮切滚刀块，用淡盐水浸泡防止氧化变黑。 鸡蛋打散备用，葱切葱花。 锅中水烧开，下姜片和丝瓜块煮 3 分钟。 转小火淋入蛋液，用筷子轻推成蛋花。 加盐和香油调味，撒葱花即可。 煮 清淡 午餐 晚餐 丝瓜 鸡蛋 小葱 姜 香油 盐'),
('91610650-3ab9-5256-a5ae-1e8aa2249779', '丝瓜豆腐汤', '营养', '通用', '🍲', '丝瓜清甜、豆腐嫩滑，少油清淡的养生汤，补水又补蛋白。', '["丝瓜去皮切滚刀块，豆腐切小块。", "锅中加两碗水，放姜片和虾皮煮开。", "下丝瓜煮 4 分钟，再下豆腐煮 3 分钟。", "加盐调味，淋香油出锅。"]'::jsonb, '[{"name": "丝瓜", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": "（约 250 克）", "sourceText": null}, {"name": "嫩豆腐", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "虾皮", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "香油", "quantity": "3", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '400 g', '164', '9', '14', '8', '2.2', '3.5', '2', NULL, 'A', NULL, '丝瓜豆腐汤 营养 通用 丝瓜清甜、豆腐嫩滑，少油清淡的养生汤，补水又补蛋白。 丝瓜去皮切滚刀块，豆腐切小块。 锅中加两碗水，放姜片和虾皮煮开。 下丝瓜煮 4 分钟，再下豆腐煮 3 分钟。 加盐调味，淋香油出锅。 煮 清淡 晚餐 丝瓜 嫩豆腐 虾皮 姜 香油 盐'),
('1f75a641-26f8-538b-bc28-ce9786f0e134', '中式馅饼', '家常菜', '通用', '🍽️', '', '["准备原料", "取肉沫（解冻），加入 1/2 所有上述调料（油、盐、糖、酱油、风味调料）和全部的生粉，搅拌均匀，腌制 30 分钟。", "将面粉加入碗中，加入鸡蛋，加入剩下 1/2 所有上述调料，加入相当于面粉 1/2 的水（使得面粉相对粘稠但可以流动），搅拌均匀。", "蒜头切为蒜末。", "大葱切段。", "胡萝卜切末（作为馅料用，所以要求尽量细碎，可用乱刀）", "烹饪", "热锅冷油，宽油起锅。", "待油烧热后，放入蒜末爆香。", "加入腌制的肉沫，翻炒，直至断生。", "将胡萝卜末加入肉沫中一同翻炒，直至油被染为金黄色（这是为了萃取胡萝卜的风味）。", "关火。冷却 2 分钟。", "将炒好的肉沫倒入生面糊中，搅匀。", "重新开火，平底锅铺底油。", "调至小火，将面糊倒入锅中均匀铺满。保证厚度不要过高。可以端起锅，让面糊流过锅底来完成这一操作。", "在饼的表面尚为液态时，撒上大葱段。", "保持小火，直到底面凝固。", "将饼翻面，继续小火煎烤，直至另一侧凝固。", "之后，每一面再额外煎 20 秒。", "关火出锅。"]'::jsonb, '[{"name": "面粉 200g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "面粉 200g"}, {"name": "肉沫 50g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "肉沫 50g"}, {"name": "油 30ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "油 30ml"}, {"name": "盐 3g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐 3g"}, {"name": "糖 5g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "糖 5g"}, {"name": "生粉 10g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "生粉 10g"}, {"name": "酱油 5g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "酱油 5g"}, {"name": "风味调料 3g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "风味调料 3g"}, {"name": "蒜头 2 瓣", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "蒜头 2 瓣"}, {"name": "大葱 1/4 根（靠叶部分）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "大葱 1/4 根（靠叶部分）"}, {"name": "鸡蛋 （可选，1 个）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "鸡蛋 （可选，1 个）"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/staple/%E4%B8%AD%E5%BC%8F%E9%A6%85%E9%A5%BC/%E4%B8%AD%E5%BC%8F%E9%A6%85%E9%A5%BC.md', '中式馅饼 家常菜 通用 准备原料 取肉沫（解冻），加入 1/2 所有上述调料（油、盐、糖、酱油、风味调料）和全部的生粉，搅拌均匀，腌制 30 分钟。 将面粉加入碗中，加入鸡蛋，加入剩下 1/2 所有上述调料，加入相当于面粉 1/2 的水（使得面粉相对粘稠但可以流动），搅拌均匀。 蒜头切为蒜末。 大葱切段。 胡萝卜切末（作为馅料用，所以要求尽量细碎，可用乱刀） 烹饪 热锅冷油，宽油起锅。 待油烧热后，放入蒜末爆香。 加入腌制的肉沫，翻炒，直至断生。 将胡萝卜末加入肉沫中一同翻炒，直至油被染为金黄色（这是为了萃取胡萝卜的风味）。 关火。冷却 2 分钟。 将炒好的肉沫倒入生面糊中，搅匀。 重新开火，平底锅铺底油。 调至小火，将面糊倒入锅中均匀铺满。保证厚度不要过高。可以端起锅，让面糊流过锅底来完成这一操作。 在饼的表面尚为液态时，撒上大葱段。 保持小火，直到底面凝固。 将饼翻面，继续小火煎烤，直至另一侧凝固。 之后，每一面再额外煎 20 秒。 关火出锅。 午餐 晚餐 面粉 200g 肉沫 50g 油 30ml 盐 3g 糖 5g 生粉 10g 酱油 5g 风味调料 3g 蒜头 2 瓣 大葱 1/4 根（靠叶部分） 鸡蛋 （可选，1 个）'),
('e58894a8-07d4-5ea5-a566-278826901801', '丸子汤', '家常菜', '新疆菜', '🍲', '昌吉招牌，牛肉丸配冻豆腐、粉条烩进骨汤，丸子弹、汤头鲜。', '["牛肉馅加鸡蛋、淀粉、姜末、盐顺一个方向搅打上劲。", "锅中水烧至微开，挤入丸子煮至浮起，撇去浮沫。", "下冻豆腐块、泡软的粉条煮 8 分钟。", "加盐、白胡椒调味，撒香菜出锅。"]'::jsonb, '[{"name": "牛肉馅", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "冻豆腐", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "粉条", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡蛋", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "淀粉", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "姜末", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香菜", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "盐、白胡椒", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['鲜香']::TEXT[], ARRAY['早餐', '午餐']::TEXT[], NULL, NULL, '600 g', '678', '54', '48', '30', '9', '8', '5', NULL, 'A', NULL, '丸子汤 家常菜 新疆菜 昌吉招牌，牛肉丸配冻豆腐、粉条烩进骨汤，丸子弹、汤头鲜。 牛肉馅加鸡蛋、淀粉、姜末、盐顺一个方向搅打上劲。 锅中水烧至微开，挤入丸子煮至浮起，撇去浮沫。 下冻豆腐块、泡软的粉条煮 8 分钟。 加盐、白胡椒调味，撒香菜出锅。 煮 鲜香 早餐 午餐 牛肉馅 冻豆腐 粉条 鸡蛋 淀粉 姜末 香菜 盐、白胡椒'),
('f6a2f749-a2b6-5101-b64d-19b882085fb0', '丽江腊排骨火锅', '家常菜', '滇菜', '🍖', '腊香浓郁的排骨久炖出白汤，配萝卜番茄越煮越鲜，丽江冬夜的暖锅担当。', '["腊排骨斩块，温水浸泡 1 小时去咸，冷水下锅焯 5 分钟。", "排骨入砂锅，加姜片、花椒、葱段和足量热水，大火烧开转小火炖 40 分钟。", "下白萝卜块、西红柿块再炖 20 分钟。", "尝味后酌情加盐，连汤带肉上桌，可涮菜。"]'::jsonb, '[{"name": "腊排骨", "quantity": "400", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "白萝卜", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "西红柿", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "姜片", "quantity": "4", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "花椒", "quantity": "10", "quantityPrefix": null, "unit": "粒", "note": null, "sourceText": null}, {"name": "葱段", "quantity": "2", "quantityPrefix": null, "unit": "段", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['火锅']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '600 g', '954', '66', '24', '66', '11', '4', '11', NULL, 'A', NULL, '丽江腊排骨火锅 家常菜 滇菜 腊香浓郁的排骨久炖出白汤，配萝卜番茄越煮越鲜，丽江冬夜的暖锅担当。 腊排骨斩块，温水浸泡 1 小时去咸，冷水下锅焯 5 分钟。 排骨入砂锅，加姜片、花椒、葱段和足量热水，大火烧开转小火炖 40 分钟。 下白萝卜块、西红柿块再炖 20 分钟。 尝味后酌情加盐，连汤带肉上桌，可涮菜。 火锅 咸鲜 午餐 晚餐 腊排骨 白萝卜 西红柿 姜片 花椒 葱段 盐'),
('f2b36e1a-4465-5bdd-a52c-ebf8d779a012', '乡村啤酒鸭', '家常菜', '通用', '🍽️', '', '["鸭肉焯水以去腥去血水", "鸭肉清洗一遍放进锅中", "加清水淹没鸭肉", "加 20 ml 料酒", "加备用的 1 根 大葱", "加生姜 ,拍散的 2 厘米", "开火烧滚", "捞出浮沫", "鸭肉捞出，清水洗干净备用", "开始煮", "锅清洗干净烧热，加 60ml 的花生油", "油温到 60 度的时候，加一把花椒（ 30 颗）", "加鸭肉翻炒 4 分钟", "- 2 分钟后加入所有的香料", "- 3 分钟的时候加入所有的料头（生姜，大蒜，小米辣）", "加入 1000 ml 的啤酒", "烧鸭肉 30 分钟", "- 10 分钟的时候加 盐 （3 克） 生抽( 10 ml ) 老抽( 5 ml)", "- 20 分钟 加入所有的辅料 （青椒和红椒段）", "- 29 分钟加入 蒜苗段 和 大葱段", "- 翻炒 1 分钟", "出锅"]'::jsonb, '[{"name": "鸭肉（半只,1 kg,让市场老板剁成小块）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "鸭肉（半只,1 kg,让市场老板剁成小块）"}, {"name": "啤酒 1000 ml （可以买 500 ml 的罐装啤酒两瓶）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "啤酒 1000 ml （可以买 500 ml 的罐装啤酒两瓶）"}, {"name": "青椒 2 条，红椒 1 条 （ 长度 10 厘米到 15 厘米 之间都可以）（切段 或者切片都可以， 2 厘米一段）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "青椒 2 条，红椒 1 条 （ 长度 10 厘米到 15 厘米 之间都可以）（切段 或者切片都可以， 2 厘米一段）"}, {"name": "大蒜 4 颗 ,拍散备用", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "大蒜 4 颗 ,拍散备用"}, {"name": "生姜 3 厘米长，拍散备用", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "生姜 3 厘米长，拍散备用"}, {"name": "小米辣 3 颗，切两段即可(不吃辣的可以不用", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "小米辣 3 颗，切两段即可(不吃辣的可以不用"}, {"name": "蒜苗 2 根 切段备用", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "蒜苗 2 根 切段备用"}, {"name": "大葱 2 根 1 根切段,1 根备用", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "大葱 2 根  1 根切段,1 根备用"}, {"name": "草果 两颗，拍散去仔备用", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "草果 两颗，拍散去仔备用"}, {"name": "桂皮 4 厘米一小片", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "桂皮 4 厘米一小片"}, {"name": "八角 3 颗", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "八角 3 颗"}, {"name": "香叶 3 片", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "香叶 3 片"}, {"name": "干辣椒 6 条 (不吃辣可以不用", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "干辣椒 6 条 (不吃辣可以不用"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/meat_dish/%E4%B9%A1%E6%9D%91%E5%95%A4%E9%85%92%E9%B8%AD.md', '乡村啤酒鸭 家常菜 通用 鸭肉焯水以去腥去血水 鸭肉清洗一遍放进锅中 加清水淹没鸭肉 加 20 ml 料酒 加备用的 1 根 大葱 加生姜 ,拍散的 2 厘米 开火烧滚 捞出浮沫 鸭肉捞出，清水洗干净备用 开始煮 锅清洗干净烧热，加 60ml 的花生油 油温到 60 度的时候，加一把花椒（ 30 颗） 加鸭肉翻炒 4 分钟 - 2 分钟后加入所有的香料 - 3 分钟的时候加入所有的料头（生姜，大蒜，小米辣） 加入 1000 ml 的啤酒 烧鸭肉 30 分钟 - 10 分钟的时候加 盐 （3 克） 生抽( 10 ml ) 老抽( 5 ml) - 20 分钟 加入所有的辅料 （青椒和红椒段） - 29 分钟加入 蒜苗段 和 大葱段 - 翻炒 1 分钟 出锅 午餐 晚餐 鸭肉（半只,1 kg,让市场老板剁成小块） 啤酒 1000 ml （可以买 500 ml 的罐装啤酒两瓶） 青椒 2 条，红椒 1 条 （ 长度 10 厘米到 15 厘米 之间都可以）（切段 或者切片都可以， 2 厘米一段） 大蒜 4 颗 ,拍散备用 生姜 3 厘米长，拍散备用 小米辣 3 颗，切两段即可(不吃辣的可以不用 蒜苗 2 根 切段备用 大葱 2 根 1 根切段,1 根备用 草果 两颗，拍散去仔备用 桂皮 4 厘米一小片 八角 3 颗 香叶 3 片 干辣椒 6 条 (不吃辣可以不用'),
('7a40cf86-a562-55df-aecf-311bf19449a4', '乡村欧包', '烘焙', '通用', '🥖', '无油低糖的粗犷欧包，外皮硬脆内里湿润有嚼劲，麦香纯粹适合抹黄油或蘸汤。', '["所有材料混合成团，盖布静置 30 分钟，折叠拉伸四角一次，间隔 30 分钟重复 3-4 次。", "面团冷藏发酵 12-18 小时至明显膨胀。", "取出回温 1 小时，整形成圆形，放在铺面粉的发酵布上二次发酵 1 小时。", "转移到烤盘表面割口，放入预热 230°C 烤箱，底部放一盘热水制造蒸汽烤 30 分钟。", "出炉敲击底部有空洞声即熟透，晾凉后切片。"]'::jsonb, '[{"name": "高筋面粉", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "全麦面粉", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "水", "quantity": "210", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "盐", "quantity": "6", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干酵母", "quantity": "1", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "橄榄油", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['烘焙']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['早餐', '午餐']::TEXT[], NULL, NULL, '80 片', '185', '7', '37', '1', '9', '46', '1', NULL, 'A', NULL, '乡村欧包 烘焙 通用 无油低糖的粗犷欧包，外皮硬脆内里湿润有嚼劲，麦香纯粹适合抹黄油或蘸汤。 所有材料混合成团，盖布静置 30 分钟，折叠拉伸四角一次，间隔 30 分钟重复 3-4 次。 面团冷藏发酵 12-18 小时至明显膨胀。 取出回温 1 小时，整形成圆形，放在铺面粉的发酵布上二次发酵 1 小时。 转移到烤盘表面割口，放入预热 230°c 烤箱，底部放一盘热水制造蒸汽烤 30 分钟。 出炉敲击底部有空洞声即熟透，晾凉后切片。 烘焙 清淡 早餐 午餐 高筋面粉 全麦面粉 水 盐 干酵母 橄榄油'),
('e5250223-5712-5215-aecb-38ca3c4fc189', '乾州锅盔', '家常菜', 'shan', '🫓', '大如锅盖、厚似盾牌的烤饼，外脆内暄，麦香十足，夹辣子夹肉都香。', '["面粉加酵母、盐和温水揉成面团，醒发至两倍大。", "面团擀成大圆饼，表面刷水撒芝麻，用牙签扎孔防鼓泡。", "平底锅小火，饼入锅加盖烙 8 分钟，翻面再烙 8 分钟至两面金黄。", "出炉晾凉切块，可夹菜夹肉食用。"]'::jsonb, '[{"name": "面粉", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "酵母", "quantity": "3", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "温水", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['煎']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '200 g', '505', '18', '90', '8', '9', '45', '4', NULL, 'A', NULL, '乾州锅盔 家常菜 shan 大如锅盖、厚似盾牌的烤饼，外脆内暄，麦香十足，夹辣子夹肉都香。 面粉加酵母、盐和温水揉成面团，醒发至两倍大。 面团擀成大圆饼，表面刷水撒芝麻，用牙签扎孔防鼓泡。 平底锅小火，饼入锅加盖烙 8 分钟，翻面再烙 8 分钟至两面金黄。 出炉晾凉切块，可夹菜夹肉食用。 煎 咸鲜 午餐 晚餐 面粉 酵母 温水 盐 食用油'),
('1f5e09cc-693e-5940-88fb-0de089b3df1f', '乾隆白菜', '家常菜', '通用', '🍽️', '', '["大白菜只取内部嫩叶（黄色部分），去除菜帮，用手撕成半个巴掌大的块，不要用刀切（手撕截面粗糙更易挂酱）", "将撕好的白菜叶冲洗干净，充分控干水分，水分残留会导致酱汁无法挂附", "碗中加入 30g 芝麻酱，先加入 45ml 陈醋，沿同一方向搅拌，将麻酱慢慢稀释开，直至成细线状滴落为止（切勿来回搅拌，会导致芝麻酱\"走油\"）", "向麻酱汁中加入 5g 白糖，搅拌均匀；再加入 1g 食盐，搅拌均匀；最后加入 5ml 香油，搅拌均匀（各调料需分次加入并分别搅拌，边加边感受稀稠度）", "将调好的麻酱汁均匀淋在白菜叶上，用手轻轻抓拌，使每片菜叶都裹上酱汁", "撒上熟白芝麻，装盘即可食用；若时间充裕，可静置 5 分钟待其入味后再食用"]'::jsonb, '[{"name": "大白菜嫩叶 300g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "大白菜嫩叶 300g"}, {"name": "芝麻酱 30g（约 2 汤匙）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "芝麻酱 30g（约 2 汤匙）"}, {"name": "陈醋 45ml（约 3 汤匙，醋与麻酱比例约 3:2）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "陈醋 45ml（约 3 汤匙，醋与麻酱比例约 3:2）"}, {"name": "白糖 5g（约 1 茶匙）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "白糖 5g（约 1 茶匙）"}, {"name": "香油 5ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "香油 5ml"}, {"name": "食盐 1g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "食盐 1g"}, {"name": "熟白芝麻 3g（可选）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "熟白芝麻 3g（可选）"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'recipes/images/e9b1f03369e37ab35e66.jpg', 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/vegetable_dish/%E4%B9%BE%E9%9A%86%E7%99%BD%E8%8F%9C/%E4%B9%BE%E9%9A%86%E7%99%BD%E8%8F%9C.md', '乾隆白菜 家常菜 通用 大白菜只取内部嫩叶（黄色部分），去除菜帮，用手撕成半个巴掌大的块，不要用刀切（手撕截面粗糙更易挂酱） 将撕好的白菜叶冲洗干净，充分控干水分，水分残留会导致酱汁无法挂附 碗中加入 30g 芝麻酱，先加入 45ml 陈醋，沿同一方向搅拌，将麻酱慢慢稀释开，直至成细线状滴落为止（切勿来回搅拌，会导致芝麻酱"走油"） 向麻酱汁中加入 5g 白糖，搅拌均匀；再加入 1g 食盐，搅拌均匀；最后加入 5ml 香油，搅拌均匀（各调料需分次加入并分别搅拌，边加边感受稀稠度） 将调好的麻酱汁均匀淋在白菜叶上，用手轻轻抓拌，使每片菜叶都裹上酱汁 撒上熟白芝麻，装盘即可食用；若时间充裕，可静置 5 分钟待其入味后再食用 午餐 晚餐 大白菜嫩叶 300g 芝麻酱 30g（约 2 汤匙） 陈醋 45ml（约 3 汤匙，醋与麻酱比例约 3:2） 白糖 5g（约 1 茶匙） 香油 5ml 食盐 1g 熟白芝麻 3g（可选）'),
('655bc220-8a62-5fd7-acad-1be99b0450b2', '五红汤', '食疗', '通用', '🍲', '红豆红枣红皮花生枸杞红糖，补血养气经典五红。', '["红豆、红皮花生提前浸泡 2 小时，红枣去核。", "红豆、花生加清水大火烧开，转小火煮 40 分钟至开花。", "下红枣、红糖再煮 15 分钟，关火撒枸杞焖 5 分钟。"]'::jsonb, '[{"name": "红豆", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "红枣", "quantity": "6", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "红皮花生", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "枸杞", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "红糖", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "清水", "quantity": "900", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['甜']::TEXT[], ARRAY['早餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '279', '9', '54', '3', '3', '18', '1', NULL, 'A', NULL, '五红汤 食疗 通用 红豆红枣红皮花生枸杞红糖，补血养气经典五红。 红豆、红皮花生提前浸泡 2 小时，红枣去核。 红豆、花生加清水大火烧开，转小火煮 40 分钟至开花。 下红枣、红糖再煮 15 分钟，关火撒枸杞焖 5 分钟。 煮 甜 早餐 晚餐 红豆 红枣 红皮花生 枸杞 红糖 清水'),
('2f930d3c-e4cb-575b-a94d-458145dc4bde', '五香卷', '家常菜', '闽菜', '🌯', '闽南炸五香，豆皮裹肉馅，外酥内嫩，宴席冷盘常客。', '["前腿肉切小丁，马蹄、洋葱切碎，与五香粉、生抽、地瓜粉拌匀成馅。", "豆皮铺开，放上馅料卷紧成圆筒状，收口处抹水粘牢。", "卷好的五香卷上锅蒸 10 分钟定型。", "切段，入六成热油中炸至金黄酥脆，沥油装盘。"]'::jsonb, '[{"name": "猪前腿肉", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "豆皮", "quantity": "2", "quantityPrefix": null, "unit": "张", "note": null, "sourceText": null}, {"name": "马蹄", "quantity": "5", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "洋葱", "quantity": "0.5", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "五香粉", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "地瓜粉", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['蒸', '炸']::TEXT[], ARRAY['五香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '180 g', '296', '16', '22', '16', '9', '12', '9', NULL, 'A', NULL, '五香卷 家常菜 闽菜 闽南炸五香，豆皮裹肉馅，外酥内嫩，宴席冷盘常客。 前腿肉切小丁，马蹄、洋葱切碎，与五香粉、生抽、地瓜粉拌匀成馅。 豆皮铺开，放上馅料卷紧成圆筒状，收口处抹水粘牢。 卷好的五香卷上锅蒸 10 分钟定型。 切段，入六成热油中炸至金黄酥脆，沥油装盘。 蒸 炸 五香 午餐 晚餐 猪前腿肉 豆皮 马蹄 洋葱 五香粉 生抽 地瓜粉'),
('4db403f2-1afe-5cd7-bca0-62fd19b62263', '京酱肉丝', '家常菜', '北方菜', '🌯', '甜面酱裹着嫩肉丝，配葱丝豆腐皮一卷，酱香浓郁的京味菜。', '["里脊切细丝，加料酒、淀粉、蛋清少许抓匀腌 10 分钟；葱白切细丝。", "豆腐皮切方块，沸水烫 30 秒捞出，与葱丝一起摆盘。", "热锅下油，下肉丝中火滑炒至变色盛出。", "锅中留底油，小火下甜面酱、白糖炒出酱香，倒回肉丝翻炒裹匀，盛在葱丝上。", "吃时用豆腐皮卷起肉丝和葱丝即可。"]'::jsonb, '[{"name": "猪里脊", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "甜面酱", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "大葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "豆腐皮", "quantity": "2", "quantityPrefix": null, "unit": "张", "note": null, "sourceText": null}, {"name": "白糖", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "姜", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['炒']::TEXT[], ARRAY['酱香', '咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '330 g', '571', '46', '30', '30', '14', '9', '9', NULL, 'A', NULL, '京酱肉丝 家常菜 北方菜 甜面酱裹着嫩肉丝，配葱丝豆腐皮一卷，酱香浓郁的京味菜。 里脊切细丝，加料酒、淀粉、蛋清少许抓匀腌 10 分钟；葱白切细丝。 豆腐皮切方块，沸水烫 30 秒捞出，与葱丝一起摆盘。 热锅下油，下肉丝中火滑炒至变色盛出。 锅中留底油，小火下甜面酱、白糖炒出酱香，倒回肉丝翻炒裹匀，盛在葱丝上。 吃时用豆腐皮卷起肉丝和葱丝即可。 炒 酱香 咸鲜 午餐 晚餐 猪里脊 甜面酱 大葱 豆腐皮 白糖 料酒 姜 食用油'),
('ab2794b3-51cc-5090-9a60-153eff974161', '什锦蛋炒饭', '家常菜', '通用', '🍛', '隔夜米饭大火炒散，蛋香裹着玉米豌豆胡萝卜与香肠丁，粒粒分明。', '["香肠切小丁；鸡蛋打散；米饭用勺子拨散备用。", "热锅倒油，下蛋液炒成蛋片盛出；锅留底油炒香香肠丁和杂菜。", "倒入米饭大火翻炒至粒粒松散，加盐和蛋片翻炒均匀即可。"]'::jsonb, '[{"name": "隔夜米饭", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡蛋", "quantity": "2", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "三色杂菜", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "香肠", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "盐", "quantity": "3", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "食用油", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['炒']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '712', '20', '104', '24', '5', '26', '6', NULL, 'A', NULL, '什锦蛋炒饭 家常菜 通用 隔夜米饭大火炒散，蛋香裹着玉米豌豆胡萝卜与香肠丁，粒粒分明。 香肠切小丁；鸡蛋打散；米饭用勺子拨散备用。 热锅倒油，下蛋液炒成蛋片盛出；锅留底油炒香香肠丁和杂菜。 倒入米饭大火翻炒至粒粒松散，加盐和蛋片翻炒均匀即可。 炒 咸鲜 午餐 晚餐 隔夜米饭 鸡蛋 三色杂菜 香肠 盐 食用油'),
('6eaa0a04-5352-5b9b-a1bf-dfed44ce47ac', '佛跳墙', '家常菜', '闽菜', '🫕', '闽菜之首，山珍海味荟于一坛，汤浓味醇，开坛香飘四邻。', '["鲍鱼、海参、花胶、干贝提前泡发，花菇温水泡软，全部改刀备用。", "老母鸡斩块与猪蹄筋、火腿分别焯水，去除浮沫洗净。", "取大坛，按耐煮到易熟分层码入蹄筋、花菇、火腿、鸡块、干贝，最上层放鲍鱼、海参、花胶。", "倒入高汤和福建老酒没过食材，坛口封上荷叶再盖盖子。", "小火煨 3 小时至汤汁浓稠、食材酥烂，上桌前掀盖撒少许葱花。"]'::jsonb, '[{"name": "鲍鱼", "quantity": "4", "quantityPrefix": null, "unit": "只", "note": null, "sourceText": null}, {"name": "海参", "quantity": "2", "quantityPrefix": null, "unit": "条", "note": null, "sourceText": null}, {"name": "花胶", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干贝", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "猪蹄筋", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "花菇", "quantity": "6", "quantityPrefix": null, "unit": "朵", "note": null, "sourceText": null}, {"name": "老母鸡", "quantity": "0.5", "quantityPrefix": null, "unit": "只", "note": null, "sourceText": null}, {"name": "金华火腿", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['炖']::TEXT[], ARRAY['鲜香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '250 g', '237', '20', '10', '13', '8', '4', '5', NULL, 'A', NULL, '佛跳墙 家常菜 闽菜 闽菜之首，山珍海味荟于一坛，汤浓味醇，开坛香飘四邻。 鲍鱼、海参、花胶、干贝提前泡发，花菇温水泡软，全部改刀备用。 老母鸡斩块与猪蹄筋、火腿分别焯水，去除浮沫洗净。 取大坛，按耐煮到易熟分层码入蹄筋、花菇、火腿、鸡块、干贝，最上层放鲍鱼、海参、花胶。 倒入高汤和福建老酒没过食材，坛口封上荷叶再盖盖子。 小火煨 3 小时至汤汁浓稠、食材酥烂，上桌前掀盖撒少许葱花。 炖 鲜香 午餐 晚餐 鲍鱼 海参 花胶 干贝 猪蹄筋 花菇 老母鸡 金华火腿'),
('401bd801-e939-5227-8f3c-8ab54152cb4e', '傣味舂鸡脚', '家常菜', '滇菜', '🍗', '石臼里舂出的酸辣鲜香，鸡脚弹韧入味，柠檬小米辣香菜一样不少。', '["鸡脚剪去指甲，冷水下锅煮 15 分钟至熟透，捞出冰镇 10 分钟。", "小米辣、蒜瓣、香菜根放入石臼，加盐舂碎出香。", "加入鸡脚、鱼露、白糖，挤入柠檬汁，继续舂压至入味。", "拌入香菜段，冷藏 20 分钟风味更佳。"]'::jsonb, '[{"name": "鸡脚", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "柠檬", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "小米辣", "quantity": "6", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "蒜瓣", "quantity": "5", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香菜", "quantity": "1", "quantityPrefix": null, "unit": "把", "note": null, "sourceText": null}, {"name": "鱼露", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "白糖", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮', '凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '456', '36', '24', '24', '12', '8', '8', NULL, 'A', NULL, '傣味舂鸡脚 家常菜 滇菜 石臼里舂出的酸辣鲜香，鸡脚弹韧入味，柠檬小米辣香菜一样不少。 鸡脚剪去指甲，冷水下锅煮 15 分钟至熟透，捞出冰镇 10 分钟。 小米辣、蒜瓣、香菜根放入石臼，加盐舂碎出香。 加入鸡脚、鱼露、白糖，挤入柠檬汁，继续舂压至入味。 拌入香菜段，冷藏 20 分钟风味更佳。 煮 凉拌 酸辣 午餐 晚餐 鸡脚 柠檬 小米辣 蒜瓣 香菜 鱼露 白糖'),
('806d8c93-8fa3-5159-acd0-668533203697', '傲椒风味翅尖', '小吃', '通用', '🍗', '鸡翅尖腌制后高温快炸，外壳焦脆、肉质弹韧，撒上麻辣料粉越啃越香。', '["翅尖洗净沥干，加生抽、料酒、少许盐抓匀，腌制 20 分钟。", "腌好的翅尖薄薄裹一层玉米淀粉，抖去多余粉。", "油温烧至 170℃ 下翅尖，中火炸 3 分钟至金黄浮起，捞出沥油。", "趁热撒上辣椒粉、花椒粉和盐，翻拌均匀即可。"]'::jsonb, '[{"name": "鸡翅尖", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "辣椒粉", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "花椒粉", "quantity": "0.5", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "盐", "quantity": "0.5", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "玉米淀粉", "quantity": "20", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "食用油", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['炸']::TEXT[], ARRAY['麻辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '120 g', '342', '19', '10', '25', '16', '8', '21', NULL, 'A', NULL, '傲椒风味翅尖 小吃 通用 鸡翅尖腌制后高温快炸，外壳焦脆、肉质弹韧，撒上麻辣料粉越啃越香。 翅尖洗净沥干，加生抽、料酒、少许盐抓匀，腌制 20 分钟。 腌好的翅尖薄薄裹一层玉米淀粉，抖去多余粉。 油温烧至 170℃ 下翅尖，中火炸 3 分钟至金黄浮起，捞出沥油。 趁热撒上辣椒粉、花椒粉和盐，翻拌均匀即可。 炸 麻辣 午餐 晚餐 鸡翅尖 生抽 料酒 辣椒粉 花椒粉 盐 玉米淀粉 食用油'),
('af24424f-bd2b-5ef0-89c2-eabe18e3b7e5', '全麦吐司', '烘焙', '通用', '🍞', '麦香浓郁的健康主食面包，组织扎实有嚼劲，早餐两片配蛋奶正合适。', '["除黄油外所有材料混合揉成光滑面团，加入软化的黄油继续揉至能拉出较薄手套膜。", "面团盖保鲜膜室温发酵至两倍大，约 1 小时。", "排气后分成 3 份滚圆松弛 15 分钟，擀卷两次放入吐司盒。", "二次发酵至模具八分满，约 50 分钟。", "放入预热 180°C 烤箱烤 35 分钟，出炉立即脱模侧放晾凉，切片食用。"]'::jsonb, '[{"name": "全麦面粉", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "高筋面粉", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "牛奶", "quantity": "180", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "细砂糖", "quantity": "20", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "盐", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干酵母", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄油", "quantity": "20", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['烘焙']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['早餐']::TEXT[], NULL, NULL, '60 片', '146', '6', '26', '2', '10', '44', '4', NULL, 'A', NULL, '全麦吐司 烘焙 通用 麦香浓郁的健康主食面包，组织扎实有嚼劲，早餐两片配蛋奶正合适。 除黄油外所有材料混合揉成光滑面团，加入软化的黄油继续揉至能拉出较薄手套膜。 面团盖保鲜膜室温发酵至两倍大，约 1 小时。 排气后分成 3 份滚圆松弛 15 分钟，擀卷两次放入吐司盒。 二次发酵至模具八分满，约 50 分钟。 放入预热 180°c 烤箱烤 35 分钟，出炉立即脱模侧放晾凉，切片食用。 烘焙 清淡 早餐 全麦面粉 高筋面粉 牛奶 细砂糖 盐 干酵母 黄油'),
('faab20e8-e2da-57f6-85af-896b914d7474', '八公山豆腐', '家常菜', '徽菜', '🍥', '淮南八公山豆腐细嫩洁白、久煮不碎，煎烧后外皮微焦、内里滑嫩，配鸡汤和虾籽提鲜，豆香浓郁。', '["豆腐切厚片，入油锅煎至两面金黄。", "下姜末炒香，倒入鸡汤和虾籽，加生抽。", "小火炖 8 分钟让豆腐吸饱汤汁，大火收汁撒葱花。"]'::jsonb, '[{"name": "八公山豆腐", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡汤", "quantity": "200", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}, {"name": "虾籽", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "菜籽油", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "姜末", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}]'::jsonb, ARRAY['煎', '炖']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '250 g', '278', '18', '13', '18', '7', '5', '7', NULL, 'A', NULL, '八公山豆腐 家常菜 徽菜 淮南八公山豆腐细嫩洁白、久煮不碎，煎烧后外皮微焦、内里滑嫩，配鸡汤和虾籽提鲜，豆香浓郁。 豆腐切厚片，入油锅煎至两面金黄。 下姜末炒香，倒入鸡汤和虾籽，加生抽。 小火炖 8 分钟让豆腐吸饱汤汁，大火收汁撒葱花。 煎 炖 咸鲜 午餐 晚餐 八公山豆腐 鸡汤 虾籽 菜籽油 生抽 姜末 小葱'),
('bb10a110-76fd-5f3a-9c4b-25c5505ded2f', '八宝粥', '家常菜', '北方菜', '🥣', '红豆花生莲子糯米熬一锅，软糯香甜，腊八节家常味。', '["红豆、花生和莲子提前浸泡 2 小时。", "所有米类和豆类入锅，加清水大火煮开。", "转小火熬 40 分钟至豆烂米开花。", "加冰糖和红枣，再熬 10 分钟至浓稠即可。"]'::jsonb, '[{"name": "大米", "quantity": "20", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "糯米", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "红豆", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "花生", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "莲子", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "红枣", "quantity": "3", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "冰糖", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "清水", "quantity": "550", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}]'::jsonb, ARRAY['熬粥']::TEXT[], ARRAY['甜']::TEXT[], ARRAY['早餐']::TEXT[], NULL, NULL, '600 g', '262', '6', '55', '2', '1', '9.2', '0.3', NULL, 'A', NULL, '八宝粥 家常菜 北方菜 红豆花生莲子糯米熬一锅，软糯香甜，腊八节家常味。 红豆、花生和莲子提前浸泡 2 小时。 所有米类和豆类入锅，加清水大火煮开。 转小火熬 40 分钟至豆烂米开花。 加冰糖和红枣，再熬 10 分钟至浓稠即可。 熬粥 甜 早餐 大米 糯米 红豆 花生 莲子 红枣 冰糖 清水'),
('ebd668d4-e168-520b-bbf2-baac401e2042', '六安腊鹅', '家常菜', '徽菜', '🦆', '六安传统腊味，白鹅经盐腌风干，腊香浓郁、肉质紧实，蒸熟斩件或炒蒜苗，咸香耐嚼。', '["腊鹅温水浸泡 1 小时去部分咸味，斩块。", "盘中码腊鹅块，铺姜丝淋料酒，大火蒸 30 分钟。", "蒜苗切段，用蒸出的鹅油快炒断生。", "腊鹅与蒜苗同炒，加白糖提鲜，出锅装盘。"]'::jsonb, '[{"name": "腊鹅", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜丝", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒜苗", "quantity": "2", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "白糖", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}]'::jsonb, ARRAY['蒸']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '200 g', '456', '36', '6', '32', '18', '3', '16', NULL, 'A', NULL, '六安腊鹅 家常菜 徽菜 六安传统腊味，白鹅经盐腌风干，腊香浓郁、肉质紧实，蒸熟斩件或炒蒜苗，咸香耐嚼。 腊鹅温水浸泡 1 小时去部分咸味，斩块。 盘中码腊鹅块，铺姜丝淋料酒，大火蒸 30 分钟。 蒜苗切段，用蒸出的鹅油快炒断生。 腊鹅与蒜苗同炒，加白糖提鲜，出锅装盘。 蒸 咸鲜 午餐 晚餐 腊鹅 姜丝 料酒 蒜苗 白糖'),
('03efefac-3db8-5965-89ae-73040ba6ac6f', '兴化米粉', '家常菜', '闽菜', '🍲', '细如发丝的兴化米粉，吸饱海鲜汤汁，清淡鲜美。', '["兴化米粉用温水泡 10 分钟至软，沥干备用。", "五花肉丝下锅煸香，放虾头炒出虾油，烹入老酒。", "加水烧开，下蛤蜊煮至开口，再下虾仁、白菜煮 2 分钟。", "下米粉煮 1-2 分钟，加盐调味，撒芹菜段出锅。"]'::jsonb, '[{"name": "兴化米粉", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鲜虾", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蛤蜊", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "五花肉", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "白菜", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "芹菜", "quantity": "2", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "老酒", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '246', '12', '36', '6', '4', '12', '2', NULL, 'A', NULL, '兴化米粉 家常菜 闽菜 细如发丝的兴化米粉，吸饱海鲜汤汁，清淡鲜美。 兴化米粉用温水泡 10 分钟至软，沥干备用。 五花肉丝下锅煸香，放虾头炒出虾油，烹入老酒。 加水烧开，下蛤蜊煮至开口，再下虾仁、白菜煮 2 分钟。 下米粉煮 1-2 分钟，加盐调味，撒芹菜段出锅。 煮 清淡 午餐 晚餐 兴化米粉 鲜虾 蛤蜊 五花肉 白菜 芹菜 老酒'),
('c718255b-7797-50cd-bd5c-bcbd2c7ee31f', '冒烤鸭', '家常菜', '川菜', '🦆', '烤鸭片浸入麻辣红汤，配豆芽千张，川味冒菜吃法过瘾。', '["烤鸭斩成小块；豆芽、千张丝入开水汆烫 1 分钟，垫入碗底。", "锅中放油炒香豆瓣酱，加开水煮 3 分钟成红汤，捞出料渣。", "红汤中下烤鸭块煮 4 分钟，连汤倒入垫菜碗中。", "表面撒蒜末、花椒粉，淋烧热的辣椒油激香，撒葱花香菜。"]'::jsonb, '[{"name": "烤鸭", "quantity": "0.5", "quantityPrefix": null, "unit": "只", "note": null, "sourceText": null}, {"name": "绿豆芽", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "千张丝", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "郫县豆瓣酱", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "花椒粉", "quantity": "1", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "葱花 香菜", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['麻辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '350 g', '499', '32', '14', '35', '9', '4', '10', NULL, 'A', NULL, '冒烤鸭 家常菜 川菜 烤鸭片浸入麻辣红汤，配豆芽千张，川味冒菜吃法过瘾。 烤鸭斩成小块；豆芽、千张丝入开水汆烫 1 分钟，垫入碗底。 锅中放油炒香豆瓣酱，加开水煮 3 分钟成红汤，捞出料渣。 红汤中下烤鸭块煮 4 分钟，连汤倒入垫菜碗中。 表面撒蒜末、花椒粉，淋烧热的辣椒油激香，撒葱花香菜。 煮 麻辣 午餐 晚餐 烤鸭 绿豆芽 千张丝 郫县豆瓣酱 辣椒油 蒜末 花椒粉 葱花 香菜'),
('a00dba31-e897-5295-834d-878dd6dc9e19', '农家一碗香', '家常菜', '湘菜', '🍲', '浏阳农家做法，五花肉、鸡蛋、青红椒一锅炒，油润咸香，堪称米饭杀手。', '["五花肉切薄片，鸡蛋煎成荷包蛋切块，青红椒切滚刀块。", "锅中少油，下五花肉中火煸出油至边缘微焦。", "下蒜片、青红椒大火翻炒，加入荷包蛋块。", "加生抽、老抽、盐翻匀，炒出锅气即可出锅。"]'::jsonb, '[{"name": "五花肉", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡蛋", "quantity": "3", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "青椒", "quantity": "2", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "红椒", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "老抽", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['炒']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '594', '30', '24', '42', '10', '8', '14', 'recipes/images/cd64270612fa1da87932.jpg', 'A', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/meat_dish/%E5%86%9C%E5%AE%B6%E4%B8%80%E7%A2%97%E9%A6%99/%E5%86%9C%E5%AE%B6%E4%B8%80%E7%A2%97%E9%A6%99.md', '农家一碗香 家常菜 湘菜 浏阳农家做法，五花肉、鸡蛋、青红椒一锅炒，油润咸香，堪称米饭杀手。 五花肉切薄片，鸡蛋煎成荷包蛋切块，青红椒切滚刀块。 锅中少油，下五花肉中火煸出油至边缘微焦。 下蒜片、青红椒大火翻炒，加入荷包蛋块。 加生抽、老抽、盐翻匀，炒出锅气即可出锅。 炒 咸鲜 午餐 晚餐 五花肉 鸡蛋 青椒 红椒 蒜 生抽 老抽 盐'),
('a83150bf-e201-5446-a641-52fca828ed98', '冬瓜丸子汤', '家常菜', '通用', '🍡', '手打肉丸弹嫩，冬瓜清甜，肉香汤鲜的暖心家常汤。', '["肉末加蛋清、姜末、淀粉和盐，顺一个方向搅打上劲。", "冬瓜去皮去瓤切片。", "锅中水烧开转小火，用虎口挤出丸子逐个下锅。", "全部下完后转中火煮 3 分钟撇去浮沫。", "下冬瓜片再煮 5 分钟，加盐调味，撒葱花即可。"]'::jsonb, '[{"name": "猪肉末", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "冬瓜", "quantity": "400", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡蛋清", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "姜末", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "淀粉", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '700 g', '332', '25', '13', '20', '3.5', '1.8', '2.8', NULL, 'A', NULL, '冬瓜丸子汤 家常菜 通用 手打肉丸弹嫩，冬瓜清甜，肉香汤鲜的暖心家常汤。 肉末加蛋清、姜末、淀粉和盐，顺一个方向搅打上劲。 冬瓜去皮去瓤切片。 锅中水烧开转小火，用虎口挤出丸子逐个下锅。 全部下完后转中火煮 3 分钟撇去浮沫。 下冬瓜片再煮 5 分钟，加盐调味，撒葱花即可。 煮 咸鲜 午餐 晚餐 猪肉末 冬瓜 鸡蛋清 姜末 淀粉 小葱 盐'),
('2efe2ab9-7edd-578d-85d0-125eff49614b', '冬瓜排骨汤', '家常菜', '通用', '🍲', '冬瓜清甜解腻，排骨汤鲜而不油，夏日消暑经典。', '["排骨冷水下锅，加料酒焯水 3 分钟，撇去浮沫后捞出冲洗干净。", "冬瓜去皮去瓤，切成 3 厘米见方的厚块。", "排骨放入砂锅，加足量热水和姜片，大火烧开转小火慢炖 40 分钟。", "下冬瓜块，继续小火炖 15 分钟至冬瓜透明软糯。", "加盐调味，撒葱花，关火焖 2 分钟即可。"]'::jsonb, '[{"name": "排骨", "quantity": "350", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "冬瓜", "quantity": "400", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "4", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "2", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煲汤']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '800 g', '330', '32', '10', '18', '4', '1.2', '2.2', NULL, 'A', NULL, '冬瓜排骨汤 家常菜 通用 冬瓜清甜解腻，排骨汤鲜而不油，夏日消暑经典。 排骨冷水下锅，加料酒焯水 3 分钟，撇去浮沫后捞出冲洗干净。 冬瓜去皮去瓤，切成 3 厘米见方的厚块。 排骨放入砂锅，加足量热水和姜片，大火烧开转小火慢炖 40 分钟。 下冬瓜块，继续小火炖 15 分钟至冬瓜透明软糯。 加盐调味，撒葱花，关火焖 2 分钟即可。 煲汤 咸鲜 午餐 晚餐 排骨 冬瓜 姜 小葱 料酒 盐'),
('dcc001f7-fb8d-54ae-8f5b-3fd9a77affe0', '冬瓜桑拿鸡', '家常菜', '通用', '🍽️', '', '["鸡切块，加姜丝、生抽、蚝油、盐、食用油，揉搓均匀后腌制 20 分钟", "冬瓜切薄片铺在盘子底部", "再铺一层泡好的虫草花", "把腌好的鸡肉铺在虫草花上面", "水烧开后放入蒸锅，上汽后蒸 15 分钟，出锅即可"]'::jsonb, '[{"name": "鸡肉 400 g（切块）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "鸡肉 400 g（切块）"}, {"name": "冬瓜 300 g（切薄片）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "冬瓜 300 g（切薄片）"}, {"name": "虫草花 30 g（提前冲洗泡软）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "虫草花 30 g（提前冲洗泡软）"}, {"name": "姜丝 10 g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "姜丝 10 g"}, {"name": "生抽 15 ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "生抽 15 ml"}, {"name": "蚝油 10 g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "蚝油 10 g"}, {"name": "盐 3 g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐 3 g"}, {"name": "食用油 10 ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "食用油 10 ml"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], 35, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/meat_dish/%E5%86%AC%E7%93%9C%E6%A1%91%E6%8B%BF%E9%B8%A1.md', '冬瓜桑拿鸡 家常菜 通用 鸡切块，加姜丝、生抽、蚝油、盐、食用油，揉搓均匀后腌制 20 分钟 冬瓜切薄片铺在盘子底部 再铺一层泡好的虫草花 把腌好的鸡肉铺在虫草花上面 水烧开后放入蒸锅，上汽后蒸 15 分钟，出锅即可 午餐 晚餐 鸡肉 400 g（切块） 冬瓜 300 g（切薄片） 虫草花 30 g（提前冲洗泡软） 姜丝 10 g 生抽 15 ml 蚝油 10 g 盐 3 g 食用油 10 ml'),
('734316cb-76ef-5c9f-a18e-2cb73ee8a1e1', '冬瓜汤', '减脂', '通用', '🍲', '冬瓜热量极低、利水消肿，配瘦肉丝提鲜，减脂期一碗清汤。', '["冬瓜去皮去瓤切薄片，瘦肉丝用少许盐抓匀。", "锅中烧开两碗水，放姜片、虾皮和冬瓜片，中火煮 5 分钟至透明。", "下瘦肉丝拨散，煮 2 分钟至变色。", "加盐和白胡椒调味，撒葱花出锅。"]'::jsonb, '[{"name": "冬瓜", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "瘦肉丝", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "虾皮", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "白胡椒、盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '400 g', '125', '13', '7', '5', '3.3', '1.8', '1.3', NULL, 'A', NULL, '冬瓜汤 减脂 通用 冬瓜热量极低、利水消肿，配瘦肉丝提鲜，减脂期一碗清汤。 冬瓜去皮去瓤切薄片，瘦肉丝用少许盐抓匀。 锅中烧开两碗水，放姜片、虾皮和冬瓜片，中火煮 5 分钟至透明。 下瘦肉丝拨散，煮 2 分钟至变色。 加盐和白胡椒调味，撒葱花出锅。 煮 清淡 晚餐 冬瓜 瘦肉丝 虾皮 姜 小葱 白胡椒、盐'),
('77866174-db51-5d43-b514-014e4153542d', '冬瓜烧肉', '保持', '通用', '🥘', '冬瓜吸足肉汁软糯入味，五花肉肥而不腻，清爽版烧肉。', '["五花肉切薄片，冬瓜去皮切厚块。", "锅中少油，下五花肉中火煸炒 3 分钟至出油微焦。", "加生抽老抽和两碗水，烧开转小火炖 10 分钟。", "下冬瓜块再炖 8 分钟至透明，大火收汁撒葱花。"]'::jsonb, '[{"name": "五花肉", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "冬瓜", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "老抽", "quantity": "0.5", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "2", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['红烧']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '450 g', '396', '9', '9', '36', '2.1', '2', '8', NULL, 'A', NULL, '冬瓜烧肉 保持 通用 冬瓜吸足肉汁软糯入味，五花肉肥而不腻，清爽版烧肉。 五花肉切薄片，冬瓜去皮切厚块。 锅中少油，下五花肉中火煸炒 3 分钟至出油微焦。 加生抽老抽和两碗水，烧开转小火炖 10 分钟。 下冬瓜块再炖 8 分钟至透明，大火收汁撒葱花。 红烧 咸鲜 午餐 晚餐 五花肉 冬瓜 姜 小葱 生抽 老抽 食用油'),
('3f546771-ed15-5c40-8b9d-0f1fda28e33b', '冬瓜老鸭汤', '家常菜', '粤菜', '🍲', '清热消暑的经典老火汤，冬瓜吸饱鸭汤鲜甜，夏天常喝。', '["薏米提前泡 1 小时；老鸭剁块焯水 5 分钟。", "鸭块、姜片、薏米入锅，加开水大火烧开撇沫，转小火炖 1 小时。", "下冬瓜块再炖 15 分钟至透明。", "加盐和白胡椒粉调味即可。"]'::jsonb, '[{"name": "老鸭", "quantity": "0.5", "quantityPrefix": null, "unit": "只", "note": "（约 500 克）", "sourceText": null}, {"name": "冬瓜", "quantity": "400", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "1", "quantityPrefix": null, "unit": "块", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "薏米", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "白胡椒粉", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}]'::jsonb, ARRAY['煲汤']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '600 g', '255', '21', '9', '15', '3.5', '1.5', '2.5', NULL, 'A', NULL, '冬瓜老鸭汤 家常菜 粤菜 清热消暑的经典老火汤，冬瓜吸饱鸭汤鲜甜，夏天常喝。 薏米提前泡 1 小时；老鸭剁块焯水 5 分钟。 鸭块、姜片、薏米入锅，加开水大火烧开撇沫，转小火炖 1 小时。 下冬瓜块再炖 15 分钟至透明。 加盐和白胡椒粉调味即可。 煲汤 清淡 晚餐 老鸭 冬瓜 姜 料酒 薏米 盐 白胡椒粉'),
('ecce6887-72e2-5ce4-a3d6-5a9b8c4ed0e2', '冬瓜荷叶汤', '食疗', '粤菜', '🍃', '清热解暑、利水消肿，夏日消脂轻负担。', '["冬瓜连皮切厚块，荷叶洗净撕片，薏米浸泡 1 小时。", "荷叶、薏米、姜片加清水煮 20 分钟出味。", "下冬瓜块再煮 20 分钟至透明，捞去荷叶加盐调味。"]'::jsonb, '[{"name": "冬瓜", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干荷叶", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "薏米", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "清水", "quantity": "1000", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '85', '3', '16', '1', '0.8', '4', '0.2', NULL, 'A', NULL, '冬瓜荷叶汤 食疗 粤菜 清热解暑、利水消肿，夏日消脂轻负担。 冬瓜连皮切厚块，荷叶洗净撕片，薏米浸泡 1 小时。 荷叶、薏米、姜片加清水煮 20 分钟出味。 下冬瓜块再煮 20 分钟至透明，捞去荷叶加盐调味。 煮 清淡 午餐 晚餐 冬瓜 干荷叶 薏米 姜 清水'),
('984517d3-cb00-5410-bd18-59922bee2f23', '冬瓜薏米排骨汤', '食疗', '粤菜', '🍲', '清热利湿、消暑健脾，冬瓜吸饱肉香格外清甜。', '["猪骨焯水洗净；薏米浸泡 1 小时；冬瓜连皮切块。", "猪骨、薏米、姜片加清水大火烧开，转小火煲 40 分钟。", "下冬瓜块续煲 20 分钟，加盐调味即可。"]'::jsonb, '[{"name": "冬瓜", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "薏米", "quantity": "40", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "猪骨", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "清水", "quantity": "1200", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}]'::jsonb, ARRAY['煲汤']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '320', '20', '24', '16', '5', '6', '4', NULL, 'A', NULL, '冬瓜薏米排骨汤 食疗 粤菜 清热利湿、消暑健脾，冬瓜吸饱肉香格外清甜。 猪骨焯水洗净；薏米浸泡 1 小时；冬瓜连皮切块。 猪骨、薏米、姜片加清水大火烧开，转小火煲 40 分钟。 下冬瓜块续煲 20 分钟，加盐调味即可。 煲汤 清淡 午餐 晚餐 冬瓜 薏米 猪骨 姜 清水'),
('643a24bb-8f68-53cf-8730-dab1a5df558d', '冬瓜薏米汤', '减脂', '通用', '🍲', '冬瓜利水、薏米祛湿，汤清味淡，减脂期祛湿消肿的好汤。', '["薏米提前浸泡 2 小时；冬瓜去皮去瓤切薄片。", "锅中加两碗水，放入薏米和姜片，大火烧开转小火煮 25 分钟。", "加入冬瓜片和虾皮，中火煮 8 分钟至冬瓜透明。", "加盐和白胡椒调味，撒葱花出锅。"]'::jsonb, '[{"name": "冬瓜", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "薏米", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "虾皮", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "盐、白胡椒", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '450 g', '158', '8', '27', '2', '1.78', '6', '0.44', NULL, 'A', NULL, '冬瓜薏米汤 减脂 通用 冬瓜利水、薏米祛湿，汤清味淡，减脂期祛湿消肿的好汤。 薏米提前浸泡 2 小时；冬瓜去皮去瓤切薄片。 锅中加两碗水，放入薏米和姜片，大火烧开转小火煮 25 分钟。 加入冬瓜片和虾皮，中火煮 8 分钟至冬瓜透明。 加盐和白胡椒调味，撒葱花出锅。 煮 清淡 晚餐 冬瓜 薏米 虾皮 姜 小葱 盐、白胡椒'),
('395b32f0-db50-5ef8-a2b1-fb535d8b8297', '冬瓜虾仁汤', '家常菜', '通用', '🦐', '冬瓜清爽、虾仁弹嫩，低脂高蛋白的快手鲜汤。', '["冬瓜去皮去瓤切片；虾仁用料酒和盐抓匀腌 5 分钟。", "锅中水烧开，下冬瓜片和姜片煮 5 分钟。", "下虾仁煮 2 分钟至变色卷曲。", "加盐调味，撒葱花即可。"]'::jsonb, '[{"name": "冬瓜", "quantity": "400", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鲜虾仁", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['鲜香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '650 g', '163', '18', '7', '7', '2.8', '1', '1', NULL, 'A', NULL, '冬瓜虾仁汤 家常菜 通用 冬瓜清爽、虾仁弹嫩，低脂高蛋白的快手鲜汤。 冬瓜去皮去瓤切片；虾仁用料酒和盐抓匀腌 5 分钟。 锅中水烧开，下冬瓜片和姜片煮 5 分钟。 下虾仁煮 2 分钟至变色卷曲。 加盐调味，撒葱花即可。 煮 鲜香 午餐 晚餐 冬瓜 鲜虾仁 姜 小葱 料酒 盐'),
('d6e48577-758f-52a8-819c-36eac4656e94', '冬瓜虾皮豆腐汤', '保持', '通用', '🍲', '冬瓜清甜、豆腐嫩滑，虾皮提鲜，清淡鲜美的家常快手汤。', '["冬瓜去皮切薄片，豆腐切小块，瘦肉丝用少许盐抓匀。", "锅中烧开三碗水，放姜片、虾皮和冬瓜片，中火煮 5 分钟至透明。", "下豆腐块再煮 3 分钟，放瘦肉丝拨散煮 2 分钟。", "加盐和白胡椒调味，撒葱花出锅。"]'::jsonb, '[{"name": "冬瓜", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "北豆腐", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "虾皮", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "瘦肉丝", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "白胡椒、盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '550 g', '265', '26', '11', '13', '4.7', '2', '2.4', NULL, 'A', NULL, '冬瓜虾皮豆腐汤 保持 通用 冬瓜清甜、豆腐嫩滑，虾皮提鲜，清淡鲜美的家常快手汤。 冬瓜去皮切薄片，豆腐切小块，瘦肉丝用少许盐抓匀。 锅中烧开三碗水，放姜片、虾皮和冬瓜片，中火煮 5 分钟至透明。 下豆腐块再煮 3 分钟，放瘦肉丝拨散煮 2 分钟。 加盐和白胡椒调味，撒葱花出锅。 煮 清淡 晚餐 冬瓜 北豆腐 虾皮 瘦肉丝 姜 小葱 白胡椒、盐'),
('c4a1f628-677c-5ffe-9156-547b40facc4a', '冬瓜酿肉', '家常菜', '通用', '🍽️', '', '["冬瓜去皮，切成 25cm 长 3cm 厚的片", "将切好的冬瓜放入碗中，放入 15g 盐，将冬瓜抹匀，放置 10 分钟", "放置冬瓜的同时，换个碗放入肉末，葱姜末， 5g 盐，淀粉 5g，胡椒粉，生抽，胡椒粉", "使用筷子在肉末中进行顺时针搅拌，搅拌到食材颜色没有明显对比（约 2 分钟）", "将腌制好的冬瓜（会变软）使用清水洗三遍", "拿出 1 片冬瓜片卷起来，并把肉塞进去", "放入碟子中摆到碟子的边缘", "打入 1 个鸡蛋到中间圆圈处", "放入普通铁锅中水烧开后，蒸 15 分钟，盖上锅盖", "开盖，取出蒸好的冬瓜酿肉", "将冬瓜酿肉碟子的水倒入锅中，放入水淀粉，加入 50ml 清水倒入锅中烧开", "淋到冬瓜酿肉上"]'::jsonb, '[{"name": "猪肉末 300g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "猪肉末 300g"}, {"name": "鸡蛋 1 个（可选,不习惯的人可能会有点腥）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "鸡蛋 1 个（可选,不习惯的人可能会有点腥）"}, {"name": "冬瓜 200g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "冬瓜 200g"}, {"name": "葱花（一根,约 20g）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "葱花（一根,约 20g）"}, {"name": "胡椒粉 5g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "胡椒粉 5g"}, {"name": "生抽 10ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "生抽 10ml"}, {"name": "淀粉 5g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "淀粉 5g"}, {"name": "水淀粉 25g（淀粉 25g,水 50ml）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "水淀粉 25g（淀粉 25g,水 50ml）"}, {"name": "葱姜末（姜 3-4 片约 30g, 取上面一根葱花中的葱白部分即可）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "葱姜末（姜 3-4 片约 30g, 取上面一根葱花中的葱白部分即可）"}, {"name": "盐 20g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐 20g"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], 30, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'recipes/images/40e28313bc713fccb612.jpg', 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/meat_dish/%E5%86%AC%E7%93%9C%E9%85%BF%E8%82%89/%E5%86%AC%E7%93%9C%E9%85%BF%E8%82%89.md', '冬瓜酿肉 家常菜 通用 冬瓜去皮，切成 25cm 长 3cm 厚的片 将切好的冬瓜放入碗中，放入 15g 盐，将冬瓜抹匀，放置 10 分钟 放置冬瓜的同时，换个碗放入肉末，葱姜末， 5g 盐，淀粉 5g，胡椒粉，生抽，胡椒粉 使用筷子在肉末中进行顺时针搅拌，搅拌到食材颜色没有明显对比（约 2 分钟） 将腌制好的冬瓜（会变软）使用清水洗三遍 拿出 1 片冬瓜片卷起来，并把肉塞进去 放入碟子中摆到碟子的边缘 打入 1 个鸡蛋到中间圆圈处 放入普通铁锅中水烧开后，蒸 15 分钟，盖上锅盖 开盖，取出蒸好的冬瓜酿肉 将冬瓜酿肉碟子的水倒入锅中，放入水淀粉，加入 50ml 清水倒入锅中烧开 淋到冬瓜酿肉上 午餐 晚餐 猪肉末 300g 鸡蛋 1 个（可选,不习惯的人可能会有点腥） 冬瓜 200g 葱花（一根,约 20g） 胡椒粉 5g 生抽 10ml 淀粉 5g 水淀粉 25g（淀粉 25g,水 50ml） 葱姜末（姜 3-4 片约 30g, 取上面一根葱花中的葱白部分即可） 盐 20g'),
('49c1a728-aa77-5594-a750-fc4e8a66a24b', '冰糖湘莲', '家常菜', '湘菜', '🪷', '洞庭湘莲清甜粉糯，冰糖莲子汤清亮甜润，饭后来一碗，清心又解辣。', '["干莲子温水泡 2 小时，去芯。", "莲子入锅加足量清水，大火烧开转小火炖 40 分钟。", "下冰糖继续炖 10 分钟，至莲子粉糯、汤汁微稠。", "下枸杞焖 2 分钟，放凉或冷藏后食用更佳。"]'::jsonb, '[{"name": "干湘莲", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "冰糖", "quantity": "60", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "枸杞", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "清水", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['炖']::TEXT[], ARRAY['甜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '250 g', '305', '15', '50', '5', '6', '20', '2', NULL, 'A', NULL, '冰糖湘莲 家常菜 湘菜 洞庭湘莲清甜粉糯，冰糖莲子汤清亮甜润，饭后来一碗，清心又解辣。 干莲子温水泡 2 小时，去芯。 莲子入锅加足量清水，大火烧开转小火炖 40 分钟。 下冰糖继续炖 10 分钟，至莲子粉糯、汤汁微稠。 下枸杞焖 2 分钟，放凉或冷藏后食用更佳。 炖 甜 午餐 晚餐 干湘莲 冰糖 枸杞 清水'),
('2dcac4c5-343d-5d61-9af3-57b8bd034921', '冰糖银耳莲子羹', '营养', '通用', '🍵', '银耳胶质浓滑，莲子清心，枸杞红枣点缀，润燥甜品羹。', '["干银耳冷水泡发 2 小时，去蒂撕成小朵，莲子浸泡 1 小时。", "银耳加足量水，大火烧开转小火炖 40 分钟至出胶。", "加入莲子、红枣和冰糖，再小火炖 20 分钟。", "关火前 5 分钟撒入枸杞即可。"]'::jsonb, '[{"name": "干银耳", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": "（泡发约 100 克）", "sourceText": null}, {"name": "莲子", "quantity": "20", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "红枣", "quantity": "3", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "枸杞", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "冰糖", "quantity": "8", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "清水", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['炖']::TEXT[], ARRAY['甜']::TEXT[], ARRAY['早餐', '晚餐']::TEXT[], NULL, NULL, '350 g', '133', '3', '28', '1', '0.9', '8', '0.3', NULL, 'A', NULL, '冰糖银耳莲子羹 营养 通用 银耳胶质浓滑，莲子清心，枸杞红枣点缀，润燥甜品羹。 干银耳冷水泡发 2 小时，去蒂撕成小朵，莲子浸泡 1 小时。 银耳加足量水，大火烧开转小火炖 40 分钟至出胶。 加入莲子、红枣和冰糖，再小火炖 20 分钟。 关火前 5 分钟撒入枸杞即可。 炖 甜 早餐 晚餐 干银耳 莲子 红枣 枸杞 冰糖 清水'),
('b30a6315-3d95-522f-bced-eb0ea4028fe0', '冰糖雪梨汤', '家常菜', '通用', '🍐', '雪梨清甜润肺，搭配冰糖银耳，秋冬干燥时节的家常甜汤。', '["银耳泡发撕小朵；雪梨去皮去核切块。", "银耳加清水大火烧开，转小火炖 30 分钟出胶。", "下雪梨块再炖 20 分钟至梨肉透明。", "加冰糖和枸杞，煮 5 分钟至冰糖化开即可。"]'::jsonb, '[{"name": "雪梨", "quantity": "2", "quantityPrefix": null, "unit": "个", "note": "（约 500 克）", "sourceText": null}, {"name": "冰糖", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干银耳", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "枸杞", "quantity": "1", "quantityPrefix": null, "unit": "小把", "note": null, "sourceText": null}, {"name": "红枣", "quantity": "4", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "清水", "quantity": "1000", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}]'::jsonb, ARRAY['煲汤']::TEXT[], ARRAY['甜']::TEXT[], ARRAY['早餐', '晚餐']::TEXT[], NULL, NULL, '500 g', '157', '2', '35', '1', '0.3', '7', '0.1', NULL, 'A', NULL, '冰糖雪梨汤 家常菜 通用 雪梨清甜润肺，搭配冰糖银耳，秋冬干燥时节的家常甜汤。 银耳泡发撕小朵；雪梨去皮去核切块。 银耳加清水大火烧开，转小火炖 30 分钟出胶。 下雪梨块再炖 20 分钟至梨肉透明。 加冰糖和枸杞，煮 5 分钟至冰糖化开即可。 煲汤 甜 早餐 晚餐 雪梨 冰糖 干银耳 枸杞 红枣 清水');
INSERT INTO recipe_catalog (id, name, category, cuisine, emoji, description, steps, ingredients, methods, flavors, meal_types, estimated_minutes, servings, serving_size, kcal, protein, carbs, fat, protein_per100g, carbs_per100g, fat_per100g, image_key, source, source_url, search_text) VALUES
('3b097667-f872-5e01-8f9a-7475fc8c122b', '冷吃兔', '家常菜', '通用', '🍽️', '', '["蒜、姜扒皮并剁碎备用，八角、桂皮、香叶、山奈、白蔻、小茴香洗净备用。", "干辣椒剪成 2 厘米的小段，洗净备用。", "小葱/大葱/洋葱洗净，洋葱切成小块。", "兔肉剁成 2 厘米的小块，加入盐、料酒、味精调味，腌制 15 分钟。", "锅中倒油，油温 4 成热下小葱/大葱/洋葱，中小火煸炒出香味，待到小葱/大葱/洋葱微焦，将其捞出。", "开大火升高油温，油温 8 成热时下入兔肉，炸制过程转中小火，炸至兔肉微微焦黄时捞出兔肉。", "升高油温，倒入干辣椒、青花椒、八角、桂皮、香叶、山奈、白蔻、小茴香；转小火将辣椒段炸脆。", "重新倒入兔肉，加入蚝油、翻炒几分钟。", "关火，加入蒜、姜、白芝麻，翻炒均匀。", "放置一夜更加入味。"]'::jsonb, '[{"name": "盐量 = 兔肉斤数 2 克", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐量 = 兔肉斤数  2 克"}, {"name": "味精量 = 兔肉斤数 1 克", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "味精量 = 兔肉斤数  1 克"}, {"name": "蚝油量 = 兔肉斤数 5 克", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "蚝油量 = 兔肉斤数  5 克"}, {"name": "料酒量 = 兔肉斤数 10 克", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "料酒量 = 兔肉斤数  10 克"}, {"name": "油量 = 兔肉斤数 0.9 ～ 1 升", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "油量 = 兔肉斤数  0.9 ～ 1 升"}, {"name": "蒜量 = 兔肉斤数 二分之一头蒜", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "蒜量 = 兔肉斤数  二分之一头蒜"}, {"name": "姜量 = 蒜量", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "姜量 = 蒜量"}, {"name": "小葱/大葱/洋葱总量 = 兔肉斤数 15 克", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "小葱/大葱/洋葱总量 = 兔肉斤数  15 克"}, {"name": "干辣椒量 = 辣椒段的总体积等于兔肉的总体积", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "干辣椒量 = 辣椒段的总体积等于兔肉的总体积"}, {"name": "青花椒量 = 3 斤兔肉对应吃饭用的小碗，一整碗花椒", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "青花椒量 = 3 斤兔肉对应吃饭用的小碗，一整碗花椒"}, {"name": "八角量 = 兔肉斤数 1 粒", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "八角量 = 兔肉斤数  1 粒"}, {"name": "桂皮量 = 兔肉斤数 大拇指长短的一块", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "桂皮量 = 兔肉斤数  大拇指长短的一块"}, {"name": "香叶量 = 兔肉斤数 5 片", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "香叶量 = 兔肉斤数  5 片"}, {"name": "山奈量 = 兔肉斤数 黄豆大小的一块", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "山奈量 = 兔肉斤数  黄豆大小的一块"}, {"name": "白蔻量 = 兔肉斤数 2 颗", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "白蔻量 = 兔肉斤数  2 颗"}, {"name": "小茴香量 = 兔肉斤数 15 克", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "小茴香量 = 兔肉斤数  15 克"}, {"name": "白芝麻量 = 兔肉斤数 25 克", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "白芝麻量 = 兔肉斤数  25 克"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/meat_dish/%E5%86%B7%E5%90%83%E5%85%94.md', '冷吃兔 家常菜 通用 蒜、姜扒皮并剁碎备用，八角、桂皮、香叶、山奈、白蔻、小茴香洗净备用。 干辣椒剪成 2 厘米的小段，洗净备用。 小葱/大葱/洋葱洗净，洋葱切成小块。 兔肉剁成 2 厘米的小块，加入盐、料酒、味精调味，腌制 15 分钟。 锅中倒油，油温 4 成热下小葱/大葱/洋葱，中小火煸炒出香味，待到小葱/大葱/洋葱微焦，将其捞出。 开大火升高油温，油温 8 成热时下入兔肉，炸制过程转中小火，炸至兔肉微微焦黄时捞出兔肉。 升高油温，倒入干辣椒、青花椒、八角、桂皮、香叶、山奈、白蔻、小茴香；转小火将辣椒段炸脆。 重新倒入兔肉，加入蚝油、翻炒几分钟。 关火，加入蒜、姜、白芝麻，翻炒均匀。 放置一夜更加入味。 午餐 晚餐 盐量 = 兔肉斤数 2 克 味精量 = 兔肉斤数 1 克 蚝油量 = 兔肉斤数 5 克 料酒量 = 兔肉斤数 10 克 油量 = 兔肉斤数 0.9 ～ 1 升 蒜量 = 兔肉斤数 二分之一头蒜 姜量 = 蒜量 小葱/大葱/洋葱总量 = 兔肉斤数 15 克 干辣椒量 = 辣椒段的总体积等于兔肉的总体积 青花椒量 = 3 斤兔肉对应吃饭用的小碗，一整碗花椒 八角量 = 兔肉斤数 1 粒 桂皮量 = 兔肉斤数 大拇指长短的一块 香叶量 = 兔肉斤数 5 片 山奈量 = 兔肉斤数 黄豆大小的一块 白蔻量 = 兔肉斤数 2 颗 小茴香量 = 兔肉斤数 15 克 白芝麻量 = 兔肉斤数 25 克'),
('fa3b2d2b-57d9-5054-9915-6555a59d3c5c', '冻梨', '小吃', '东北菜', '🍐', '白梨冷冻到乌黑，缓到半化咬一口，冰甜汁水迸出，东北限定冬日快乐。', '["花盖梨洗净擦干，放入冰箱冷冻 48 小时冻透。", "取出放凉水中缓冻，待冰壳融化、梨身变软。", "反复冻化两次，梨肉变黑变软即可。", "吃时用手捏软，咬一小口吸汁，冰甜沁心。"]'::jsonb, '[{"name": "花盖梨", "quantity": "4", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "清水", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "白糖", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}, {"name": "蜂蜜", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}]'::jsonb, '{}'::TEXT[], ARRAY['甜']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '200 g', '122', '2', '24', '2', '1', '12', '1', NULL, 'A', NULL, '冻梨 小吃 东北菜 白梨冷冻到乌黑，缓到半化咬一口，冰甜汁水迸出，东北限定冬日快乐。 花盖梨洗净擦干，放入冰箱冷冻 48 小时冻透。 取出放凉水中缓冻，待冰壳融化、梨身变软。 反复冻化两次，梨肉变黑变软即可。 吃时用手捏软，咬一小口吸汁，冰甜沁心。 甜 晚餐 花盖梨 清水 白糖 蜂蜜'),
('ea1e0bbf-6b50-5230-a328-7154253aacdb', '凉拌三丝', '保持', '通用', '🥗', '黄瓜、胡萝卜、粉丝三丝凉拌，酸辣爽口，夏日开胃家常凉菜。', '["黄瓜、胡萝卜切细丝；粉丝温水泡发后沸水煮 1 分钟过凉沥干。", "木耳焯水 1 分钟切丝，蒜切末。", "所有食材装入大碗，加香醋、生抽、香油和少许盐。", "拌匀后撒熟花生碎，静置 2 分钟入味即可。"]'::jsonb, '[{"name": "黄瓜", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "胡萝卜", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干粉丝", "quantity": "40", "quantityPrefix": null, "unit": "克", "note": "（泡发约 120 克）", "sourceText": null}, {"name": "木耳（泡发）", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "熟花生碎", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香油", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '350 g', '295', '5', '49', '9', '1.4', '14', '2.6', NULL, 'A', NULL, '凉拌三丝 保持 通用 黄瓜、胡萝卜、粉丝三丝凉拌，酸辣爽口，夏日开胃家常凉菜。 黄瓜、胡萝卜切细丝；粉丝温水泡发后沸水煮 1 分钟过凉沥干。 木耳焯水 1 分钟切丝，蒜切末。 所有食材装入大碗，加香醋、生抽、香油和少许盐。 拌匀后撒熟花生碎，静置 2 分钟入味即可。 凉拌 酸辣 午餐 晚餐 黄瓜 胡萝卜 干粉丝 木耳（泡发） 熟花生碎 蒜 香醋 香油'),
('ca721a2a-f4ba-5b5a-a0fd-246e415b612a', '凉拌千张丝', '减脂', '通用', '🥗', '千张是豆制品里的蛋白王，凉拌清爽，减脂期高蛋白凉菜。', '["千张切细丝，沸水焯烫 1 分钟捞出过凉沥干。", "黄瓜、胡萝卜切细丝，蒜切末。", "香醋、生抽、香油、蒜末调成料汁。", "千张丝与蔬菜丝拌匀，淋料汁撒白芝麻即可。"]'::jsonb, '[{"name": "千张", "quantity": "110", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": "（约 100 克）", "sourceText": null}, {"name": "胡萝卜", "quantity": "40", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "2", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香油", "quantity": "3", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "白芝麻", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '310 g', '267', '28', '14', '11', '9.03', '4.52', '3.55', NULL, 'A', NULL, '凉拌千张丝 减脂 通用 千张是豆制品里的蛋白王，凉拌清爽，减脂期高蛋白凉菜。 千张切细丝，沸水焯烫 1 分钟捞出过凉沥干。 黄瓜、胡萝卜切细丝，蒜切末。 香醋、生抽、香油、蒜末调成料汁。 千张丝与蔬菜丝拌匀，淋料汁撒白芝麻即可。 凉拌 清淡 午餐 晚餐 千张 黄瓜 胡萝卜 蒜 香醋 生抽 香油 白芝麻'),
('03c8c625-7ea3-537a-aae4-b9b4f49ad0f3', '凉拌干豆腐丝', '家常菜', '东北菜', '🥢', '干豆腐切细丝焯水拌料，加蒜末辣椒油，筋道入味，下酒必备。', '["干豆腐切细丝，沸水焯烫 1 分钟捞出过凉；黄瓜、胡萝卜切丝。", "蒜切末，加生抽、香醋、辣椒油调成料汁。", "干豆腐丝、黄瓜丝、胡萝卜丝放大碗，浇上料汁。", "拌匀后静置 5 分钟入味即可。"]'::jsonb, '[{"name": "干豆腐", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "0.5", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "胡萝卜", "quantity": "0.5", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '200 g', '230', '18', '8', '14', '9', '4', '7', NULL, 'A', NULL, '凉拌干豆腐丝 家常菜 东北菜 干豆腐切细丝焯水拌料，加蒜末辣椒油，筋道入味，下酒必备。 干豆腐切细丝，沸水焯烫 1 分钟捞出过凉；黄瓜、胡萝卜切丝。 蒜切末，加生抽、香醋、辣椒油调成料汁。 干豆腐丝、黄瓜丝、胡萝卜丝放大碗，浇上料汁。 拌匀后静置 5 分钟入味即可。 凉拌 辣 午餐 晚餐 干豆腐 黄瓜 胡萝卜 蒜 辣椒油 生抽 香醋 盐'),
('8b8d4f29-608d-59d2-9e50-7bfaf9470e75', '凉拌折耳根', '家常菜', '滇菜', '🥬', '鱼腥草脆嫩带独特香气，小米辣蒜醋一拌，酸辣爽口，爱的人停不下筷。', '["折耳根摘去老根，洗净切段，用凉开水冲洗沥干。", "小米辣切圈，与蒜末、生抽、醋、辣椒油调成料汁。", "料汁倒入折耳根拌匀，撒香菜即可。"]'::jsonb, '[{"name": "折耳根", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "小米辣", "quantity": "4", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香菜", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '200 g', '118', '4', '12', '6', '2', '6', '3', NULL, 'A', NULL, '凉拌折耳根 家常菜 滇菜 鱼腥草脆嫩带独特香气，小米辣蒜醋一拌，酸辣爽口，爱的人停不下筷。 折耳根摘去老根，洗净切段，用凉开水冲洗沥干。 小米辣切圈，与蒜末、生抽、醋、辣椒油调成料汁。 料汁倒入折耳根拌匀，撒香菜即可。 凉拌 酸辣 午餐 晚餐 折耳根 小米辣 蒜末 生抽 醋 辣椒油 香菜'),
('07ef0097-2edd-54cb-8472-1ddd9216f13f', '凉拌木耳', '家常菜', '通用', '🍄', '木耳焯水后冰镇，爽脆弹牙，酸辣凉拌汁吃着超开胃。', '["木耳泡发后去蒂撕小朵，反复冲洗干净。", "烧开水下木耳焯 2 分钟，捞出立刻过凉水沥干。", "蒜末、小米椒圈、香醋、生抽、糖、香油、辣椒油调成料汁。", "料汁与木耳拌匀，冷藏 10 分钟后风味更佳。"]'::jsonb, '[{"name": "泡发木耳", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "小米椒", "quantity": "2", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "白糖", "quantity": "0.5", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "香油", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '320 g', '199', '4', '21', '11', '1.3', '6.6', '3.4', 'recipes/images/9d5b2964d96ab5324e2f.jpg', 'A', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/vegetable_dish/%E5%87%89%E6%8B%8C%E6%9C%A8%E8%80%B3/%E5%87%89%E6%8B%8C%E6%9C%A8%E8%80%B3.md', '凉拌木耳 家常菜 通用 木耳焯水后冰镇，爽脆弹牙，酸辣凉拌汁吃着超开胃。 木耳泡发后去蒂撕小朵，反复冲洗干净。 烧开水下木耳焯 2 分钟，捞出立刻过凉水沥干。 蒜末、小米椒圈、香醋、生抽、糖、香油、辣椒油调成料汁。 料汁与木耳拌匀，冷藏 10 分钟后风味更佳。 凉拌 酸辣 午餐 晚餐 泡发木耳 蒜末 小米椒 香醋 生抽 白糖 香油 辣椒油'),
('9d7a9d14-549b-54fe-8069-ab6ec60c0627', '凉拌油麦菜', '家常菜', '通用', '🍽️', '', '["蒜拍碎切末", "醋，酱油，芝麻酱，香油，糖，蚝油，蒜末放到碗里搅拌均匀", "油麦菜切段，每段不超过 4cm", "油麦菜放到一个大点的盆里，倒入上述碗中酱料，充分搅拌均匀."]'::jsonb, '[{"name": "1 颗 油麦菜（约 200g）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "1 颗 油麦菜（约 200g）  份数"}, {"name": "15ml 醋", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "15ml 醋  份数"}, {"name": "5ml 酱油", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "5ml 酱油  份数"}, {"name": "10ml 芝麻酱", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "10ml 芝麻酱  份数"}, {"name": "5ml 香油", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "5ml 香油  份数"}, {"name": "5g 糖", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "5g 糖  份数"}, {"name": "10ml 蚝油", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "10ml 蚝油  份数"}, {"name": "两头蒜", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "两头蒜  份数"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/vegetable_dish/%E5%87%89%E6%8B%8C%E6%B2%B9%E9%BA%A6%E8%8F%9C.md', '凉拌油麦菜 家常菜 通用 蒜拍碎切末 醋，酱油，芝麻酱，香油，糖，蚝油，蒜末放到碗里搅拌均匀 油麦菜切段，每段不超过 4cm 油麦菜放到一个大点的盆里，倒入上述碗中酱料，充分搅拌均匀. 午餐 晚餐 1 颗 油麦菜（约 200g） 15ml 醋 5ml 酱油 10ml 芝麻酱 5ml 香油 5g 糖 10ml 蚝油 两头蒜'),
('3ff41cbd-7f4d-5093-ab7d-78a9636536a3', '凉拌海带丝', '营养', '通用', '🌿', '海带富含碘与可溶性纤维，凉拌爽脆开胃，花生碎增香，是低脂高纤小菜。', '["干海带泡发 30 分钟，洗净切丝。", "沸水煮海带丝 5 分钟，捞出过凉水沥干。", "蒜末、香醋、生抽、香油调成料汁，与海带丝拌匀。", "撒白芝麻和小米辣圈，冷藏 10 分钟更入味。"]'::jsonb, '[{"name": "干海带", "quantity": "40", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "花生碎", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "2", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香油", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "白芝麻", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}, {"name": "小米辣", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": "（可选）", "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['蒜香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '250 g', '161', '4', '16', '9', '1.5', '6.5', '3.5', NULL, 'A', NULL, '凉拌海带丝 营养 通用 海带富含碘与可溶性纤维，凉拌爽脆开胃，花生碎增香，是低脂高纤小菜。 干海带泡发 30 分钟，洗净切丝。 沸水煮海带丝 5 分钟，捞出过凉水沥干。 蒜末、香醋、生抽、香油调成料汁，与海带丝拌匀。 撒白芝麻和小米辣圈，冷藏 10 分钟更入味。 凉拌 蒜香 午餐 晚餐 干海带 花生碎 蒜 香醋 生抽 香油 白芝麻 小米辣'),
('f904c515-8918-58c0-87e6-1b73e1d43f26', '凉拌腐竹', '家常菜', '通用', '🥢', '泡发腐竹软韧有嚼劲，黄瓜木耳增脆，酸辣凉拌汁爽口开胃。', '["泡发腐竹切段，入沸水焯 1 分钟捞出过凉沥干；木耳焯 2 分钟。", "黄瓜拍裂切段，与腐竹、木耳一同放入大碗。", "蒜末、香醋、生抽、香油、辣椒油调成料汁，浇入碗中。", "拌匀腌制 10 分钟使其入味即可。"]'::jsonb, '[{"name": "泡发腐竹", "quantity": "180", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "泡发木耳", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "香油", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '330 g', '377', '26', '21', '21', '7.9', '6.4', '6.4', NULL, 'A', NULL, '凉拌腐竹 家常菜 通用 泡发腐竹软韧有嚼劲，黄瓜木耳增脆，酸辣凉拌汁爽口开胃。 泡发腐竹切段，入沸水焯 1 分钟捞出过凉沥干；木耳焯 2 分钟。 黄瓜拍裂切段，与腐竹、木耳一同放入大碗。 蒜末、香醋、生抽、香油、辣椒油调成料汁，浇入碗中。 拌匀腌制 10 分钟使其入味即可。 凉拌 酸辣 午餐 晚餐 泡发腐竹 黄瓜 泡发木耳 蒜末 香醋 生抽 香油 辣椒油'),
('f206311f-158a-5e7a-a3ce-487932fcec68', '凉拌莴笋', '家常菜', '通用', '🍽️', '', '["莴笋削皮，切小条。萝卜切条，一起放入大碗，加入盐搅拌，放置 10 分钟", "放置后的莴笋用水清洗 1-2 遍", "起锅烧水，放入莴笋，水煮 1 分钟 捞出，沥干水分，放入大碗", "起锅烧油，放入姜片、蒜粒、小米椒煸炒 30-45 S ，倒入莴笋中", "搅拌充分，端盘"]'::jsonb, '[{"name": "莴笋 1 根", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "莴笋 1 根"}, {"name": "萝卜 0.25 根", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "萝卜 0.25 根"}, {"name": "小米辣 2 个", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "小米辣 2 个"}, {"name": "姜 1 片", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "姜 1 片"}, {"name": "蒜头 2 粒", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "蒜头 2 粒"}, {"name": "盐 5 g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐 5 g"}, {"name": "食用油 25 ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "食用油 25 ml"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'recipes/images/fc120554b9fc57fbb6ce.jpg', 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/vegetable_dish/%E5%87%89%E6%8B%8C%E8%8E%B4%E7%AC%8B/%E5%87%89%E6%8B%8C%E8%8E%B4%E7%AC%8B.md', '凉拌莴笋 家常菜 通用 莴笋削皮，切小条。萝卜切条，一起放入大碗，加入盐搅拌，放置 10 分钟 放置后的莴笋用水清洗 1-2 遍 起锅烧水，放入莴笋，水煮 1 分钟 捞出，沥干水分，放入大碗 起锅烧油，放入姜片、蒜粒、小米椒煸炒 30-45 s ，倒入莴笋中 搅拌充分，端盘 午餐 晚餐 莴笋 1 根 萝卜 0.25 根 小米辣 2 个 姜 1 片 蒜头 2 粒 盐 5 g 食用油 25 ml'),
('53631cf0-58f1-5ef7-a9ac-bb59b260534f', '凉拌莴笋丝', '家常菜', '通用', '🥒', '莴笋丝脆嫩爽口，盐腌去生、香油提香，开胃凉菜 10 分钟上桌。', '["莴笋去皮切细丝，加盐抓匀腌制 10 分钟。", "腌出的水倒掉，莴笋丝挤干水分。", "加红椒丝、蒜末、白糖、鸡精，淋上芝麻香油。", "充分拌匀，冷藏 10 分钟口感更脆。"]'::jsonb, '[{"name": "莴笋", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": "（约 300 克）", "sourceText": null}, {"name": "红椒丝", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "芝麻香油", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "盐", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "白糖", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}, {"name": "鸡精", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '280 g', '143', '3', '8', '11', '1', '3', '4', NULL, 'A', NULL, '凉拌莴笋丝 家常菜 通用 莴笋丝脆嫩爽口，盐腌去生、香油提香，开胃凉菜 10 分钟上桌。 莴笋去皮切细丝，加盐抓匀腌制 10 分钟。 腌出的水倒掉，莴笋丝挤干水分。 加红椒丝、蒜末、白糖、鸡精，淋上芝麻香油。 充分拌匀，冷藏 10 分钟口感更脆。 凉拌 咸鲜 午餐 晚餐 莴笋 红椒丝 芝麻香油 盐 白糖 鸡精 蒜末'),
('fc0a56c0-42f1-5a96-983a-0fb987efb1f5', '凉拌菠菜', '保持', '通用', '🥬', '菠菜焯水去草酸后凉拌，蒜香加花生碎，营养又爽口的快手凉菜。', '["菠菜洗净，沸水焯 30 秒去草酸，捞出过凉挤干切段。", "粉丝温水泡发后沸水煮 1 分钟过凉，蒜切末。", "菠菜与粉丝装碗，加蒜末、生抽、香醋和香油。", "拌匀撒熟花生碎即可。"]'::jsonb, '[{"name": "菠菜", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干粉丝", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": "（泡发约 90 克）", "sourceText": null}, {"name": "熟花生碎", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香油", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['蒜香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '315', '11', '41', '12', '2.8', '10.3', '3', NULL, 'A', NULL, '凉拌菠菜 保持 通用 菠菜焯水去草酸后凉拌，蒜香加花生碎，营养又爽口的快手凉菜。 菠菜洗净，沸水焯 30 秒去草酸，捞出过凉挤干切段。 粉丝温水泡发后沸水煮 1 分钟过凉，蒜切末。 菠菜与粉丝装碗，加蒜末、生抽、香醋和香油。 拌匀撒熟花生碎即可。 凉拌 蒜香 午餐 晚餐 菠菜 干粉丝 熟花生碎 蒜 生抽 香醋 香油'),
('47c990cb-9fe7-5a5f-8ff8-cf8abb60adfe', '凉拌蕨菜', '家常菜', '徽菜', '🥗', '皖南山野馈赠，蕨菜焯水后口感滑嫩微脆，配蒜末辣椒油凉拌，酸辣开胃，是徽菜馆里的经典小凉菜。', '["蕨菜洗净切段，沸水焯 3 分钟至熟，捞出过凉水沥干。", "将蒜末、辣椒油、香醋、生抽、麻油和盐调成料汁。", "料汁倒入蕨菜拌匀，腌 5 分钟入味后装盘。"]'::jsonb, '[{"name": "蕨菜", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "麻油", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '200 g', '144', '6', '12', '8', '3', '6', '4', NULL, 'A', NULL, '凉拌蕨菜 家常菜 徽菜 皖南山野馈赠，蕨菜焯水后口感滑嫩微脆，配蒜末辣椒油凉拌，酸辣开胃，是徽菜馆里的经典小凉菜。 蕨菜洗净切段，沸水焯 3 分钟至熟，捞出过凉水沥干。 将蒜末、辣椒油、香醋、生抽、麻油和盐调成料汁。 料汁倒入蕨菜拌匀，腌 5 分钟入味后装盘。 凉拌 酸辣 午餐 晚餐 蕨菜 蒜末 辣椒油 香醋 生抽 麻油 盐'),
('9fea329f-5c23-5f61-8795-b4a68ef97e95', '凉拌藕片', '减脂', 'e', '🥗', '莲藕爽脆微甜，凉拌做法清爽低脂，替代薯类主食的好选择。', '["莲藕去皮切薄片，立即泡入清水中防氧化。", "水烧开，下藕片焯烫 2 分钟，捞出过冰水沥干。", "蒜末、小米辣加香醋、生抽、白糖、香油调成料汁。", "藕片装碗，淋料汁拌匀，撒香菜即可。"]'::jsonb, '[{"name": "莲藕", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "白糖", "quantity": "2", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "香油", "quantity": "3", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "小米辣", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "香菜", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '280 g', '198', '5', '40', '2', '1.79', '14.29', '0.71', NULL, 'A', NULL, '凉拌藕片 减脂 e 莲藕爽脆微甜，凉拌做法清爽低脂，替代薯类主食的好选择。 莲藕去皮切薄片，立即泡入清水中防氧化。 水烧开，下藕片焯烫 2 分钟，捞出过冰水沥干。 蒜末、小米辣加香醋、生抽、白糖、香油调成料汁。 藕片装碗，淋料汁拌匀，撒香菜即可。 凉拌 酸辣 午餐 晚餐 莲藕 蒜 香醋 生抽 白糖 香油 小米辣 香菜'),
('45205be7-5e21-5295-a56d-3d095f3fc902', '凉拌西兰花', '保持', '通用', '🥦', '西兰花焯水后凉拌，爽脆清甜，配木耳粉丝营养又顶饱。', '["西兰花掰小朵，沸水加少许盐焯 1 分钟捞出过凉；木耳焯水 1 分钟。", "粉丝泡发后煮 1 分钟过凉，胡萝卜切丝，蒜切末。", "西兰花、木耳、胡萝卜、粉丝装碗，加蒜末、生抽、香醋和香油。", "拌匀，静置 2 分钟入味即可。"]'::jsonb, '[{"name": "西兰花", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "木耳（泡发）", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "胡萝卜", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干粉丝", "quantity": "40", "quantityPrefix": null, "unit": "克", "note": "（泡发约 120 克）", "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香油", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '420 g', '270', '10', '49', '4', '2.4', '11.7', '1', NULL, 'A', NULL, '凉拌西兰花 保持 通用 西兰花焯水后凉拌，爽脆清甜，配木耳粉丝营养又顶饱。 西兰花掰小朵，沸水加少许盐焯 1 分钟捞出过凉；木耳焯水 1 分钟。 粉丝泡发后煮 1 分钟过凉，胡萝卜切丝，蒜切末。 西兰花、木耳、胡萝卜、粉丝装碗，加蒜末、生抽、香醋和香油。 拌匀，静置 2 分钟入味即可。 凉拌 清淡 午餐 晚餐 西兰花 木耳（泡发） 胡萝卜 干粉丝 蒜 生抽 香醋 香油'),
('3a1a0501-a7ce-50c1-bd10-87872f238739', '凉拌豆腐', '家常菜', '通用', '🍽️', '', '["将 豆腐 切成 2 cm 见方的小块，备用。", "锅中加入 500 ml 饮用水，大火烧开。", "放入 豆腐 块，煮 1-2 分钟，以去除豆腥味并使豆腐口感更紧实。", "将 煮好的 豆腐 块捞出，沥干水分，放入碗中，备用。", "将 小葱 洗净，切成葱花，备用。", "将 大蒜 去皮，切成蒜末，备用。", "在一个干净的小碗中，加入 15 ml 生抽，5 ml 香油，5 ml 醋（可选），2 g 白糖（可选）。", "加入切好的 大蒜末。", "搅拌均匀，使 白糖 充分溶解，酱汁混合均匀。", "将制作好的酱汁均匀淋在 豆腐 块上。", "撒上切好的 小葱花。", "根据个人喜好，淋上 5 ml 辣椒油（可选）。", "用 筷子 或勺子轻轻拌匀，即可食用。"]'::jsonb, '[{"name": "豆腐 250 g （约 1 块常见大小的豆腐）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "豆腐 250 g （约 1 块常见大小的豆腐）"}, {"name": "小葱 10 g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "小葱 10 g"}, {"name": "大蒜 2-3 瓣", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "大蒜 2-3 瓣"}, {"name": "生抽 15 ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "生抽 15 ml"}, {"name": "香油 5 ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "香油 5 ml"}, {"name": "醋 5 ml（可选）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "醋 5 ml（可选）"}, {"name": "白糖 2 g（可选）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "白糖 2 g（可选）"}, {"name": "辣椒油 5 ml（可选）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "辣椒油 5 ml（可选）"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], 10, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/vegetable_dish/%E5%87%89%E6%8B%8C%E8%B1%86%E8%85%90.md', '凉拌豆腐 家常菜 通用 将 豆腐 切成 2 cm 见方的小块，备用。 锅中加入 500 ml 饮用水，大火烧开。 放入 豆腐 块，煮 1-2 分钟，以去除豆腥味并使豆腐口感更紧实。 将 煮好的 豆腐 块捞出，沥干水分，放入碗中，备用。 将 小葱 洗净，切成葱花，备用。 将 大蒜 去皮，切成蒜末，备用。 在一个干净的小碗中，加入 15 ml 生抽，5 ml 香油，5 ml 醋（可选），2 g 白糖（可选）。 加入切好的 大蒜末。 搅拌均匀，使 白糖 充分溶解，酱汁混合均匀。 将制作好的酱汁均匀淋在 豆腐 块上。 撒上切好的 小葱花。 根据个人喜好，淋上 5 ml 辣椒油（可选）。 用 筷子 或勺子轻轻拌匀，即可食用。 午餐 晚餐 豆腐 250 g （约 1 块常见大小的豆腐） 小葱 10 g 大蒜 2-3 瓣 生抽 15 ml 香油 5 ml 醋 5 ml（可选） 白糖 2 g（可选） 辣椒油 5 ml（可选）'),
('baddf7cb-6ea0-57ad-8209-544bbfb3c84d', '凉拌豆芽', '保持', '通用', '🥗', '绿豆芽脆嫩爽口，配黄瓜粉丝酸辣凉拌，便宜又开胃的家常凉菜。', '["绿豆芽洗净，沸水焯 1 分钟捞出过凉沥干；粉丝泡发后煮 1 分钟过凉。", "黄瓜、胡萝卜切细丝，蒜切末。", "豆芽、黄瓜、胡萝卜、粉丝装碗，加蒜末、香醋、生抽和辣椒油。", "拌匀撒熟花生碎，静置 2 分钟入味即可。"]'::jsonb, '[{"name": "绿豆芽", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干粉丝", "quantity": "40", "quantityPrefix": null, "unit": "克", "note": "（泡发约 120 克）", "sourceText": null}, {"name": "胡萝卜", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "熟花生碎", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "3", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '420 g', '315', '9', '47', '10', '2.1', '11.2', '2.4', NULL, 'A', NULL, '凉拌豆芽 保持 通用 绿豆芽脆嫩爽口，配黄瓜粉丝酸辣凉拌，便宜又开胃的家常凉菜。 绿豆芽洗净，沸水焯 1 分钟捞出过凉沥干；粉丝泡发后煮 1 分钟过凉。 黄瓜、胡萝卜切细丝，蒜切末。 豆芽、黄瓜、胡萝卜、粉丝装碗，加蒜末、香醋、生抽和辣椒油。 拌匀撒熟花生碎，静置 2 分钟入味即可。 凉拌 酸辣 午餐 晚餐 绿豆芽 黄瓜 干粉丝 胡萝卜 熟花生碎 蒜 香醋 辣椒油'),
('3bdf1266-f82e-5f0f-a775-e0a1f7cec736', '凉拌豌豆粉', '家常菜', '滇菜', '🥗', '豌豆凉粉切条，浇上酸辣酱汁和油辣椒，爽滑弹嫩，夏日消暑小凉菜。', '["豌豆粉加清水调成粉浆，锅中水烧开转小火，倒入粉浆边倒边搅。", "小火熬 10 分钟至浓稠，倒入容器抹平，放凉凝固 2 小时。", "凉粉倒扣切条，装盘。", "蒜末、辣椒油、生抽、醋调成料汁浇上，撒香菜即可。"]'::jsonb, '[{"name": "豌豆粉", "quantity": "120", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "水", "quantity": "900", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香菜", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '336', '15', '42', '12', '5', '14', '4', NULL, 'A', NULL, '凉拌豌豆粉 家常菜 滇菜 豌豆凉粉切条，浇上酸辣酱汁和油辣椒，爽滑弹嫩，夏日消暑小凉菜。 豌豆粉加清水调成粉浆，锅中水烧开转小火，倒入粉浆边倒边搅。 小火熬 10 分钟至浓稠，倒入容器抹平，放凉凝固 2 小时。 凉粉倒扣切条，装盘。 蒜末、辣椒油、生抽、醋调成料汁浇上，撒香菜即可。 凉拌 酸辣 午餐 晚餐 豌豆粉 水 蒜末 辣椒油 生抽 醋 香菜'),
('4b7e705b-bd58-5b10-a646-4cbc5156aeba', '凉拌金针菇', '保持', '通用', '🍄', '金针菇焯水后凉拌，爽滑弹牙，酸辣开胃的平价家常凉菜。', '["金针菇去根撕散，沸水焯 2 分钟捞出过凉挤干。", "粉丝泡发后煮 1 分钟过凉，黄瓜切丝，蒜切末。", "金针菇、黄瓜、粉丝装碗，加蒜末、香醋、生抽和辣椒油。", "拌匀撒香菜即可。"]'::jsonb, '[{"name": "金针菇", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干粉丝", "quantity": "40", "quantityPrefix": null, "unit": "克", "note": "（泡发约 120 克）", "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "3", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "香菜", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '280', '7', '51', '5', '1.8', '12.8', '1.3', NULL, 'A', NULL, '凉拌金针菇 保持 通用 金针菇焯水后凉拌，爽滑弹牙，酸辣开胃的平价家常凉菜。 金针菇去根撕散，沸水焯 2 分钟捞出过凉挤干。 粉丝泡发后煮 1 分钟过凉，黄瓜切丝，蒜切末。 金针菇、黄瓜、粉丝装碗，加蒜末、香醋、生抽和辣椒油。 拌匀撒香菜即可。 凉拌 酸辣 午餐 晚餐 金针菇 黄瓜 干粉丝 蒜 香醋 生抽 辣椒油 香菜'),
('f0d3d7ce-bd80-5a69-8d82-2b6b32249aac', '凉拌魔芋结', '减脂', '通用', '🥗', '魔芋结近乎零热量，脆弹爽口，酸辣凉拌是减脂解馋利器。', '["魔芋结用清水冲洗两遍，沸水煮 2 分钟捞出过凉沥干。", "黄瓜拍碎切段，蒜切末。", "香醋、生抽、辣椒油、蒜末调成料汁。", "魔芋结与黄瓜拌匀，淋料汁撒香菜即可。"]'::jsonb, '[{"name": "魔芋结", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "0.5", "quantityPrefix": null, "unit": "根", "note": "（约 60 克）", "sourceText": null}, {"name": "蒜", "quantity": "2", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "3", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "香菜", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '300 g', '59', '2', '6', '3', '0.67', '2', '1', NULL, 'A', NULL, '凉拌魔芋结 减脂 通用 魔芋结近乎零热量，脆弹爽口，酸辣凉拌是减脂解馋利器。 魔芋结用清水冲洗两遍，沸水煮 2 分钟捞出过凉沥干。 黄瓜拍碎切段，蒜切末。 香醋、生抽、辣椒油、蒜末调成料汁。 魔芋结与黄瓜拌匀，淋料汁撒香菜即可。 凉拌 酸辣 晚餐 魔芋结 黄瓜 蒜 香醋 生抽 辣椒油 香菜'),
('4be701b4-8b7e-59bc-9e91-a7d3ad40e696', '凉拌鸡丝', '减脂', '通用', '🥗', '鸡胸肉水煮手撕，配清爽黄瓜丝，高蛋白低脂的夏日凉菜。', '["鸡胸肉冷水下锅，加姜片料酒，中火煮 12 分钟至熟透。", "捞出放凉后顺纹理撕成细丝，黄瓜、胡萝卜切细丝。", "蒜切末，与香醋、生抽、香油调成料汁。", "鸡丝与蔬菜丝拌匀，淋入料汁，撒香菜即可。"]'::jsonb, '[{"name": "鸡胸肉", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": "（约 100 克）", "sourceText": null}, {"name": "胡萝卜", "quantity": "40", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "2", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香油", "quantity": "3", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "香菜", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮', '凉拌']::TEXT[], ARRAY['蒜香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '280 g', '222', '34', '8', '6', '12.1', '2.9', '2.1', 'recipes/images/d9904098db67b351ecd9.jpg', 'A', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/meat_dish/%E5%87%89%E6%8B%8C%E9%B8%A1%E4%B8%9D/%E5%87%89%E6%8B%8C%E9%B8%A1%E4%B8%9D.md', '凉拌鸡丝 减脂 通用 鸡胸肉水煮手撕，配清爽黄瓜丝，高蛋白低脂的夏日凉菜。 鸡胸肉冷水下锅，加姜片料酒，中火煮 12 分钟至熟透。 捞出放凉后顺纹理撕成细丝，黄瓜、胡萝卜切细丝。 蒜切末，与香醋、生抽、香油调成料汁。 鸡丝与蔬菜丝拌匀，淋入料汁，撒香菜即可。 煮 凉拌 蒜香 午餐 晚餐 鸡胸肉 黄瓜 胡萝卜 蒜 香醋 生抽 香油 香菜'),
('e148a6dc-cead-50b6-8b39-8781dc416ce5', '凉拌鸡丝荞麦面', '减脂', '通用', '🍜', '荞麦面低升糖又饱腹，鸡丝高蛋白，酸辣开胃的夏日减脂主食。', '["荞麦面沸水煮 5–6 分钟，捞出过凉水沥干，拌少许香油防粘。", "鸡胸肉冷水下锅，加姜片料酒煮 12 分钟，捞出放凉后撕成细丝。", "黄瓜、胡萝卜切细丝，蒜切末、香菜切段。", "将生抽、香醋、辣椒油、蒜末调成料汁。", "面条装碗，铺上鸡丝和蔬菜丝，淋料汁拌匀即可。"]'::jsonb, '[{"name": "荞麦面（干）", "quantity": "70", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡胸肉", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "0.5", "quantityPrefix": null, "unit": "根", "note": "（约 60 克）", "sourceText": null}, {"name": "胡萝卜", "quantity": "30", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜末、香菜", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": "+ 香醋 1 勺 + 辣椒油 2 克", "sourceText": null}]'::jsonb, ARRAY['煮', '凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '390 g', '424', '34', '52', '9', '8.7', '13.3', '2.3', NULL, 'A', NULL, '凉拌鸡丝荞麦面 减脂 通用 荞麦面低升糖又饱腹，鸡丝高蛋白，酸辣开胃的夏日减脂主食。 荞麦面沸水煮 5–6 分钟，捞出过凉水沥干，拌少许香油防粘。 鸡胸肉冷水下锅，加姜片料酒煮 12 分钟，捞出放凉后撕成细丝。 黄瓜、胡萝卜切细丝，蒜切末、香菜切段。 将生抽、香醋、辣椒油、蒜末调成料汁。 面条装碗，铺上鸡丝和蔬菜丝，淋料汁拌匀即可。 煮 凉拌 酸辣 午餐 晚餐 荞麦面（干） 鸡胸肉 黄瓜 胡萝卜 蒜末、香菜 生抽'),
('177ddaab-6a94-5397-baa7-58470f760f55', '凉拌鸡胸', '减脂', '通用', '🍗', '水煮鸡胸切薄片凉拌，酸辣料汁开胃，高蛋白低脂快手菜。', '["鸡胸肉冷水下锅，加姜片料酒，中火煮 12 分钟至熟透。", "捞出放凉切薄片，黄瓜切片，木耳焯水后切丝。", "蒜末与生抽、香醋、辣椒油调成料汁。", "鸡片与配菜装盘，淋料汁撒香菜拌匀。"]'::jsonb, '[{"name": "鸡胸肉", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "0.5", "quantityPrefix": null, "unit": "根", "note": "（约 50 克）", "sourceText": null}, {"name": "木耳（泡发）", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "2", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "2", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "香菜", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮', '凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '320 g', '278', '48', '8', '6', '15', '2.5', '1.8', NULL, 'A', NULL, '凉拌鸡胸 减脂 通用 水煮鸡胸切薄片凉拌，酸辣料汁开胃，高蛋白低脂快手菜。 鸡胸肉冷水下锅，加姜片料酒，中火煮 12 分钟至熟透。 捞出放凉切薄片，黄瓜切片，木耳焯水后切丝。 蒜末与生抽、香醋、辣椒油调成料汁。 鸡片与配菜装盘，淋料汁撒香菜拌匀。 煮 凉拌 酸辣 午餐 晚餐 鸡胸肉 黄瓜 木耳（泡发） 蒜 生抽 香醋 辣椒油 香菜'),
('221273c2-e707-5d44-9a2a-089ab02c9bbb', '凉拌黄瓜', '家常菜', '通用', '🥒', '拍黄瓜最入味，蒜醋香辣汁一拌，爽脆解腻的万能凉菜。', '["黄瓜洗净，用刀背拍裂后切段，加半勺盐腌 5 分钟，倒掉析出的水。", "蒜末、小米椒、香醋、生抽、糖、香油、辣椒油调成料汁。", "料汁浇在黄瓜上，拌匀腌制 10 分钟更入味。"]'::jsonb, '[{"name": "黄瓜", "quantity": "400", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "小米椒", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "白糖", "quantity": "0.5", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "香油", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '420 g', '155', '3', '11', '11', '0.7', '2.6', '2.6', NULL, 'A', NULL, '凉拌黄瓜 家常菜 通用 拍黄瓜最入味，蒜醋香辣汁一拌，爽脆解腻的万能凉菜。 黄瓜洗净，用刀背拍裂后切段，加半勺盐腌 5 分钟，倒掉析出的水。 蒜末、小米椒、香醋、生抽、糖、香油、辣椒油调成料汁。 料汁浇在黄瓜上，拌匀腌制 10 分钟更入味。 凉拌 酸辣 午餐 晚餐 黄瓜 蒜末 小米椒 香醋 生抽 白糖 香油 辣椒油'),
('0f32b7ec-c7ac-52c0-ac31-791d682b95bc', '凉皮', '小吃', '北方菜', '🥒', '米浆蒸出的凉皮透亮筋道，配面筋黄瓜丝，浇上油泼辣子和醋汁，酸辣开胃。', '["凉皮切宽条，面筋切块，黄瓜切丝，豆芽焯水过凉。", "蒜捣碎加凉白开调成蒜水，辣椒油、香醋、生抽混合成料汁。", "凉皮、面筋、黄瓜丝、豆芽装入大碗。", "浇上料汁和蒜水，拌匀开吃。"]'::jsonb, '[{"name": "凉皮", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "面筋", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄瓜", "quantity": "0.5", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "豆芽", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "辣椒油", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒜水", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '350 g', '373', '14', '77', '1', '4', '22', '0.4', NULL, 'A', NULL, '凉皮 小吃 北方菜 米浆蒸出的凉皮透亮筋道，配面筋黄瓜丝，浇上油泼辣子和醋汁，酸辣开胃。 凉皮切宽条，面筋切块，黄瓜切丝，豆芽焯水过凉。 蒜捣碎加凉白开调成蒜水，辣椒油、香醋、生抽混合成料汁。 凉皮、面筋、黄瓜丝、豆芽装入大碗。 浇上料汁和蒜水，拌匀开吃。 凉拌 酸辣 午餐 晚餐 凉皮 面筋 黄瓜 豆芽 辣椒油 香醋 生抽 蒜水'),
('936569ec-49ba-5789-85dd-1eaea3b9c39d', '凉粉', '家常菜', '通用', '🍽️', '', '["准备食材。", "把豌豆淀粉和水各 100 克混合搅拌。", "往锅中倒入 600g 水，大火煮开后转为小火。", "倒入淀粉水，边倒边不断的搅拌，搅拌到浓稠且色泽均匀。", "找一个容器，在容器中刷一层薄薄的食用油。", "将煮好的淀粉倒入容器中冷藏 2-4 小时。", "冷藏后取出，脱模，切条。", "大蒜和小米辣剁成沫，放上 10g 辣椒粉，5g 花生碎，热油搅拌均匀。", "再加入 10ml 酱油，10ml 醋，5g 白糖，3g 鸡精，3g 盐搅拌均匀。", "将调味料倒在凉粉上，然后撒上香菜即可。"]'::jsonb, '[{"name": "豌豆淀粉 100g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "豌豆淀粉  100g"}, {"name": "大蒜 3 瓣", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "大蒜   3 瓣"}, {"name": "小米辣 3 颗", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "小米辣  3 颗"}, {"name": "辣椒粉 10g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "辣椒粉  10g"}, {"name": "酱油 10ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "酱油   10ml"}, {"name": "醋 10ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "醋   10ml"}, {"name": "白糖 3ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "白糖  3ml"}, {"name": "鸡精 3g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "鸡精  3g"}, {"name": "盐 3g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐  3g"}, {"name": "花生碎 5g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "花生碎  5g"}, {"name": "香菜 5g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "香菜  5g"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'recipes/images/83c2759e7cb25a73eae2.jpg', 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/staple/%E5%87%89%E7%B2%89/%E5%87%89%E7%B2%89.md', '凉粉 家常菜 通用 准备食材。 把豌豆淀粉和水各 100 克混合搅拌。 往锅中倒入 600g 水，大火煮开后转为小火。 倒入淀粉水，边倒边不断的搅拌，搅拌到浓稠且色泽均匀。 找一个容器，在容器中刷一层薄薄的食用油。 将煮好的淀粉倒入容器中冷藏 2-4 小时。 冷藏后取出，脱模，切条。 大蒜和小米辣剁成沫，放上 10g 辣椒粉，5g 花生碎，热油搅拌均匀。 再加入 10ml 酱油，10ml 醋，5g 白糖，3g 鸡精，3g 盐搅拌均匀。 将调味料倒在凉粉上，然后撒上香菜即可。 午餐 晚餐 豌豆淀粉 100g 大蒜 3 瓣 小米辣 3 颗 辣椒粉 10g 酱油 10ml 醋 10ml 白糖 3ml 鸡精 3g 盐 3g 花生碎 5g 香菜 5g'),
('8fae98b2-4be3-57d0-b1f8-9ada3e76e7ca', '凉糕', '小吃', '川菜', '🍮', '米浆熬制晾凉切块，浇红糖水冰镇食用，滑嫩清凉，川渝夏天解暑首选。', '["大米浸泡 3 小时，加清水磨成米浆。", "米浆倒入锅中，加入澄清的石灰水，小火不停搅拌熬至浓稠熟透。", "倒入模具晾凉凝固，切成小方块。", "红糖加水熬化晾凉，浇在凉糕上冰镇食用。"]'::jsonb, '[{"name": "大米", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "食用石灰水", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "红糖", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "清水", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['熬']::TEXT[], ARRAY['甜', '清淡']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '200 g', '193', '2', '44', '1', '1', '22', '0.5', NULL, 'A', NULL, '凉糕 小吃 川菜 米浆熬制晾凉切块，浇红糖水冰镇食用，滑嫩清凉，川渝夏天解暑首选。 大米浸泡 3 小时，加清水磨成米浆。 米浆倒入锅中，加入澄清的石灰水，小火不停搅拌熬至浓稠熟透。 倒入模具晾凉凝固，切成小方块。 红糖加水熬化晾凉，浇在凉糕上冰镇食用。 熬 甜 清淡 晚餐 大米 食用石灰水 红糖 清水'),
('20720e5f-e6ef-5788-9519-c108cfc6e314', '凤凰蛋（活珠子）', '小吃', '徽菜', '🥚', '孵化十余天的受精鸡蛋，清水慢煮后蘸椒盐食用，蛋白Q弹、蛋黄绵密，安徽街头特色小吃。', '["活珠子洗净外壳，冷水入锅，加入 1 小勺盐。", "大火烧开后转小火慢煮 20 分钟，捞出稍晾至不烫手。", "剥开气室一端，先吸汤汁，再剥壳蘸椒盐食用。"]'::jsonb, '[{"name": "活珠子", "quantity": "2", "quantityPrefix": null, "unit": "枚", "note": null, "sourceText": null}, {"name": "清水", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "盐", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "椒盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '90 g', '148', '11', '2', '11', '12', '2', '12', NULL, 'A', NULL, '凤凰蛋（活珠子） 小吃 徽菜 孵化十余天的受精鸡蛋，清水慢煮后蘸椒盐食用，蛋白q弹、蛋黄绵密，安徽街头特色小吃。 活珠子洗净外壳，冷水入锅，加入 1 小勺盐。 大火烧开后转小火慢煮 20 分钟，捞出稍晾至不烫手。 剥开气室一端，先吸汤汁，再剥壳蘸椒盐食用。 煮 咸鲜 晚餐 活珠子 清水 盐 椒盐'),
('fb5a0d3e-9b7e-5c22-9138-e39abe5af2d7', '凤爪蒸豆米', '家常菜', '通用', '🫘', '咸鸡爪与毛豆米同蒸，鸡油香渗进豆米，家常蒸菜快手味。', '["咸鸡爪提前蒸 25 分钟至软，剁成小块。", "毛豆米铺入蒸碗，撒盐、鸡精，淋鸡油和鸡汤。", "鸡爪块平铺在豆米上，蒸锅上汽后蒸 12 分钟。", "出锅拌匀即可。"]'::jsonb, '[{"name": "咸鸡爪", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "毛豆米", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "盐", "quantity": "1", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡精", "quantity": "1", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡汤", "quantity": "30", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}, {"name": "鸡油", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['蒸']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '250 g', '315', '25', '20', '15', '10', '8', '6', NULL, 'A', NULL, '凤爪蒸豆米 家常菜 通用 咸鸡爪与毛豆米同蒸，鸡油香渗进豆米，家常蒸菜快手味。 咸鸡爪提前蒸 25 分钟至软，剁成小块。 毛豆米铺入蒸碗，撒盐、鸡精，淋鸡油和鸡汤。 鸡爪块平铺在豆米上，蒸锅上汽后蒸 12 分钟。 出锅拌匀即可。 蒸 咸鲜 午餐 晚餐 咸鸡爪 毛豆米 盐 鸡精 鸡汤 鸡油'),
('de58814c-cb7a-59f9-a676-05f4e0eeb6b2', '刀板香', '家常菜', '徽菜', '🥓', '徽州腊味代表，咸肉腌好后与笋同蒸，肉香脂香渗透笋中，切厚片码在木板上，肥而不腻、咸鲜回甘。', '["咸肉温水浸泡 30 分钟去部分盐分，切厚片。", "春笋切滚刀块铺在盘底，码上咸肉片，放姜片、料酒。", "大火上锅蒸 30 分钟至咸肉透明出油。", "拣去姜片，撒葱花，趁热食用。"]'::jsonb, '[{"name": "徽州咸肉", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "春笋", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜片", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}]'::jsonb, ARRAY['蒸']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '150 g', '411', '24', '5', '33', '16', '3', '22', NULL, 'A', NULL, '刀板香 家常菜 徽菜 徽州腊味代表，咸肉腌好后与笋同蒸，肉香脂香渗透笋中，切厚片码在木板上，肥而不腻、咸鲜回甘。 咸肉温水浸泡 30 分钟去部分盐分，切厚片。 春笋切滚刀块铺在盘底，码上咸肉片，放姜片、料酒。 大火上锅蒸 30 分钟至咸肉透明出油。 拣去姜片，撒葱花，趁热食用。 蒸 咸鲜 午餐 晚餐 徽州咸肉 春笋 姜片 料酒 小葱'),
('ce39755f-a78e-5a4d-b841-eecad60c2157', '利提巧卡', '家常菜', '通用', '🍽️', '', '["制作利提馅料", "在碗中混合烤鹰嘴豆粉 120g、切碎的洋葱、青辣椒、生姜", "加入孜然籽 3g、芝麻 5g、红辣椒粉 3g、印度黑盐 3g、盐 3g", "加入芥末油 15ml、柠檬汁 10ml、切碎的香菜叶", "充分混合均匀，馅料应呈松散但可捏合的状态，备用", "制作利提面团", "将全麦面粉 200g 放入大碗中", "逐渐加入温水，边加边揉，揉成光滑柔软的面团", "面团静置 15 分钟", "将面团分成 8 个等大的小剂子", "每个剂子用手压成一个直径约 8cm 的圆形面片（中间稍厚）", "在面片中央放入约 15g 馅料", "将面片四周收拢包住馅料，封口处捏紧，搓成圆球", "烤制利提", "烤箱预热至 200°C", "将利提放在烤盘上，烤 25-30 分钟，期间翻面一次，直至表面金棕色且有裂纹", "如果使用明火：将利提直接放在炭火或煤气灶小火上烤，不断翻转，直至均匀焦黄", "烤好后趁热将每个利提表面涂上酥油，使其浸润吸收", "制作巧卡", "将茄子、番茄、土豆放在明火上直接烤，或放入 200°C 烤箱烤 20-25 分钟，直至外皮焦黑、内部完全软烂", "烤好后去皮，将茄子、番茄、土豆分别用叉子或手捣碎", "将捣碎的蔬菜混合在一起", "加入切碎的大蒜、青辣椒、盐 4g、芥末油 15ml", "充分搅拌混合均匀", "撒上香菜叶装饰", "上菜", "将利提摆盘，旁边放上巧卡蔬菜泥", "趁热食用，用手掰开利提蘸巧卡"]'::jsonb, '[{"name": "全麦面粉 200g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "全麦面粉 200g"}, {"name": "烤鹰嘴豆粉 120g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "烤鹰嘴豆粉 120g"}, {"name": "洋葱 1 个（约 80g），切极细碎", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "洋葱 1 个（约 80g），切极细碎"}, {"name": "青辣椒 2 根，切极细碎", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "青辣椒 2 根，切极细碎"}, {"name": "生姜 5g，磨碎", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "生姜 5g，磨碎"}, {"name": "芥末油 15ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "芥末油 15ml"}, {"name": "柠檬汁 10ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "柠檬汁 10ml"}, {"name": "香菜叶 10g，切碎", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "香菜叶 10g，切碎"}, {"name": "孜然籽 3g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "孜然籽 3g"}, {"name": "芝麻 5g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "芝麻 5g"}, {"name": "红辣椒粉 3g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "红辣椒粉 3g"}, {"name": "印度黑盐 3g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "印度黑盐 3g"}, {"name": "盐 3g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐 3g"}, {"name": "温水 约 100ml（用于和面）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "温水 约 100ml（用于和面）"}, {"name": "酥油 30g（烤好后涂抹用）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "酥油 30g（烤好后涂抹用）"}, {"name": "茄子 1 个（约 250g）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "茄子 1 个（约 250g）"}, {"name": "番茄 2 个（约 180g）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "番茄 2 个（约 180g）"}, {"name": "土豆 2 个（约 240g）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "土豆 2 个（约 240g）"}, {"name": "大蒜 4 瓣（约 12g）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "大蒜 4 瓣（约 12g）"}, {"name": "青辣椒 1 根", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "青辣椒 1 根"}, {"name": "芥末油 15ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "芥末油 15ml"}, {"name": "盐 4g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐 4g"}, {"name": "香菜叶 10g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "香菜叶 10g"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], 60, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/staple/%E5%88%A9%E6%8F%90%E5%B7%A7%E5%8D%A1.md', '利提巧卡 家常菜 通用 制作利提馅料 在碗中混合烤鹰嘴豆粉 120g、切碎的洋葱、青辣椒、生姜 加入孜然籽 3g、芝麻 5g、红辣椒粉 3g、印度黑盐 3g、盐 3g 加入芥末油 15ml、柠檬汁 10ml、切碎的香菜叶 充分混合均匀，馅料应呈松散但可捏合的状态，备用 制作利提面团 将全麦面粉 200g 放入大碗中 逐渐加入温水，边加边揉，揉成光滑柔软的面团 面团静置 15 分钟 将面团分成 8 个等大的小剂子 每个剂子用手压成一个直径约 8cm 的圆形面片（中间稍厚） 在面片中央放入约 15g 馅料 将面片四周收拢包住馅料，封口处捏紧，搓成圆球 烤制利提 烤箱预热至 200°c 将利提放在烤盘上，烤 25-30 分钟，期间翻面一次，直至表面金棕色且有裂纹 如果使用明火：将利提直接放在炭火或煤气灶小火上烤，不断翻转，直至均匀焦黄 烤好后趁热将每个利提表面涂上酥油，使其浸润吸收 制作巧卡 将茄子、番茄、土豆放在明火上直接烤，或放入 200°c 烤箱烤 20-25 分钟，直至外皮焦黑、内部完全软烂 烤好后去皮，将茄子、番茄、土豆分别用叉子或手捣碎 将捣碎的蔬菜混合在一起 加入切碎的大蒜、青辣椒、盐 4g、芥末油 15ml 充分搅拌混合均匀 撒上香菜叶装饰 上菜 将利提摆盘，旁边放上巧卡蔬菜泥 趁热食用，用手掰开利提蘸巧卡 午餐 晚餐 全麦面粉 200g 烤鹰嘴豆粉 120g 洋葱 1 个（约 80g），切极细碎 青辣椒 2 根，切极细碎 生姜 5g，磨碎 芥末油 15ml 柠檬汁 10ml 香菜叶 10g，切碎 孜然籽 3g 芝麻 5g 红辣椒粉 3g 印度黑盐 3g 盐 3g 温水 约 100ml（用于和面） 酥油 30g（烤好后涂抹用） 茄子 1 个（约 250g） 番茄 2 个（约 180g） 土豆 2 个（约 240g） 大蒜 4 瓣（约 12g） 青辣椒 1 根 芥末油 15ml 盐 4g 香菜叶 10g'),
('42b727bf-58ab-5cca-83a2-2fd4896d3604', '剁椒木耳炒鸡蛋', '家常菜', '湘菜', '🍳', '鸡蛋先炒成大片，再与剁椒木耳爆炒，酸辣爽脆。', '["鸡蛋加少许盐打散；木耳撕小朵焯水 1 分钟。", "热锅多油，倒入蛋液炒成大块蛋片，盛出备用。", "锅留底油，下蒜片、剁椒炒香，倒入木耳大火爆炒 1 分钟。", "倒回蛋片，加盐、鸡精翻匀，撒葱段出锅。"]'::jsonb, '[{"name": "鸡蛋", "quantity": "4", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "泡发木耳", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "剁椒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "盐", "quantity": "2", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡精", "quantity": "1", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "香葱", "quantity": "2", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}]'::jsonb, ARRAY['炒']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '250 g', '349', '18', '13', '25', '7', '5', '10', NULL, 'A', NULL, '剁椒木耳炒鸡蛋 家常菜 湘菜 鸡蛋先炒成大片，再与剁椒木耳爆炒，酸辣爽脆。 鸡蛋加少许盐打散；木耳撕小朵焯水 1 分钟。 热锅多油，倒入蛋液炒成大块蛋片，盛出备用。 锅留底油，下蒜片、剁椒炒香，倒入木耳大火爆炒 1 分钟。 倒回蛋片，加盐、鸡精翻匀，撒葱段出锅。 炒 酸辣 午餐 晚餐 鸡蛋 泡发木耳 剁椒 蒜 盐 鸡精 香葱'),
('ff90abbd-4a6a-57dc-b47f-106a3991a8ed', '剁椒芽白', '家常菜', '湘菜', '🥬', '芽白（娃娃菜）配剁椒清炒，酸辣脆嫩、汁水丰盈，两分钟出锅的快手菜。', '["娃娃菜洗净，顺长切四瓣。", "热锅下油，爆香蒜片，下剁椒炒出酸香。", "倒入娃娃菜大火翻炒 2 分钟，至菜帮断生。", "沿锅边淋香醋，加生抽、盐翻匀即可出锅。"]'::jsonb, '[{"name": "娃娃菜", "quantity": "3", "quantityPrefix": null, "unit": "棵", "note": null, "sourceText": null}, {"name": "剁椒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "0.5", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}]'::jsonb, ARRAY['炒']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '246', '6', '15', '18', '2', '5', '6', NULL, 'A', NULL, '剁椒芽白 家常菜 湘菜 芽白（娃娃菜）配剁椒清炒，酸辣脆嫩、汁水丰盈，两分钟出锅的快手菜。 娃娃菜洗净，顺长切四瓣。 热锅下油，爆香蒜片，下剁椒炒出酸香。 倒入娃娃菜大火翻炒 2 分钟，至菜帮断生。 沿锅边淋香醋，加生抽、盐翻匀即可出锅。 炒 酸辣 午餐 晚餐 娃娃菜 剁椒 蒜 香醋 生抽 盐'),
('69a38e46-5218-528d-ad5c-8faf3172de78', '剁椒萝卜干', '小吃', '湘菜', '🥕', '萝卜干晒到半干，拌上剁椒蒜末，咸辣脆爽，佐粥下饭都停不下来。', '["白萝卜切条，晾晒 2 天至半干。", "萝卜干温水洗净，挤干水分。", "加剁椒、蒜末、白糖、生抽、香油拌匀。", "装瓶密封，冷藏腌 2 天入味后即可食用。"]'::jsonb, '[{"name": "白萝卜", "quantity": "500", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "剁椒", "quantity": "3", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "4", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "白糖", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香油", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['凉拌']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['早餐', '午餐']::TEXT[], NULL, NULL, '200 g', '212', '6', '20', '12', '3', '10', '6', NULL, 'A', NULL, '剁椒萝卜干 小吃 湘菜 萝卜干晒到半干，拌上剁椒蒜末，咸辣脆爽，佐粥下饭都停不下来。 白萝卜切条，晾晒 2 天至半干。 萝卜干温水洗净，挤干水分。 加剁椒、蒜末、白糖、生抽、香油拌匀。 装瓶密封，冷藏腌 2 天入味后即可食用。 凉拌 酸辣 早餐 午餐 白萝卜 剁椒 蒜 白糖 生抽 香油'),
('b833f41a-284a-5e6a-96a9-1686707d3f94', '剁椒蒸芋头', '家常菜', '湘菜', '🍠', '芋头切块垫底铺剁椒，蒸到粉糯绵软，吸饱酸辣汁，软糯又开胃。', '["芋头去皮洗净，切成滚刀块，码入盘中。", "剁椒、蒜末、生抽、香油拌匀，铺在芋头上。", "水开上锅大火蒸 20 分钟，至芋头粉糯。", "撒葱花，淋少许热油即可。"]'::jsonb, '[{"name": "小芋头", "quantity": "500", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "剁椒", "quantity": "3", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "4", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "香油", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "葱花", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['蒸']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '312', '9', '42', '12', '3', '14', '4', NULL, 'A', NULL, '剁椒蒸芋头 家常菜 湘菜 芋头切块垫底铺剁椒，蒸到粉糯绵软，吸饱酸辣汁，软糯又开胃。 芋头去皮洗净，切成滚刀块，码入盘中。 剁椒、蒜末、生抽、香油拌匀，铺在芋头上。 水开上锅大火蒸 20 分钟，至芋头粉糯。 撒葱花，淋少许热油即可。 蒸 酸辣 午餐 晚餐 小芋头 剁椒 蒜 生抽 香油 葱花'),
('e7e361a3-2446-5b1a-85a5-ed518c1a7405', '剁椒蒸鱼', '家常菜', '湘菜', '🐟', '整条鲈鱼铺剁椒蒸制，鱼肉鲜嫩吸满酸辣，豉油提鲜，蒸菜里的清爽担当。', '["鲈鱼处理干净，鱼身划刀，用料酒、姜片腌 10 分钟。", "剁椒与蒜末拌匀，铺在鱼身和鱼腹内。", "水开上锅大火蒸 8 分钟，关火再焖 2 分钟。", "倒掉盘中腥水，淋蒸鱼豉油，撒葱花，浇一勺热油激香即可。"]'::jsonb, '[{"name": "鲈鱼", "quantity": "1", "quantityPrefix": null, "unit": "条", "note": "（约 600 克）", "sourceText": null}, {"name": "剁椒", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "1", "quantityPrefix": null, "unit": "块", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "4", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "2", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒸鱼豉油", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['蒸']::TEXT[], ARRAY['酸辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '350 g', '386', '42', '14', '18', '12', '4', '5', NULL, 'A', NULL, '剁椒蒸鱼 家常菜 湘菜 整条鲈鱼铺剁椒蒸制，鱼肉鲜嫩吸满酸辣，豉油提鲜，蒸菜里的清爽担当。 鲈鱼处理干净，鱼身划刀，用料酒、姜片腌 10 分钟。 剁椒与蒜末拌匀，铺在鱼身和鱼腹内。 水开上锅大火蒸 8 分钟，关火再焖 2 分钟。 倒掉盘中腥水，淋蒸鱼豉油，撒葱花，浇一勺热油激香即可。 蒸 酸辣 午餐 晚餐 鲈鱼 剁椒 姜 蒜 小葱 料酒 蒸鱼豉油'),
('c92acc0a-b6bd-5620-8922-7c89e2e038c0', '剁椒鱼头', '家常菜', '湘菜', '🐠', '湘菜经典，胖头鱼头铺满红亮剁椒，鲜辣开胃，肉质肥嫩。', '["鱼头从中间劈开洗净，用料酒和姜片腌 15 分钟去腥。", "剁椒加蒜末和少许食用油拌匀，铺满鱼头表面。", "蒸锅水开后放入鱼头，大火蒸 12 分钟至熟透。", "取出撒上葱花，淋蒸鱼豉油，再浇一勺烧热的油激香即可。"]'::jsonb, '[{"name": "胖头鱼鱼头", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": "（约 600 克）", "sourceText": null}, {"name": "剁椒", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "1", "quantityPrefix": null, "unit": "块", "note": null, "sourceText": null}, {"name": "大蒜", "quantity": "4", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "2", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "蒸鱼豉油", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['蒸']::TEXT[], ARRAY['辣']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '420 g', '450', '51', '8', '24', '12.1', '1.9', '5.7', NULL, 'A', NULL, '剁椒鱼头 家常菜 湘菜 湘菜经典，胖头鱼头铺满红亮剁椒，鲜辣开胃，肉质肥嫩。 鱼头从中间劈开洗净，用料酒和姜片腌 15 分钟去腥。 剁椒加蒜末和少许食用油拌匀，铺满鱼头表面。 蒸锅水开后放入鱼头，大火蒸 12 分钟至熟透。 取出撒上葱花，淋蒸鱼豉油，再浇一勺烧热的油激香即可。 蒸 辣 晚餐 胖头鱼鱼头 剁椒 姜 大蒜 小葱 料酒 蒸鱼豉油 食用油'),
('ebe19e7a-9587-5540-b7fb-d44ca5894512', '勾芡香菇汤', '家常菜', '通用', '🍽️', '', '["香菇切片（每片厚度 0.5-1 cm,厚点相对薄点更有嚼劲），放入大碗中，倒入 2g 食用盐 浸泡 15 分钟", "生粉倒入小碗中，加入 50ml 水，搅拌生粉直至融化没有颗粒（即水淀粉）", "倒掉碗中的盐水，适当去掉香菇本身的水分（方便下一步煎炸）【可选】", "小火，倒入油，待油开始冒小泡（小火 30s ，看每个锅的功率），倒入香菇，每面煎 10s 【可选】", "倒入开水 300ml ，调中火再煮 3-5 分钟", "倒入水淀粉，适当搅拌锅中汤汁后，加入 3g 盐、3 g ，最后撒上葱花出锅"]'::jsonb, '[{"name": "鲜香菇 2 朵", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "鲜香菇 2 朵"}, {"name": "香葱 0.5 根", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "香葱 0.5 根"}, {"name": "鸡精 3 g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "鸡精 3 g"}, {"name": "食用油 10 ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "食用油 10 ml"}, {"name": "食用盐 3 g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "食用盐 3 g"}, {"name": "开水 350 ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "开水 350 ml"}, {"name": "生粉 10 g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "生粉 10 g"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], 25, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'recipes/images/3c05ffd63abd9ea2e52a.jpg', 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/soup/%E5%8B%BE%E8%8A%A1%E9%A6%99%E8%8F%87%E6%B1%A4/%E5%8B%BE%E8%8A%A1%E9%A6%99%E8%8F%87%E6%B1%A4.md', '勾芡香菇汤 家常菜 通用 香菇切片（每片厚度 0.5-1 cm,厚点相对薄点更有嚼劲），放入大碗中，倒入 2g 食用盐 浸泡 15 分钟 生粉倒入小碗中，加入 50ml 水，搅拌生粉直至融化没有颗粒（即水淀粉） 倒掉碗中的盐水，适当去掉香菇本身的水分（方便下一步煎炸）【可选】 小火，倒入油，待油开始冒小泡（小火 30s ，看每个锅的功率），倒入香菇，每面煎 10s 【可选】 倒入开水 300ml ，调中火再煮 3-5 分钟 倒入水淀粉，适当搅拌锅中汤汁后，加入 3g 盐、3 g ，最后撒上葱花出锅 午餐 晚餐 鲜香菇 2 朵 香葱 0.5 根 鸡精 3 g 食用油 10 ml 食用盐 3 g 开水 350 ml 生粉 10 g'),
('77d02c54-b5c5-5ed1-be90-8a416fccf368', '包烧豆腐', '家常菜', '滇菜', '🍃', '芭蕉叶裹着豆腐与肉末炭火烤制，叶香锁住汁水，外焦里嫩、香辣入味。', '["豆腐切厚块，小米辣、蒜末、香茅草、香菜剁碎，与肉末加盐拌匀成馅。", "豆腐块码在泡软的芭蕉叶上，铺上馅料。", "芭蕉叶包紧，用牙签封口。", "放入烤箱 200℃ 烤 20 分钟，或炭火烤至叶面焦黄出香即可。"]'::jsonb, '[{"name": "老豆腐", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "猪肉末", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "小米辣", "quantity": "4", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "蒜末", "quantity": "4", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "香菜", "quantity": "1", "quantityPrefix": null, "unit": "把", "note": null, "sourceText": null}, {"name": "香茅草", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "芭蕉叶", "quantity": "2", "quantityPrefix": null, "unit": "张", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['烤']::TEXT[], ARRAY['辣']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '411', '24', '18', '27', '8', '6', '9', NULL, 'A', NULL, '包烧豆腐 家常菜 滇菜 芭蕉叶裹着豆腐与肉末炭火烤制，叶香锁住汁水，外焦里嫩、香辣入味。 豆腐切厚块，小米辣、蒜末、香茅草、香菜剁碎，与肉末加盐拌匀成馅。 豆腐块码在泡软的芭蕉叶上，铺上馅料。 芭蕉叶包紧，用牙签封口。 放入烤箱 200℃ 烤 20 分钟，或炭火烤至叶面焦黄出香即可。 烤 辣 午餐 晚餐 老豆腐 猪肉末 小米辣 蒜末 香菜 香茅草 芭蕉叶 盐'),
('99ccb751-9c8f-5fdd-ab25-9b55ebf7cbaf', '包菜炒粉条', '保持', '通用', '🥬', '包菜脆甜、粉条弹韧吸汁，配肉末同炒，菜饭一体的家常主食菜。', '["干粉条温水泡发 20 分钟至软，剪成 15 厘米长段；包菜切粗丝。", "热锅放油，下肉末中火炒散至变色，加蒜末爆香。", "下包菜丝大火翻炒 2 分钟至断生。", "倒入粉条，加生抽、老抽和半碗水，中火翻炒 3 分钟至粉条吸汁入味即可。"]'::jsonb, '[{"name": "包菜", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干粉条", "quantity": "60", "quantityPrefix": null, "unit": "克", "note": "（泡发约 180 克）", "sourceText": null}, {"name": "瘦肉末", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "老抽", "quantity": "0.5", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "8", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['炒']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '390', '13', '59', '11', '3.3', '14.8', '2.8', NULL, 'A', NULL, '包菜炒粉条 保持 通用 包菜脆甜、粉条弹韧吸汁，配肉末同炒，菜饭一体的家常主食菜。 干粉条温水泡发 20 分钟至软，剪成 15 厘米长段；包菜切粗丝。 热锅放油，下肉末中火炒散至变色，加蒜末爆香。 下包菜丝大火翻炒 2 分钟至断生。 倒入粉条，加生抽、老抽和半碗水，中火翻炒 3 分钟至粉条吸汁入味即可。 炒 咸鲜 午餐 晚餐 包菜 干粉条 瘦肉末 蒜 生抽 老抽 食用油'),
('b45d7d16-940e-57fb-be36-75517455606b', '包菜炒鸡蛋粉丝', '家常菜', '通用', '🍽️', '', '["胡萝卜、包菜切丝备用", "粉丝先用冷水浸泡 1 小时，然后将粉丝放入锅中，加入开水烧至粉丝烫软捞出备用", "鸡蛋打入碗中，加入盐后搅拌 15 秒", "葱、蒜、辣椒切成小粒备用", "起锅烧油，倒入鸡蛋，打散炒熟盛出", "再倒入油，放入葱、蒜、干辣椒翻炒 8 秒", "下胡萝卜、包菜丝儿翻炒 30 秒", "放入粉丝", "放调料，生抽 15 ml，老抽 10 ml，蚝油 10 ml，盐 2 克", "放入之前炒好的鸡蛋，翻炒约 15 秒", "出锅摆盘"]'::jsonb, '[{"name": "包菜 半 颗", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "包菜 半 颗"}, {"name": "鸡蛋 2 个", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "鸡蛋 2 个"}, {"name": "粉丝 1 把", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "粉丝 1 把"}, {"name": "胡萝卜 半 根", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "胡萝卜 半 根"}, {"name": "菜籽油 20 ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "菜籽油 20 ml"}, {"name": "盐 2 g、生抽 15 ml、老抽 10 ml、蚝油 10 ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐 2 g、生抽 15 ml、老抽 10 ml、蚝油 10 ml"}, {"name": "葱 半 根、蒜瓣 2 片、干辣椒 5 根", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "葱 半 根、蒜瓣 2 片、干辣椒 5 根"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], 20, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'recipes/images/1a65efb5c3b641c0e393.jpg', 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/vegetable_dish/%E5%8C%85%E8%8F%9C%E7%82%92%E9%B8%A1%E8%9B%8B%E7%B2%89%E4%B8%9D/%E5%8C%85%E8%8F%9C%E7%82%92%E9%B8%A1%E8%9B%8B%E7%B2%89%E4%B8%9D.md', '包菜炒鸡蛋粉丝 家常菜 通用 胡萝卜、包菜切丝备用 粉丝先用冷水浸泡 1 小时，然后将粉丝放入锅中，加入开水烧至粉丝烫软捞出备用 鸡蛋打入碗中，加入盐后搅拌 15 秒 葱、蒜、辣椒切成小粒备用 起锅烧油，倒入鸡蛋，打散炒熟盛出 再倒入油，放入葱、蒜、干辣椒翻炒 8 秒 下胡萝卜、包菜丝儿翻炒 30 秒 放入粉丝 放调料，生抽 15 ml，老抽 10 ml，蚝油 10 ml，盐 2 克 放入之前炒好的鸡蛋，翻炒约 15 秒 出锅摆盘 午餐 晚餐 包菜 半 颗 鸡蛋 2 个 粉丝 1 把 胡萝卜 半 根 菜籽油 20 ml 盐 2 g、生抽 15 ml、老抽 10 ml、蚝油 10 ml 葱 半 根、蒜瓣 2 片、干辣椒 5 根'),
('c740280a-d767-55ef-82b5-247fea67e798', '北海道牛奶吐司', '烘焙', '通用', '🍞', '汤种法做出的日式吐司，奶香浓郁组织拉丝，空口吃都停不下来。', '["所有材料除黄油外混合，揉至扩展阶段加入黄油，继续揉至完全阶段能拉出薄膜。", "基础发酵至两倍大，排气分割成 3 份滚圆松弛 15 分钟。", "擀卷两次放入吐司盒，二次发酵至九分满。", "放入预热 170°C 烤箱烤 40 分钟，上色满意后盖锡纸。", "出炉脱模侧放晾凉，组织细腻拉丝，切片食用。"]'::jsonb, '[{"name": "高筋面粉", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "牛奶", "quantity": "190", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "淡奶油", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "细砂糖", "quantity": "40", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "盐", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "干酵母", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄油", "quantity": "25", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "奶粉", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['烘焙']::TEXT[], ARRAY['甜', '奶香']::TEXT[], ARRAY['早餐']::TEXT[], NULL, NULL, '60 片', '177', '5', '28', '5', '8', '46', '8', NULL, 'A', NULL, '北海道牛奶吐司 烘焙 通用 汤种法做出的日式吐司，奶香浓郁组织拉丝，空口吃都停不下来。 所有材料除黄油外混合，揉至扩展阶段加入黄油，继续揉至完全阶段能拉出薄膜。 基础发酵至两倍大，排气分割成 3 份滚圆松弛 15 分钟。 擀卷两次放入吐司盒，二次发酵至九分满。 放入预热 170°c 烤箱烤 40 分钟，上色满意后盖锡纸。 出炉脱模侧放晾凉，组织细腻拉丝，切片食用。 烘焙 甜 奶香 早餐 高筋面粉 牛奶 淡奶油 细砂糖 盐 干酵母 黄油 奶粉'),
('f60aca75-0ceb-5e36-b4c6-3843b3ac58a3', '千张结烧肉', '家常菜', '通用', '🎀', '千张结吸满红烧肉汁，咬下去爆汁，豆制品与肉香的完美组合。', '["五花肉切块，冷水下锅加料酒焯水 5 分钟，捞出洗净。", "锅中少油炒化冰糖，下五花肉翻炒上色，加生抽、老抽、姜片、八角炒香。", "倒入没过肉的热水，大火烧开转小火加盖炖 30 分钟。", "加入千张结继续炖 15 分钟，开盖大火收汁至浓稠即可。"]'::jsonb, '[{"name": "五花肉", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "千张结", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "冰糖", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "老抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "姜", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "八角", "quantity": "1", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}]'::jsonb, ARRAY['红烧']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '350 g', '693', '39', '25', '49', '11', '7', '14', NULL, 'A', NULL, '千张结烧肉 家常菜 通用 千张结吸满红烧肉汁，咬下去爆汁，豆制品与肉香的完美组合。 五花肉切块，冷水下锅加料酒焯水 5 分钟，捞出洗净。 锅中少油炒化冰糖，下五花肉翻炒上色，加生抽、老抽、姜片、八角炒香。 倒入没过肉的热水，大火烧开转小火加盖炖 30 分钟。 加入千张结继续炖 15 分钟，开盖大火收汁至浓稠即可。 红烧 咸鲜 午餐 晚餐 五花肉 千张结 冰糖 生抽 老抽 料酒 姜 八角'),
('6fb034cf-b1f5-50de-8f4e-6a6ad9774506', '南县龟肉', '家常菜', '湘菜', '🐢', '益阳南县滋补名菜，龟肉配当归枸杞慢炖，汤清味醇，肉嫩不腥。', '["乌龟宰杀处理干净，斩块焯水去腥，捞出冲洗。", "砂锅放足量清水，下龟肉、姜片、当归、料酒，大火烧开撇去浮沫。", "转小火炖 90 分钟，至龟肉软糯、汤汁浓白。", "下枸杞再炖 5 分钟，加盐、白胡椒粉调味即可。"]'::jsonb, '[{"name": "乌龟", "quantity": "1", "quantityPrefix": null, "unit": "只", "note": "（约 600 克）", "sourceText": null}, {"name": "当归", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "枸杞", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "1", "quantityPrefix": null, "unit": "块", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "盐", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}, {"name": "白胡椒粉", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}]'::jsonb, ARRAY['炖']::TEXT[], ARRAY['清淡']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '540', '52', '20', '28', '13', '5', '7', NULL, 'A', NULL, '南县龟肉 家常菜 湘菜 益阳南县滋补名菜，龟肉配当归枸杞慢炖，汤清味醇，肉嫩不腥。 乌龟宰杀处理干净，斩块焯水去腥，捞出冲洗。 砂锅放足量清水，下龟肉、姜片、当归、料酒，大火烧开撇去浮沫。 转小火炖 90 分钟，至龟肉软糯、汤汁浓白。 下枸杞再炖 5 分钟，加盐、白胡椒粉调味即可。 炖 清淡 午餐 晚餐 乌龟 当归 枸杞 姜 料酒 盐 白胡椒粉'),
('4110956d-e502-5a92-b041-c7e58432089c', '南派红烧肉', '家常菜', '通用', '🍽️', '', '["建议在此之前查看炒糖色教程", "猪五花肉先不切小块，切成能放入锅中的大块（约 5–6cm 宽）即可", "生姜切片（每片厚度约 3mm ）", "开水烧开", "凉水自来水即可", "小葱小葱白色的部分葱白切成小段（小葱最佳，大葱也可以）", "蒜中间切开，不要拍扁，否则难以捞出以至最后收汁时影响味道", "请将辅料分为两个\"预备包\"：", "- A包（去腥用）：2 片姜、2 段葱段。", "- B包（炖煮用）：剩下的 4 片姜、葱白、蒜瓣、花椒、八角、香叶，统一放入一个小碗中备用。", "凉水锅中放入五花肉大块，加入 20ml 料酒 与 A包（2 片姜、2 段葱段），煮 15 分钟去掉血腥，捞出来后洗干净；", "将焯过水的五花肉捞出，稍微放凉（不烫手即可），切成边长约 3cm × 3cm × 3cm 的正方体块（焯水后肉质收紧，此时切块比生肉时更容易且成品大小更均匀。3cm 切块最终成品约为 2.5cm，是最适宜入口且容易烧透的尺寸）", "另起锅炒糖色，注意：在此菜谱中，请采用其中提到的\"操作 2\"来制作，即在糖液起密集小泡时，迅速将 B包（生姜、葱白、蒜、花椒、八角、香叶）倒入锅中爆香。", "爆出香味后（约 5-10 秒内），先不要加开水，而是立刻将焯过水的五花肉倒入锅中大火翻炒，让肉块均匀裹上糖色并煸炒出油脂。待闻到肉香后，再倒入开水至没过全部肉，盖上锅盖，转中小火炖煮 50 分钟-60 分钟（高压锅则为 40 分钟）；", "加入 10ml 料酒；", "盖上锅盖煮至沸腾后，每隔 25 分钟打开盖子将浮在表面的油和沫捞出；", "当水的高度减至肉最高的高度与锅底高度的 3/5 时，转中火，并捞出除肉和水以外的所有辅料，开始收汁；", "打开锅盖，待汤汁快没有的时粘稠状出锅（切记不可收干）；"]'::jsonb, '[{"name": "猪五花肉：1000g（约 2 斤）。注：生肉烹饪后缩水脱脂严重，此分量最终出肉量约满足 2-3 人正常饭量。如仅 1 人食用，建议所有食材剂量减半。", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "猪五花肉：1000g（约 2 斤）。注：生肉烹饪后缩水脱脂严重，此分量最终出肉量约满足 2-3 人正常饭量。如仅 1 人食用，建议所有食材剂量减半。"}, {"name": "油：100-150ml，色拉油、猪油、花生油都可以", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "油：100-150ml，色拉油、猪油、花生油都可以"}, {"name": "姜： 6 片", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "姜： 6 片"}, {"name": "小葱：约 30g（3-4 根），葱白切段备用", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "小葱：约 30g（3-4 根），葱白切段备用"}, {"name": "大蒜：约 25g（5-6 瓣），中间切开备用", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "大蒜：约 25g（5-6 瓣），中间切开备用"}, {"name": "冰糖：50g（约大拇指甲盖大小的碎单晶冰糖 15 块）。如果上一步炒糖色已经使用了 50g，此处的 50g 为炖煮时二次调味使用，可根据对\"南派甜口\"的接受度调整至 30g。", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "冰糖：50g（约大拇指甲盖大小的碎单晶冰糖 15 块）。如果上一步炒糖色已经使用了 50g，此处的 50g 为炖煮时二次调味使用，可根据对\"南派甜口\"的接受度调整至 30g。"}, {"name": "白砂糖：30g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "白砂糖：30g"}, {"name": "老抽：15ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "老抽：15ml"}, {"name": "料酒：总量 30ml（其中 20ml 用于前期焯水去腥，10ml 用于后期炖煮提鲜）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "料酒：总量 30ml（其中 20ml 用于前期焯水去腥，10ml 用于后期炖煮提鲜）"}, {"name": "凉水：没过食材的量即可，看锅大小准备", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "凉水：没过食材的量即可，看锅大小准备"}, {"name": "开水：没过食材的量即可，看锅大小准备", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "开水：没过食材的量即可，看锅大小准备"}, {"name": "香叶：4 片", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "香叶：4 片"}, {"name": "八角：3 个", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "八角：3 个"}, {"name": "盐：2-3g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐：2-3g"}, {"name": "花椒：10g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "花椒：10g"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'recipes/images/373d56f2f32aba5c1867.jpg', 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/meat_dish/%E7%BA%A2%E7%83%A7%E8%82%89/%E5%8D%97%E6%B4%BE%E7%BA%A2%E7%83%A7%E8%82%89.md', '南派红烧肉 家常菜 通用 建议在此之前查看炒糖色教程 猪五花肉先不切小块，切成能放入锅中的大块（约 5–6cm 宽）即可 生姜切片（每片厚度约 3mm ） 开水烧开 凉水自来水即可 小葱小葱白色的部分葱白切成小段（小葱最佳，大葱也可以） 蒜中间切开，不要拍扁，否则难以捞出以至最后收汁时影响味道 请将辅料分为两个"预备包"： - a包（去腥用）：2 片姜、2 段葱段。 - b包（炖煮用）：剩下的 4 片姜、葱白、蒜瓣、花椒、八角、香叶，统一放入一个小碗中备用。 凉水锅中放入五花肉大块，加入 20ml 料酒 与 a包（2 片姜、2 段葱段），煮 15 分钟去掉血腥，捞出来后洗干净； 将焯过水的五花肉捞出，稍微放凉（不烫手即可），切成边长约 3cm × 3cm × 3cm 的正方体块（焯水后肉质收紧，此时切块比生肉时更容易且成品大小更均匀。3cm 切块最终成品约为 2.5cm，是最适宜入口且容易烧透的尺寸） 另起锅炒糖色，注意：在此菜谱中，请采用其中提到的"操作 2"来制作，即在糖液起密集小泡时，迅速将 b包（生姜、葱白、蒜、花椒、八角、香叶）倒入锅中爆香。 爆出香味后（约 5-10 秒内），先不要加开水，而是立刻将焯过水的五花肉倒入锅中大火翻炒，让肉块均匀裹上糖色并煸炒出油脂。待闻到肉香后，再倒入开水至没过全部肉，盖上锅盖，转中小火炖煮 50 分钟-60 分钟（高压锅则为 40 分钟）； 加入 10ml 料酒； 盖上锅盖煮至沸腾后，每隔 25 分钟打开盖子将浮在表面的油和沫捞出； 当水的高度减至肉最高的高度与锅底高度的 3/5 时，转中火，并捞出除肉和水以外的所有辅料，开始收汁； 打开锅盖，待汤汁快没有的时粘稠状出锅（切记不可收干）； 午餐 晚餐 猪五花肉：1000g（约 2 斤）。注：生肉烹饪后缩水脱脂严重，此分量最终出肉量约满足 2-3 人正常饭量。如仅 1 人食用，建议所有食材剂量减半。 油：100-150ml，色拉油、猪油、花生油都可以 姜： 6 片 小葱：约 30g（3-4 根），葱白切段备用 大蒜：约 25g（5-6 瓣），中间切开备用 冰糖：50g（约大拇指甲盖大小的碎单晶冰糖 15 块）。如果上一步炒糖色已经使用了 50g，此处的 50g 为炖煮时二次调味使用，可根据对"南派甜口"的接受度调整至 30g。 白砂糖：30g 老抽：15ml 料酒：总量 30ml（其中 20ml 用于前期焯水去腥，10ml 用于后期炖煮提鲜） 凉水：没过食材的量即可，看锅大小准备 开水：没过食材的量即可，看锅大小准备 香叶：4 片 八角：3 个 盐：2-3g 花椒：10g'),
('63aaaabe-e451-536c-9fed-12c48e1bdf59', '南煎肝', '家常菜', '闽菜', '🥘', '福州传统做法，猪肝先煎后烧，外焦里嫩，甜咸交织。', '["猪肝切薄片，用清水反复冲洗去血水，裹薄薄一层地瓜粉。", "热锅宽油，下猪肝片中火煎至两面微焦、边缘卷起，盛出。", "余油下洋葱丝、姜片炒香。", "白糖、香醋、生抽加两勺水调匀倒入，下猪肝烧 1 分钟至汁水收裹即可。"]'::jsonb, '[{"name": "猪肝", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "洋葱", "quantity": "0.5", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "姜片", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "白糖", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": "半", "sourceText": null}, {"name": "香醋", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "地瓜粉", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['煎']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '180 g', '274', '23', '14', '14', '13', '8', '8', NULL, 'A', NULL, '南煎肝 家常菜 闽菜 福州传统做法，猪肝先煎后烧，外焦里嫩，甜咸交织。 猪肝切薄片，用清水反复冲洗去血水，裹薄薄一层地瓜粉。 热锅宽油，下猪肝片中火煎至两面微焦、边缘卷起，盛出。 余油下洋葱丝、姜片炒香。 白糖、香醋、生抽加两勺水调匀倒入，下猪肝烧 1 分钟至汁水收裹即可。 煎 咸鲜 午餐 晚餐 猪肝 洋葱 姜片 白糖 香醋 生抽 地瓜粉'),
('7ccc48e9-ac4e-5432-b1cf-9f61b88e0912', '南瓜小米粥', '家常菜', '北方菜', '🎃', '小米配南瓜熬到金黄绵稠，养胃又暖身的家常粥。', '["小米淘洗，南瓜去皮切小丁，枸杞和葡萄干冲洗备用。", "锅中加水和小米，大火煮开转小火熬 15 分钟。", "下南瓜丁，继续小火熬 10 分钟至南瓜软烂。", "加冰糖、枸杞和葡萄干搅拌融化，关火焖 5 分钟即可。"]'::jsonb, '[{"name": "小米", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "南瓜", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "清水", "quantity": "500", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}, {"name": "冰糖", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "枸杞", "quantity": "3", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "葡萄干", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['熬粥']::TEXT[], ARRAY['甜']::TEXT[], ARRAY['早餐']::TEXT[], NULL, NULL, '600 g', '238', '5', '50', '2', '0.8', '8.3', '0.3', NULL, 'A', NULL, '南瓜小米粥 家常菜 北方菜 小米配南瓜熬到金黄绵稠，养胃又暖身的家常粥。 小米淘洗，南瓜去皮切小丁，枸杞和葡萄干冲洗备用。 锅中加水和小米，大火煮开转小火熬 15 分钟。 下南瓜丁，继续小火熬 10 分钟至南瓜软烂。 加冰糖、枸杞和葡萄干搅拌融化，关火焖 5 分钟即可。 熬粥 甜 早餐 小米 南瓜 清水 冰糖 枸杞 葡萄干'),
('8b85cc3a-c1c6-582a-a3ad-ff84ad22f917', '南瓜派', '烘焙', '通用', '🥧', '南瓜泥加蛋奶烤成绵密馅心，香料温暖，感恩节餐桌的秋日味道。', '["黄油与面粉搓成粗粒，加 20 克糖和 1 个蛋液揉成团，冷藏 30 分钟。", "塔皮擀开铺入派盘，叉孔后 180°C 烤 12 分钟定型。", "南瓜泥加剩余糖、鸡蛋、淡奶油和香料搅打顺滑成馅。", "馅料倒入派壳，放入预热 180°C 烤箱烤 35 分钟至凝固。", "晾凉后冷藏 1 小时，切块食用。"]'::jsonb, '[{"name": "南瓜泥", "quantity": "250", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "低筋面粉", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "黄油", "quantity": "70", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "细砂糖", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鸡蛋", "quantity": "2", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "淡奶油", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "肉桂粉", "quantity": "2", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜粉", "quantity": "1", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['烘焙']::TEXT[], ARRAY['甜']::TEXT[], ARRAY['早餐']::TEXT[], NULL, NULL, '100 块', '286', '6', '34', '14', '6', '34', '14', NULL, 'A', NULL, '南瓜派 烘焙 通用 南瓜泥加蛋奶烤成绵密馅心，香料温暖，感恩节餐桌的秋日味道。 黄油与面粉搓成粗粒，加 20 克糖和 1 个蛋液揉成团，冷藏 30 分钟。 塔皮擀开铺入派盘，叉孔后 180°c 烤 12 分钟定型。 南瓜泥加剩余糖、鸡蛋、淡奶油和香料搅打顺滑成馅。 馅料倒入派壳，放入预热 180°c 烤箱烤 35 分钟至凝固。 晾凉后冷藏 1 小时，切块食用。 烘焙 甜 早餐 南瓜泥 低筋面粉 黄油 细砂糖 鸡蛋 淡奶油 肉桂粉 姜粉'),
('6f74caba-0fe3-5488-87bc-951a9f9e3dc2', '南瓜浓汤', '营养', '通用', '🎃', '南瓜天然香甜打成浓汤，加牛奶增稠，暖胃又补胡萝卜素。', '["南瓜去皮切薄片，洋葱切丝。", "锅中放橄榄油，炒软洋葱，下南瓜片翻炒 2 分钟。", "加半碗水没过南瓜，中火煮 12 分钟至软烂。", "倒入牛奶，用料理机打成细腻浓汤，加盐和黑胡椒调味即可。"]'::jsonb, '[{"name": "南瓜", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "牛奶", "quantity": "150", "quantityPrefix": null, "unit": "毫升", "note": null, "sourceText": null}, {"name": "洋葱", "quantity": "0.25", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "橄榄油", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "南瓜籽", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "海盐、黑胡椒", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['煮']::TEXT[], ARRAY['甜', '奶香']::TEXT[], ARRAY['晚餐']::TEXT[], NULL, NULL, '300 g', '157', '4', '24', '5', '1.2', '8', '1.8', NULL, 'A', NULL, '南瓜浓汤 营养 通用 南瓜天然香甜打成浓汤，加牛奶增稠，暖胃又补胡萝卜素。 南瓜去皮切薄片，洋葱切丝。 锅中放橄榄油，炒软洋葱，下南瓜片翻炒 2 分钟。 加半碗水没过南瓜，中火煮 12 分钟至软烂。 倒入牛奶，用料理机打成细腻浓汤，加盐和黑胡椒调味即可。 煮 甜 奶香 晚餐 南瓜 牛奶 洋葱 橄榄油 南瓜籽 海盐、黑胡椒'),
('aa87740b-12fd-5478-b32b-ec605afd9baf', '南瓜炖排骨', '保持', '北方菜', '🍖', '南瓜绵甜吸汁，排骨软烂，咸甜交织的秋季家常炖菜。', '["排骨冷水下锅加料酒焯水 3 分钟，捞出洗净；南瓜去皮切块。", "锅中加两碗水，下排骨、姜片、生抽和老抽，大火烧开转小火炖 20 分钟。", "下南瓜块，再炖 10 分钟至南瓜软糯。", "大火收汁至浓稠，撒葱花出锅。"]'::jsonb, '[{"name": "猪肋排", "quantity": "130", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "南瓜", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "姜", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "小葱", "quantity": "1", "quantityPrefix": null, "unit": "根", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "老抽", "quantity": "0.5", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['炖']::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '400 g', '415', '23', '18', '28', '5.8', '4.5', '7', NULL, 'A', NULL, '南瓜炖排骨 保持 北方菜 南瓜绵甜吸汁，排骨软烂，咸甜交织的秋季家常炖菜。 排骨冷水下锅加料酒焯水 3 分钟，捞出洗净；南瓜去皮切块。 锅中加两碗水，下排骨、姜片、生抽和老抽，大火烧开转小火炖 20 分钟。 下南瓜块，再炖 10 分钟至南瓜软糯。 大火收汁至浓稠，撒葱花出锅。 炖 咸鲜 午餐 晚餐 猪肋排 南瓜 姜 小葱 生抽 老抽 料酒'),
('dc163120-18ab-5394-bb6a-7f160ccaca12', '南瓜蒸排骨', '保持', '粤菜', '🍖', '排骨豆豉腌渍入味，贝贝南瓜垫底吸饱肉汁与油脂，软烂鲜香且不上火。', '["猪小排冷水浸泡出血水沥干，加蒜末、豆豉、生抽、料酒、淀粉抓匀腌 20 分钟。", "贝贝南瓜去籽切厚块，平铺在蒸盘底部。", "腌好的排骨平铺在南瓜上。", "蒸锅上汽后大火蒸 25 分钟，关火焖 2 分钟，出锅撒葱花。"]'::jsonb, '[{"name": "猪小排", "quantity": "180", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "贝贝南瓜", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "蒜", "quantity": "3", "quantityPrefix": null, "unit": "瓣", "note": null, "sourceText": null}, {"name": "豆豉", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "淀粉", "quantity": "5", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "4", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}]'::jsonb, ARRAY['蒸']::TEXT[], ARRAY['鲜香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '360 g', '472', '31', '24', '28', '8.6', '6.7', '7.8', NULL, 'A', NULL, '南瓜蒸排骨 保持 粤菜 排骨豆豉腌渍入味，贝贝南瓜垫底吸饱肉汁与油脂，软烂鲜香且不上火。 猪小排冷水浸泡出血水沥干，加蒜末、豆豉、生抽、料酒、淀粉抓匀腌 20 分钟。 贝贝南瓜去籽切厚块，平铺在蒸盘底部。 腌好的排骨平铺在南瓜上。 蒸锅上汽后大火蒸 25 分钟，关火焖 2 分钟，出锅撒葱花。 蒸 鲜香 午餐 晚餐 猪小排 贝贝南瓜 蒜 豆豉 生抽 料酒 淀粉 食用油'),
('71f251c6-eb3f-568b-b329-c303081db89a', '南瓜饼', '家常菜', '通用', '🎃', '南瓜泥和糯米粉炸的小饼，外酥内糯，甜丝丝的童年味。', '["南瓜去皮切片，蒸 15 分钟压成泥。", "南瓜泥加糯米粉、面粉和白糖揉成团。", "分成小剂子按扁成饼，两面沾白芝麻。", "平底锅下油，中小火每面煎 3 分钟至金黄鼓起。", "出锅控油，趁热食用。"]'::jsonb, '[{"name": "南瓜", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "糯米粉", "quantity": "50", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "中筋面粉", "quantity": "20", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "白糖", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "食用油", "quantity": "6", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "白芝麻", "quantity": null, "quantityPrefix": null, "unit": "少许", "note": null, "sourceText": null}]'::jsonb, ARRAY['煎']::TEXT[], ARRAY['甜']::TEXT[], ARRAY['早餐']::TEXT[], NULL, NULL, '230 g', '378', '5', '76', '6', '2.2', '33', '2.6', NULL, 'A', NULL, '南瓜饼 家常菜 通用 南瓜泥和糯米粉炸的小饼，外酥内糯，甜丝丝的童年味。 南瓜去皮切片，蒸 15 分钟压成泥。 南瓜泥加糯米粉、面粉和白糖揉成团。 分成小剂子按扁成饼，两面沾白芝麻。 平底锅下油，中小火每面煎 3 分钟至金黄鼓起。 出锅控油，趁热食用。 煎 甜 早餐 南瓜 糯米粉 中筋面粉 白糖 食用油 白芝麻'),
('6b423636-e166-5a66-bf12-538d1a348a35', '南瓜鹰嘴豆沙拉', '营养', '通用', '🥗', '烤南瓜自带甜糯，鹰嘴豆是优质植物蛋白，芝麻酱汁香浓营养足。', '["南瓜去皮切块，拌少许橄榄油和黑胡椒，200℃ 烤 20 分钟至软。", "鹰嘴豆提前泡发煮熟（或用水煮罐头），沥干备用。", "生菜撕片、圣女果对半切，与南瓜、鹰嘴豆装盘。", "芝麻酱加两勺温水、柠檬汁和盐调稀，淋上拌匀。"]'::jsonb, '[{"name": "南瓜", "quantity": "200", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "鹰嘴豆（熟）", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "生菜", "quantity": "100", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "圣女果", "quantity": "8", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "芝麻酱", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "柠檬汁", "quantity": null, "quantityPrefix": null, "unit": "适量", "note": null, "sourceText": null}]'::jsonb, ARRAY['烤']::TEXT[], ARRAY['甜', '酱香']::TEXT[], ARRAY['午餐']::TEXT[], NULL, NULL, '500 g', '316', '13', '48', '8', '2.6', '9.6', '1.6', NULL, 'A', NULL, '南瓜鹰嘴豆沙拉 营养 通用 烤南瓜自带甜糯，鹰嘴豆是优质植物蛋白，芝麻酱汁香浓营养足。 南瓜去皮切块，拌少许橄榄油和黑胡椒，200℃ 烤 20 分钟至软。 鹰嘴豆提前泡发煮熟（或用水煮罐头），沥干备用。 生菜撕片、圣女果对半切，与南瓜、鹰嘴豆装盘。 芝麻酱加两勺温水、柠檬汁和盐调稀，淋上拌匀。 烤 甜 酱香 午餐 南瓜 鹰嘴豆（熟） 生菜 圣女果 芝麻酱 柠檬汁'),
('1b58af36-b97b-573e-b1ab-950381d20ee8', '卤大排', '家常菜', '徽菜', '🍖', '大排先炸后卤，肉质紧实带卤香，凉热都好吃。', '["大排用刀背拍松，加料酒、姜片腌 15 分钟。", "大排拍一层薄淀粉，下六成热油中火炸 3 分钟至两面金黄。", "锅中加水、生抽、老抽、冰糖、八角、桂皮烧开成卤汤。", "下大排小火卤 15 分钟，关火焖 10 分钟入味即可。"]'::jsonb, '[{"name": "猪大排", "quantity": "400", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "3", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "老抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "冰糖", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "八角", "quantity": "2", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "桂皮", "quantity": "1", "quantityPrefix": null, "unit": "小段", "note": null, "sourceText": null}, {"name": "姜", "quantity": "4", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['炸', '卤']::TEXT[], ARRAY['五香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '528', '42', '9', '36', '14', '3', '12', NULL, 'A', NULL, '卤大排 家常菜 徽菜 大排先炸后卤，肉质紧实带卤香，凉热都好吃。 大排用刀背拍松，加料酒、姜片腌 15 分钟。 大排拍一层薄淀粉，下六成热油中火炸 3 分钟至两面金黄。 锅中加水、生抽、老抽、冰糖、八角、桂皮烧开成卤汤。 下大排小火卤 15 分钟，关火焖 10 分钟入味即可。 炸 卤 五香 午餐 晚餐 猪大排 生抽 老抽 冰糖 八角 桂皮 姜 料酒'),
('318e4643-73ea-599b-bcf4-cd998558737f', '卤方干', '家常菜', '通用', '🧈', '白干方片入五香卤汤浸煮，豆香与卤香交织，冷碟热吃两相宜。', '["白干切 1 厘米厚的大片，用牙签扎些小孔便于入味。", "锅中加水、生抽、老抽、冰糖、八角、桂皮、花椒、姜片烧开。", "下白干小火卤 10 分钟，关火浸泡 30 分钟以上。", "捞出切片装盘，可淋少许卤汁。"]'::jsonb, '[{"name": "白干", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "3", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "老抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "冰糖", "quantity": "10", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "八角", "quantity": "2", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "桂皮", "quantity": "1", "quantityPrefix": null, "unit": "小段", "note": null, "sourceText": null}, {"name": "花椒", "quantity": "1", "quantityPrefix": null, "unit": "小勺", "note": null, "sourceText": null}, {"name": "姜", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}]'::jsonb, ARRAY['卤']::TEXT[], ARRAY['五香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '250 g', '322', '30', '10', '18', '12', '4', '7', NULL, 'A', NULL, '卤方干 家常菜 通用 白干方片入五香卤汤浸煮，豆香与卤香交织，冷碟热吃两相宜。 白干切 1 厘米厚的大片，用牙签扎些小孔便于入味。 锅中加水、生抽、老抽、冰糖、八角、桂皮、花椒、姜片烧开。 下白干小火卤 10 分钟，关火浸泡 30 分钟以上。 捞出切片装盘，可淋少许卤汁。 卤 五香 午餐 晚餐 白干 生抽 老抽 冰糖 八角 桂皮 花椒 姜'),
('61926583-fcb3-5d75-8400-76b913f7baa8', '卤牛肉', '增肌', '通用', '🥩', '牛腱卤制后切片，高蛋白低脂肪，增肌期常备的冷盘蛋白质。', '["牛腱子冷水浸泡 1 小时去血水，冷水下锅加料酒焯水 5 分钟捞出。", "锅中加足量水，放入牛腱、八角、桂皮、香叶、姜片和生抽老抽。", "大火烧开转小火，加盖卤 1.5 小时至筷子能扎透。", "关火浸泡 2 小时入味，捞出放凉切片食用。"]'::jsonb, '[{"name": "牛腱子", "quantity": "300", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "八角", "quantity": "2", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "桂皮", "quantity": "1", "quantityPrefix": null, "unit": "小段", "note": null, "sourceText": null}, {"name": "香叶", "quantity": "2", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "姜", "quantity": "3", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "3", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "老抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['卤']::TEXT[], ARRAY['五香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '180 g', '259', '47', '2', '7', '26.1', '1.1', '3.9', NULL, 'A', NULL, '卤牛肉 增肌 通用 牛腱卤制后切片，高蛋白低脂肪，增肌期常备的冷盘蛋白质。 牛腱子冷水浸泡 1 小时去血水，冷水下锅加料酒焯水 5 分钟捞出。 锅中加足量水，放入牛腱、八角、桂皮、香叶、姜片和生抽老抽。 大火烧开转小火，加盖卤 1.5 小时至筷子能扎透。 关火浸泡 2 小时入味，捞出放凉切片食用。 卤 五香 午餐 晚餐 牛腱子 八角 桂皮 香叶 姜 生抽 老抽 料酒'),
('36920bf0-d820-54ad-a609-97ba08a7c89e', '卤牛肉糙米碗', '增肌', '通用', '🍛', '卤牛肉高蛋白低脂肪，配糙米和卤蛋，增肌期的经典一碗端。', '["卤牛肉切成厚片，卤蛋对半切开，西兰花掰小朵焯水 1 分钟。", "糙米饭提前煮好，盛入碗中压实。", "依次铺上卤牛肉片、卤蛋和西兰花。", "淋 2 勺卤汁，撒少许白芝麻即可。"]'::jsonb, '[{"name": "卤牛肉", "quantity": "150", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "糙米饭", "quantity": "220", "quantityPrefix": null, "unit": "克", "note": "（熟）", "sourceText": null}, {"name": "卤蛋", "quantity": "1", "quantityPrefix": null, "unit": "个", "note": null, "sourceText": null}, {"name": "西兰花", "quantity": "80", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "卤汁", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, '{}'::TEXT[], ARRAY['咸鲜']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '500 g', '660', '58', '62', '20', '11.6', '12.4', '4', NULL, 'A', NULL, '卤牛肉糙米碗 增肌 通用 卤牛肉高蛋白低脂肪，配糙米和卤蛋，增肌期的经典一碗端。 卤牛肉切成厚片，卤蛋对半切开，西兰花掰小朵焯水 1 分钟。 糙米饭提前煮好，盛入碗中压实。 依次铺上卤牛肉片、卤蛋和西兰花。 淋 2 勺卤汁，撒少许白芝麻即可。 咸鲜 午餐 晚餐 卤牛肉 糙米饭 卤蛋 西兰花 卤汁'),
('e955ce56-3ae0-51a6-b582-effac5211a6a', '卤翅根', '家常菜', '通用', '🍗', '鸡翅根焯水后入五香卤汤慢卤，皮滑肉嫩，啃着过瘾。', '["翅根冷水下锅加料酒焯水，捞出洗净。", "锅中加水、生抽、老抽、冰糖、八角、桂皮、姜片烧开成卤汤。", "下翅根大火烧开，转小火卤 20 分钟。", "关火再焖 10 分钟入味，捞出即可。"]'::jsonb, '[{"name": "鸡翅根", "quantity": "500", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "生抽", "quantity": "3", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "老抽", "quantity": "1", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}, {"name": "冰糖", "quantity": "15", "quantityPrefix": null, "unit": "克", "note": null, "sourceText": null}, {"name": "八角", "quantity": "2", "quantityPrefix": null, "unit": "颗", "note": null, "sourceText": null}, {"name": "桂皮", "quantity": "1", "quantityPrefix": null, "unit": "小段", "note": null, "sourceText": null}, {"name": "姜", "quantity": "4", "quantityPrefix": null, "unit": "片", "note": null, "sourceText": null}, {"name": "料酒", "quantity": "2", "quantityPrefix": null, "unit": "勺", "note": null, "sourceText": null}]'::jsonb, ARRAY['卤']::TEXT[], ARRAY['五香']::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, '300 g', '486', '48', '6', '30', '16', '2', '10', NULL, 'A', NULL, '卤翅根 家常菜 通用 鸡翅根焯水后入五香卤汤慢卤，皮滑肉嫩，啃着过瘾。 翅根冷水下锅加料酒焯水，捞出洗净。 锅中加水、生抽、老抽、冰糖、八角、桂皮、姜片烧开成卤汤。 下翅根大火烧开，转小火卤 20 分钟。 关火再焖 10 分钟入味，捞出即可。 卤 五香 午餐 晚餐 鸡翅根 生抽 老抽 冰糖 八角 桂皮 姜 料酒'),
('287c2369-fb93-5a3f-a948-8b66ae33cafd', '卤菜', '家常菜', '通用', '🍽️', '', '["建议在此之前查看炒糖色教程", "牛腱子提前浸泡在冷水中 3 小时以上，去除血水", "准备卤水", "准备糖色：锅中加入 30g 白糖，小火加热至糖完全融化并呈现棕褐色，加入 150ml 热水，搅拌均匀备用", "将洋葱切块，生姜和大蒜拍碎，干辣椒掰断备用", "在锅中加入足量的水，放入卤料包、洋葱、生姜、大蒜、干辣椒，大火烧开", "加入黄豆酱、豆瓣酱、蚝油和南腐乳各 15ml，搅拌均匀", "倒入准备好的糖色，混合均匀", "加入生抽 120ml 和老抽 60ml，搅拌均匀", "加入 10-15g 盐调味", "倒入 1 罐啤酒(330ml)，再次烧开", "卤制牛肉", "牛腱子放入锅中焯水 2-3 分钟，捞出并用热水冲洗干净表面的浮沫", "将焯水后的牛腱子放入已烧开的卤水中，确保卤水没过所有肉类", "盖上高压锅盖，上汽后继续烹饪 25-30 分钟", "烹饪完成后，不要开盖保温，自然冷却并浸泡一晚上（这样会更入味）", "将卤好的肉取出放入冰箱冷藏，使其成型", "食用前取出切片，可直接食用或凉拌", "保存卤水", "卤水重复使用方法：每次卤完肉后，将卤水过滤，去除所有固体内容物，重新烧开杀菌，冷却后可冷藏或冷冻保存。使用时按原配方比例重新添加调味料。（加水量根据卤水使用情况而定）", "卤水保存得当可以使用很长时间，且越老越香。", "重要提示：如卤制素菜，必须另取一部分卤水，单独使用，并且卤制完素菜的卤水不可重复使用。", "凉拌调料", "将蒜末、葱花、白芝麻、辣椒粉按 1:1:1:1 的比例混合，依个人口味加小米辣，热植物油中加入少量芝麻油或藤椒油，分次泼在调料上，再加入生抽、醋、蚝油各 10ml，5ml 糖，味精/鸡精，最后 15ml 卤汤混合均匀。", "凉拌时可搭配拍黄瓜、木耳、油炸花生米、香菜等配菜。"]'::jsonb, '[{"name": "卤料包 1 包（约 10g）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "卤料包 1 包（约 10g）"}, {"name": "黄豆酱 15ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "黄豆酱 15ml"}, {"name": "豆瓣酱 15ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "豆瓣酱 15ml"}, {"name": "蚝油 15ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "蚝油 15ml"}, {"name": "南腐乳 15ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "南腐乳 15ml"}, {"name": "洋葱 半个（约 100g）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "洋葱 半个（约 100g）"}, {"name": "生姜 30g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "生姜 30g"}, {"name": "大蒜 40g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "大蒜 40g"}, {"name": "干辣椒 10g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "干辣椒 10g"}, {"name": "生抽 120ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "生抽 120ml"}, {"name": "老抽 60ml", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "老抽 60ml"}, {"name": "盐 10-15g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "盐 10-15g"}, {"name": "白糖 30g（用于熬糖色）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "白糖 30g（用于熬糖色）"}, {"name": "啤酒 1 罐(330ml)", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "啤酒 1 罐(330ml)"}, {"name": "牛腱子 500g", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "牛腱子 500g"}, {"name": "清水 足量（需要没过所有肉类）", "quantity": null, "quantityPrefix": null, "unit": null, "note": null, "sourceText": "清水 足量（需要没过所有肉类）"}]'::jsonb, '{}'::TEXT[], '{}'::TEXT[], ARRAY['午餐', '晚餐']::TEXT[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'recipes/images/ad28ce802c922811e21e.jpg', 'BD', 'https://github.com/Anduin2017/HowToCook/blob/58c1b9af7900a9489c340bca39ef94a9a62314b1/dishes/meat_dish/%E5%8D%A4%E8%8F%9C/%E5%8D%A4%E8%8F%9C.md', '卤菜 家常菜 通用 建议在此之前查看炒糖色教程 牛腱子提前浸泡在冷水中 3 小时以上，去除血水 准备卤水 准备糖色：锅中加入 30g 白糖，小火加热至糖完全融化并呈现棕褐色，加入 150ml 热水，搅拌均匀备用 将洋葱切块，生姜和大蒜拍碎，干辣椒掰断备用 在锅中加入足量的水，放入卤料包、洋葱、生姜、大蒜、干辣椒，大火烧开 加入黄豆酱、豆瓣酱、蚝油和南腐乳各 15ml，搅拌均匀 倒入准备好的糖色，混合均匀 加入生抽 120ml 和老抽 60ml，搅拌均匀 加入 10-15g 盐调味 倒入 1 罐啤酒(330ml)，再次烧开 卤制牛肉 牛腱子放入锅中焯水 2-3 分钟，捞出并用热水冲洗干净表面的浮沫 将焯水后的牛腱子放入已烧开的卤水中，确保卤水没过所有肉类 盖上高压锅盖，上汽后继续烹饪 25-30 分钟 烹饪完成后，不要开盖保温，自然冷却并浸泡一晚上（这样会更入味） 将卤好的肉取出放入冰箱冷藏，使其成型 食用前取出切片，可直接食用或凉拌 保存卤水 卤水重复使用方法：每次卤完肉后，将卤水过滤，去除所有固体内容物，重新烧开杀菌，冷却后可冷藏或冷冻保存。使用时按原配方比例重新添加调味料。（加水量根据卤水使用情况而定） 卤水保存得当可以使用很长时间，且越老越香。 重要提示：如卤制素菜，必须另取一部分卤水，单独使用，并且卤制完素菜的卤水不可重复使用。 凉拌调料 将蒜末、葱花、白芝麻、辣椒粉按 1:1:1:1 的比例混合，依个人口味加小米辣，热植物油中加入少量芝麻油或藤椒油，分次泼在调料上，再加入生抽、醋、蚝油各 10ml，5ml 糖，味精/鸡精，最后 15ml 卤汤混合均匀。 凉拌时可搭配拍黄瓜、木耳、油炸花生米、香菜等配菜。 午餐 晚餐 卤料包 1 包（约 10g） 黄豆酱 15ml 豆瓣酱 15ml 蚝油 15ml 南腐乳 15ml 洋葱 半个（约 100g） 生姜 30g 大蒜 40g 干辣椒 10g 生抽 120ml 老抽 60ml 盐 10-15g 白糖 30g（用于熬糖色） 啤酒 1 罐(330ml) 牛腱子 500g 清水 足量（需要没过所有肉类）');
